o4=A.ay(s2,A.a([A.aA(A.a(["\ub300\uc218 > \uc9c0\uc218 > \uc9c0\uc218\uc758\ud655\uc7a5 > \uc815\uc218\uc9c0\uc218 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uc9c0\uc218\ubc95\uce59\uc740 \uc790\uc5f0\uc218 \ubc94\uc704\uc5d0\uc11c \uc815\uc758\ub41c \uac1c\ub150\uc744 \uc815\uc218 \uc804\uccb4\ub85c \ud655\uc7a5\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. 0\uc774 \uc544\ub2cc \uc2e4\uc218 $a$\uc5d0 \ub300\ud558\uc5ec $a^0 = 1$\ub85c \uc815\uc758\ud558\uace0, \uc790\uc5f0\uc218 $n$\uc5d0 \ub300\ud558\uc5ec $a^{-n} = \\frac{1}{a^n}$\uc73c\ub85c \uc815\uc758\ud569\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc815\uc758\ub97c \ub3c4\uc785\ud558\uba74, \uc9c0\uc218\uac00 \uc74c\uc218\uc774\uac70\ub098 0\uc778 \uacbd\uc6b0\uc5d0\ub3c4 \uc790\uc5f0\uc218\uc5d0\uc11c \uc131\ub9bd\ud558\ub358 \uc9c0\uc218\ubc95\uce59\uc774 \uadf8\ub300\ub85c \uc720\uc9c0\ub418\uc5b4 \uacc4\uc0b0\uc758 \ud3b8\ub9ac\ud568\uc744 \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc815\uc218\uc9c0\uc218\uc5d0\uc11c \uc131\ub9bd\ud558\ub294 \uc9c0\uc218\ubc95\uce59\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $a, b$\uac00 0\uc774 \uc544\ub2cc \uc2e4\uc218\uc774\uace0 $m, n$\uc774 \uc815\uc218\uc77c \ub54c, \uccab\uc9f8\ub85c $a^m \\times a^n = a^{m+n}$\uc774 \uc131\ub9bd\ud569\ub2c8\ub2e4. \ub458\uc9f8\ub85c $(a^m)^n = a^{mn}$\uc774\uba70, \uc14b\uc9f8\ub85c $(ab)^n = a^n b^n$\uc774 \uc131\ub9bd\ud569\ub2c8\ub2e4. \ub610\ud55c \ub098\ub217\uc148\uc5d0 \ub300\ud574\uc11c\ub294 $a^m \\div a^n = a^{m-n}$\uc774 \uc131\ub9bd\ud558\ub294\ub370, \uc774\ub294 \uc9c0\uc218\uac00 \uc74c\uc218\uc77c \ub54c\ub3c4 \uc77c\uad00\ub418\uac8c \uc801\uc6a9\ub429\ub2c8\ub2e4.","\uc608\ub97c \ub4e4\uc5b4, $2^{-3}$\uc740 \uc815\uc758\uc5d0 \ub530\ub77c $\\frac{1}{2^3} = \\frac{1}{8}$\uc774 \ub429\ub2c8\ub2e4. \ub610\ud55c $5^0 = 1$\uacfc \uac19\uc774 \uc5b4\ub5a0\ud55c 0\uc774 \uc544\ub2cc \uc218\uc758 0\uc81c\uacf1\uc740 \ud56d\uc0c1 1\uc774\ub77c\ub294 \uc131\uc9c8\uc740 \ub9e4\uc6b0 \uc911\uc694\ud569\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc815\uc218\uc9c0\uc218\uc758 \ud655\uc7a5\uc740 \ubcf5\uc7a1\ud55c \ubd84\uc218 \ud615\ud0dc\uc758 \uc2dd\uc744 \uc9c0\uc218 \ud615\ud0dc\uc758 \uacf1\uc148\uc73c\ub85c \uac04\ub2e8\ud788 \ud45c\ud604\ud560 \uc218 \uc788\uac8c \ud574\uc8fc\uc5b4, \uc774\ud6c4 \ubc30\uc6b0\uac8c \ub420 \ub85c\uadf8\ub098 \ud568\uc218 \ub2e8\uc6d0\uc758 \uae30\ucd08\uac00 \ub429\ub2c8\ub2e4.","\uc774\uc81c \uc608\uc81c \ubb38\uc81c\ub97c \ud480\uc5b4\ubd05\uc2dc\ub2e4. \ubb38\uc81c: '$2^5 \\div 2^7$\uc744 \uacc4\uc0b0\ud558\uace0, \uadf8 \uacb0\uacfc\ub97c \uc815\uc218\uc9c0\uc218 \ud615\ud0dc\ub85c \ub098\ud0c0\ub0b4\uc2dc\uc624.' \uc774 \ubb38\uc81c\ub294 \uc9c0\uc218\ubc95\uce59 $a^m \\div a^n = a^{m-n}$\uc744 \ud65c\uc6a9\ud558\uc5ec \ud574\uacb0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubc11\uc774 2\ub85c \uac19\uc73c\ubbc0\ub85c \uc9c0\uc218\ub07c\ub9ac \ube7c\uc8fc\uba74 \ub429\ub2c8\ub2e4.","\ub2e8\uacc4\ubcc4 \ud480\uc774\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uc9c0\uc218\ubc95\uce59\uc744 \uc801\uc6a9\ud558\uba74 $2^5 \\div 2^7 = 2^{5-7}$\uc774 \ub429\ub2c8\ub2e4. \uc774\ub97c \uacc4\uc0b0\ud558\uba74 $2^{-2}$\uac00 \ub429\ub2c8\ub2e4. \uc815\uc758\uc5d0 \ub530\ub77c $2^{-2} = \\frac{1}{2^2} = \\frac{1}{4}$\uc774\ubbc0\ub85c, \ucd5c\uc885\uc801\uc778 \ub2f5\uc740 $2^{-2}$ \ub610\ub294 $\\frac{1}{4}$\uc785\ub2c8\ub2e4.","\ub610 \ub2e4\ub978 \uc608\uc81c\ub85c $(3^2)^{-1} \\times 3^4$\ub97c \uacc4\uc0b0\ud574 \ubd05\uc2dc\ub2e4. \uba3c\uc800 \uad04\ud638 \uc548\uc758 \uc9c0\uc218\ubc95\uce59 $(a^m)^n = a^{mn}$\uc744 \uc801\uc6a9\ud558\uba74 $(3^2)^{-1} = 3^{2 \\times (-1)} = 3^{-2}$\uac00 \ub429\ub2c8\ub2e4. \uc774\uc81c $3^{-2} \\times 3^4$\ub97c \uacc4\uc0b0\ud558\uba74 \uc9c0\uc218\ubc95\uce59 $a^m \\times a^n = a^{m+n}$\uc5d0 \uc758\ud574 $3^{-2+4} = 3^2 = 9$\uac00 \ub428\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),af2,B.r)],ai2),af2,B.r)],ai3),s3,s3,s3,s3,"concept_\uc815\uc218\uc9c0\uc218",0,"",1,s3,B.n,"\ub300\uc218 > \uc9c0\uc218 > \uc9c0\uc218\uc758\ud655\uc7a5 > \uc815\uc218\uc9c0\uc218",o4,af2,s3)
o5=A.a(["\uacf5\ud1b5\uc218\ud5591","\uc774\ucc28\ud568\uc218","\uc774\ucc28\ud568\uc218\uc758\ucd5c\ub300\ucd5c\uc18c","\ucd5c\uc19f\uac12(\uc774\ucc28\ud568\uc218)"],ai0)
o5=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5591 > \uc774\ucc28\ud568\uc218 > \uc774\ucc28\ud568\uc218\uc758\ucd5c\ub300\ucd5c\uc18c > \ucd5c\uc19f\uac12(\uc774\ucc28\ud568\uc218) \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uc774\ucc28\ud568\uc218\uc758 \ucd5c\uc19f\uac12\uc740 \uadf8\ub798\ud504\uc758 \ubaa8\uc591\uc5d0 \ub530\ub77c \uacb0\uc815\ub429\ub2c8\ub2e4. \uc774\ucc28\ud568\uc218 $y = ax^2 + bx + c$ ($a \\neq 0$)\uc758 \uadf8\ub798\ud504\ub294 \ud3ec\ubb3c\uc120 \ubaa8\uc591\uc778\ub370, $a > 0$\uc77c \ub54c \uadf8\ub798\ud504\ub294 \uc544\ub798\ub85c \ubcfc\ub85d\ud55c \ubaa8\uc591\uc774 \ub429\ub2c8\ub2e4. \uc774\ub54c \uadf8\ub798\ud504\uc758 \uac00\uc7a5 \ub0ae\uc740 \uc9c0\uc810\uc778 \uaf2d\uc9d3\uc810\uc5d0\uc11c \ud568\uc22b\uac12\uc740 \ucd5c\uc19f\uac12\uc744 \uac00\uc9c0\uba70, \ubc18\ub300\ub85c $a < 0$\uc77c \ub54c\ub294 \uc704\ub85c \ubcfc\ub85d\ud558\uc5ec \ucd5c\ub313\uac12\ub9cc \uc874\uc7ac\ud558\uace0 \ucd5c\uc19f\uac12\uc740 \uc815\ud560 \uc218 \uc5c6\uac8c \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc774\ucc28\ud568\uc218\uc758 \ucd5c\uc19f\uac12\uc744 \uad6c\ud558\ub824\uba74 \uba3c\uc800 \uadf8\ub798\ud504\uac00 \uc544\ub798\ub85c \ubcfc\ub85d\ud55c\uc9c0 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc774\ucc28\ud568\uc218\uc758 \ucd5c\uc19f\uac12\uc744 \uad6c\ud558\uae30 \uc704\ud574\uc11c\ub294 \uc8fc\uc5b4\uc9c4 \uc2dd\uc744 \uc644\uc804\uc81c\uacf1\uc2dd \uaf34\uc778 $$y = a(x - p)^2 + q$$ \ud615\ud0dc\ub85c \ubcc0\ud615\ud574\uc57c \ud569\ub2c8\ub2e4. \uc5ec\uae30\uc11c $(p, q)$\ub294 \ud3ec\ubb3c\uc120\uc758 \uaf2d\uc9d3\uc810 \uc88c\ud45c\ub97c \uc758\ubbf8\ud569\ub2c8\ub2e4. $a > 0$\uc77c \ub54c, $(x - p)^2$\uc740 \ud56d\uc0c1 $0$ \uc774\uc0c1\uc758 \uac12\uc744 \uac00\uc9c0\ubbc0\ub85c, $x = p$\uc77c \ub54c \uc804\uccb4 \uc2dd\uc758 \uac12\uc740 \uac00\uc7a5 \uc791\uc740 \uac12\uc778 $q$\uac00 \ub429\ub2c8\ub2e4. \uc989, \uc774\ucc28\ud568\uc218 $y = a(x - p)^2 + q$ ($a > 0$)\uc758 \ucd5c\uc19f\uac12\uc740 $q$\uc774\uba70, \uc774\ub54c\uc758 $x$ \uac12\uc740 $p$\uc785\ub2c8\ub2e4.","\ub9cc\uc57d \uc815\uc758\uc5ed(x\uc758 \ubc94\uc704)\uc774 \uc81c\ud55c\ub418\uc5b4 \uc788\ub2e4\uba74 \ucd5c\uc19f\uac12\uc740 \uaf2d\uc9d3\uc810\uc758 $y$ \uc88c\ud45c\uac00 \uc544\ub2d0 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc815\uc758\uc5ed\uc774 \uc2e4\uc218 \uc804\uccb4\ub77c\uba74, \uc544\ub798\ub85c \ubcfc\ub85d\ud55c \uc774\ucc28\ud568\uc218\uc758 \ucd5c\uc19f\uac12\uc740 \ud56d\uc0c1 \uaf2d\uc9d3\uc810\uc758 $y$ \uc88c\ud45c\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4. \uc774 \uc131\uc9c8\uc744 \uc774\uc6a9\ud558\uba74 \ubcf5\uc7a1\ud55c \uc774\ucc28\uc2dd\uc774\ub77c\ub3c4 \uaf2d\uc9d3\uc810\ub9cc \ucc3e\uc544\ub0b4\uba74 \ucd5c\uc19f\uac12\uc744 \uc27d\uac8c \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\uc81c \uc774 \uc6d0\ub9ac\ub97c \ubc14\ud0d5\uc73c\ub85c \uc2e4\uc81c \ubb38\uc81c\ub97c \ud480\uc5b4\ubcf4\uba70 \uc775\ud600\ubd05\uc2dc\ub2e4.","\uc608\uc81c: \uc774\ucc28\ud568\uc218 $y = x^2 - 4x + 7$\uc758 \ucd5c\uc19f\uac12\uc744 \uad6c\ud558\uc2dc\uc624. \uba3c\uc800 \uc774 \uc2dd\uc744 \uc644\uc804\uc81c\uacf1\uc2dd\uc73c\ub85c \ubcc0\ud615\ud574\uc57c \ud569\ub2c8\ub2e4. $x$\ud56d\uc774 \ud3ec\ud568\ub41c \ubd80\ubd84\uc744 $x^2 - 4x$\uc640 \uac19\uc774 \ubb36\uc740 \ub4a4, $x$ \uacc4\uc218\uc778 $-4$\uc758 \uc808\ubc18\uc758 \uc81c\uacf1\uc778 $4$\ub97c \ub354\ud558\uace0 \ube7c\uc90d\ub2c8\ub2e4. \uc2dd\uc744 \uc815\ub9ac\ud558\uba74 $$y = (x^2 - 4x + 4) - 4 + 7$$\uc774 \ub429\ub2c8\ub2e4.","\uc774\uc81c \uad04\ud638 \uc548\uc744 \uc778\uc218\ubd84\ud574\ud558\uc5ec \uc2dd\uc744 \uc644\uc131\ud569\ub2c8\ub2e4. $$y = (x - 2)^2 + 3$$ \uc774 \uc2dd\uc744 \ubcf4\uba74 $a = 1 > 0$\uc774\ubbc0\ub85c \uc544\ub798\ub85c \ubcfc\ub85d\ud55c \ud3ec\ubb3c\uc120\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4. $(x - 2)^2$\uc740 $x = 2$\uc77c \ub54c $0$\uc774 \ub418\uc5b4 \uac00\uc7a5 \uc791\uc544\uc9c0\ubbc0\ub85c, \uc804\uccb4 \uc2dd\uc758 \ucd5c\uc19f\uac12\uc740 $3$\uc774 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc8fc\uc5b4\uc9c4 \uc774\ucc28\ud568\uc218\uc758 \ucd5c\uc19f\uac12\uc740 $x = 2$\uc77c \ub54c $3$\uc785\ub2c8\ub2e4."],ai0),af3,B.r)],ai2),af3,B.r)],ai3),s3,s3,s3,s3,"concept_\ucd5c\uc19f\uac12(\uc774\ucc28\ud568\uc218)",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5591 > \uc774\ucc28\ud568\uc218 > \uc774\ucc28\ud568\uc218\uc758\ucd5c\ub300\ucd5c\uc18c > \ucd5c\uc19f\uac12(\uc774\ucc28\ud568\uc218)",o5,af3,s3)
o6=A.a(["\uacf5\ud1b5\uc218\ud5591","\ub2e4\ud56d\uc2dd","\ud56d\ub4f1\uc2dd","\ud56d\ub4f1\uc2dd\uc758\uc131\uc9c8"],ai0)
o6=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5591 > \ub2e4\ud56d\uc2dd > \ud56d\ub4f1\uc2dd > \ud56d\ub4f1\uc2dd\uc758\uc131\uc9c8 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\ud56d\ub4f1\uc2dd\uc774\ub780 \ubcc0\uc218 $x$\uc5d0 \uc5b4\ub5a4 \uac12\uc744 \ub300\uc785\ud558\ub354\ub77c\ub3c4 \ud56d\uc0c1 \uc131\ub9bd\ud558\ub294 \ub4f1\uc2dd\uc744 \ub9d0\ud569\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 $2(x+1) = 2x+2$\uc640 \uac19\uc740 \uc2dd\uc740 $x$\uc5d0 1\uc744 \ub123\ub4e0 100\uc744 \ub123\ub4e0 \uc88c\ubcc0\uacfc \uc6b0\ubcc0\uc758 \uac12\uc774 \ud56d\uc0c1 \uac19\uc73c\ubbc0\ub85c \ud56d\ub4f1\uc2dd\uc785\ub2c8\ub2e4. \ubc18\uba74, $x+1=3$\ucc98\ub7fc \ud2b9\uc815 \uac12($x=2$)\uc77c \ub54c\ub9cc \uc131\ub9bd\ud558\ub294 \uc2dd\uc740 '\ubc29\uc815\uc2dd'\uc774\ub77c\uace0 \ubd80\ub985\ub2c8\ub2e4. \ud56d\ub4f1\uc2dd\uc740 \ubb38\uc81c\uc5d0\uc11c '\ubaa8\ub4e0 $x$\uc5d0 \ub300\ud558\uc5ec \uc131\ub9bd\ud55c\ub2e4', '\uc784\uc758\uc758 $x$\uc5d0 \ub300\ud558\uc5ec \uc131\ub9bd\ud55c\ub2e4', '$x$\uc758 \uac12\uc5d0 \uad00\uacc4\uc5c6\uc774 \ud56d\uc0c1 \uc131\ub9bd\ud55c\ub2e4'\uc640 \uac19\uc740 \ud45c\ud604\uc73c\ub85c \uc790\uc8fc \ub4f1\uc7a5\ud569\ub2c8\ub2e4.","\ub2e4\ud56d\uc2dd $ax^2 + bx + c = 0$\uc774 $x$\uc5d0 \ub300\ud55c \ud56d\ub4f1\uc2dd\uc774 \ub418\ub824\uba74, \ubaa8\ub4e0 $x$\uc5d0 \ub300\ud558\uc5ec \uc2dd\uc774 \uc131\ub9bd\ud574\uc57c \ud558\ubbc0\ub85c \uacc4\uc218\ub4e4\uc774 \ubaa8\ub450 0\uc774\uc5b4\uc57c \ud569\ub2c8\ub2e4. \uc989, $$a=0, \\; b=0, \\; c=0$$\uc774 \uc131\ub9bd\ud574\uc57c \ud569\ub2c8\ub2e4. \ub354 \ub098\uc544\uac00 \ub450 \ub2e4\ud56d\uc2dd $ax^2 + bx + c$\uc640 $a'x^2 + b'x + c'$\uac00 \ubaa8\ub4e0 $x$\uc5d0 \ub300\ud558\uc5ec \uac19\uc73c\ub824\uba74, \uc591\ubcc0\uc758 \ub300\uc751\ud558\ub294 \ud56d\uc758 \uacc4\uc218\uac00 \uc11c\ub85c \uac19\uc544\uc57c \ud569\ub2c8\ub2e4. \uc774\ub97c '\uacc4\uc218\ube44\uad50\ubc95'\uc758 \uc6d0\ub9ac\ub77c\uace0 \ud558\uba70 \ub2e4\uc74c\uacfc \uac19\uc774 \uc815\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. $$a=a', \\; b=b', \\; c=c'$$","\ud56d\ub4f1\uc2dd\uc758 \uc131\uc9c8\uc744 \uc774\uc6a9\ud558\ub294 \ubc29\ubc95\uc5d0\ub294 \ud06c\uac8c \ub450 \uac00\uc9c0\uac00 \uc788\uc2b5\ub2c8\ub2e4. \uccab\uc9f8\ub294 \uc704\uc5d0\uc11c \uc5b8\uae09\ud55c '\uacc4\uc218\ube44\uad50\ubc95'\uc73c\ub85c, \uc591\ubcc0\uc758 \ub3d9\ub958\ud56d\uc758 \uacc4\uc218\ub97c \uc9c1\uc811 \ube44\uad50\ud558\ub294 \ubc29\uc2dd\uc785\ub2c8\ub2e4. \ub458\uc9f8\ub294 '\uc218\uce58\ub300\uc785\ubc95'\uc73c\ub85c, \ud56d\ub4f1\uc2dd\uc774 \ubaa8\ub4e0 $x$\uc5d0 \ub300\ud574 \uc131\ub9bd\ud55c\ub2e4\ub294 \uc810\uc744 \uc774\uc6a9\ud558\uc5ec \uc801\uc808\ud55c $x$ \uac12\uc744 \ub300\uc785\ud574 \ubbf8\uc9c0\uc218\ub97c \uad6c\ud558\ub294 \ubc29\uc2dd\uc785\ub2c8\ub2e4. \ubb38\uc81c\uc758 \ud615\ud0dc\uc5d0 \ub530\ub77c \uacc4\uc218\ub97c \ube44\uad50\ud558\ub294 \uac83\uc774 \ud3b8\ud560 \ub54c\ub3c4 \uc788\uace0, \ud2b9\uc815 \uac12\uc744 \ub300\uc785\ud558\uc5ec \uc2dd\uc744 \uac04\ub2e8\ud788 \ub9cc\ub4dc\ub294 \uac83\uc774 \ube60\ub97c \ub54c\ub3c4 \uc788\uc73c\ub2c8 \uc0c1\ud669\uc5d0 \ub9de\ucdb0 \uc120\ud0dd\ud558\ub294 \uc5f0\uc2b5\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.","\uc608\uc81c: \ub4f1\uc2dd $ax(x-1) + b(x-1) + c = 2x^2 + 3x + 1$\uc774 \ubaa8\ub4e0 $x$\uc5d0 \ub300\ud558\uc5ec \uc131\ub9bd\ud560 \ub54c, \uc0c1\uc218 $a, b, c$\uc758 \uac12\uc744 \uad6c\ud558\uc2dc\uc624. \uc774 \ubb38\uc81c\ub294 \uc218\uce58\ub300\uc785\ubc95\uc744 \uc0ac\uc6a9\ud558\uba74 \ub9e4\uc6b0 \ud3b8\ub9ac\ud569\ub2c8\ub2e4. \uc2dd\uc5d0 $x=1$\uc744 \ub300\uc785\ud558\uba74 $a(0) + b(0) + c = 2(1)^2 + 3(1) + 1$\uc774 \ub418\uc5b4, \uc88c\ubcc0\uc740 $c$\ub9cc \ub0a8\uace0 \uc6b0\ubcc0\uc740 $2+3+1=6$\uc774 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c $$c=6$$\uc784\uc744 \ubc14\ub85c \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c $c=6$\uc744 \ub300\uc785\ud55c \ud6c4, \ub2e4\ub978 $x$ \uac12\uc744 \ub300\uc785\ud558\uac70\ub098 \uacc4\uc218\ub97c \ube44\uad50\ud569\ub2c8\ub2e4. \uc2dd\uc740 $ax^2 + (b-a)x - b + 6 = 2x^2 + 3x + 1$\uc774 \ub429\ub2c8\ub2e4. \uc5ec\uae30\uc11c $x^2$\uc758 \uacc4\uc218\ub97c \ube44\uad50\ud558\uba74 $a=2$\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub97c $x$\uc758 \uacc4\uc218 \ube44\uad50\uc2dd\uc778 $b-a=3$\uc5d0 \ub300\uc785\ud558\uba74 $b-2=3$\uc774 \ub418\uc5b4 $$b=5$$\ub97c \uc5bb\uc2b5\ub2c8\ub2e4. \ucd5c\uc885\uc801\uc73c\ub85c \uad6c\ud558\ub294 \uac12\uc740 $$a=2, \\; b=5, \\; c=6$$\uc785\ub2c8\ub2e4."],ai0),af4,B.r)],ai2),af4,B.r)],ai3),s3,s3,s3,s3,"concept_\ud56d\ub4f1\uc2dd\uc758\uc131\uc9c8",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5591 > \ub2e4\ud56d\uc2dd > \ud56d\ub4f1\uc2dd > \ud56d\ub4f1\uc2dd\uc758\uc131\uc9c8",o6,af4,s3)
o7=A.a(["\ub300\uc218","\uc218\uc5f4","\ub4f1\ube44\uc218\uc5f4","\ub4f1\ube44\uc218\uc5f4\uc758\ud569"],ai0)
o7=A.ay(s2,A.a([A.aA(A.a(["\ub300\uc218 > \uc218\uc5f4 > \ub4f1\ube44\uc218\uc5f4 > \ub4f1\ube44\uc218\uc5f4\uc758\ud569 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\ub4f1\ube44\uc218\uc5f4\uc774\ub780 \uccab\uc9f8\ud56d\ubd80\ud130 \ucc28\ub840\ub300\ub85c \uc77c\uc815\ud55c \uc218\uc778 '\uacf5\ube44'\ub97c \uacf1\ud558\uc5ec \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uc218\uc5f4\uc744 \ub9d0\ud569\ub2c8\ub2e4. \uc774\ub7ec\ud55c \ub4f1\ube44\uc218\uc5f4\uc758 \uccab\uc9f8\ud56d\ubd80\ud130 \uc81c$n$\ud56d\uae4c\uc9c0\uc758 \ud569\uc744 $S_n$\uc774\ub77c\uace0 \ud560 \ub54c, \uc774\ub97c \uad6c\ud558\ub294 \uacf5\uc2dd\uc740 \uacf5\ube44 $r$\uc758 \uac12\uc5d0 \ub530\ub77c \ub2ec\ub77c\uc9d1\ub2c8\ub2e4. \uacf5\ube44 $r$\uc774 1\uc774 \uc544\ub2d0 \ub54c, \uccab\uc9f8\ud56d\uc744 $a$, \uacf5\ube44\ub97c $r$\uc774\ub77c \ud558\uba74 \uc81c$n$\ud56d\uae4c\uc9c0\uc758 \ud569 $S_n$\uc740 \ub2e4\uc74c\uacfc \uac19\uc740 \uacf5\uc2dd\uc73c\ub85c \ub098\ud0c0\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4.","$$S_n = \\frac{a(r^n - 1)}{r - 1} \\quad (r \\neq 1)$$ \ub610\ub294 \ubd84\ubaa8\uc640 \ubd84\uc790\uc5d0 -1\uc744 \uacf1\ud558\uc5ec $$S_n = \\frac{a(1 - r^n)}{1 - r} \\quad (r \\neq 1)$$ \ub85c\ub3c4 \uc4f8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub9cc\uc57d \uacf5\ube44 $r$\uc774 1\uc774\ub77c\uba74, \ubaa8\ub4e0 \ud56d\uc774 \uccab\uc9f8\ud56d $a$\uc640 \uac19\uc73c\ubbc0\ub85c \ud569\uc740 \ub2e8\uc21c\ud788 $a$\ub97c $n$\ubc88 \ub354\ud55c \uac12\uc778 $$S_n = na$$\uac00 \ub429\ub2c8\ub2e4. \uc774 \uacf5\uc2dd\ub4e4\uc740 \uc218\uc5f4\uc758 \ud56d\uc774 \ub9ce\uc544\uc9c8 \ub54c \uc77c\uc77c\uc774 \ub354\ud558\uc9c0 \uc54a\uace0\ub3c4 \ube60\ub974\uac8c \ud569\uc744 \uad6c\ud560 \uc218 \uc788\uac8c \ud574\uc8fc\ub294 \ub9e4\uc6b0 \uc720\uc6a9\ud55c \ub3c4\uad6c\uc785\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud1b5\ud574 \ub4f1\ube44\uc218\uc5f4\uc758 \ud569\uc744 \uad6c\ud558\ub294 \ubc29\ubc95\uc744 \uc54c\uc544\ubd05\uc2dc\ub2e4. \uccab\uc9f8\ud56d\uc774 2\uc774\uace0 \uacf5\ube44\uac00 3\uc778 \ub4f1\ube44\uc218\uc5f4\uc758 \uc81c5\ud56d\uae4c\uc9c0\uc758 \ud569\uc744 \uad6c\ud574\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uc8fc\uc5b4\uc9c4 \uc870\uac74\uc5d0\uc11c $a=2, r=3, n=5$\uc784\uc744 \ud655\uc778\ud569\ub2c8\ub2e4. \uacf5\ube44\uac00 1\uc774 \uc544\ub2c8\ubbc0\ub85c \uc704\uc5d0\uc11c \ubc30\uc6b4 \uacf5\uc2dd\uc744 \uadf8\ub300\ub85c \uc801\uc6a9\ud558\uba74 \ub429\ub2c8\ub2e4.","\uacf5\uc2dd $$S_n = \\frac{a(r^n - 1)}{r - 1}$$\uc5d0 \uc8fc\uc5b4\uc9c4 \uac12\ub4e4\uc744 \ub300\uc785\ud558\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$S_5 = \\frac{2(3^5 - 1)}{3 - 1}$$ \uc5ec\uae30\uc11c $3^5$\uc740 $3 \\times 3 \\times 3 \\times 3 \\times 3 = 243$\uc774\ubbc0\ub85c, \uc2dd\uc744 \uc815\ub9ac\ud558\uba74 $$S_5 = \\frac{2(243 - 1)}{2} = \\frac{2 \\times 242}{2}$$\uac00 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \ucd5c\uc885 \uacb0\uacfc\ub294 $$S_5 = 242$$\uac00 \ub429\ub2c8\ub2e4.","\ub610 \ub2e4\ub978 \uc608\uc81c\ub85c, \uccab\uc9f8\ud56d\uc774 8\uc774\uace0 \uacf5\ube44\uac00 $\\frac{1}{2}$\uc778 \ub4f1\ube44\uc218\uc5f4\uc758 \uc81c4\ud56d\uae4c\uc9c0\uc758 \ud569\uc744 \uad6c\ud574\ubd05\uc2dc\ub2e4. \uc5ec\uae30\uc11c $a=8, r=\\frac{1}{2}, n=4$\uc785\ub2c8\ub2e4. \uc774\ubc88\uc5d0\ub294 \uacf5\ube44\uac00 1\ubcf4\ub2e4 \uc791\uc73c\ubbc0\ub85c $$S_n = \\frac{a(1 - r^n)}{1 - r}$$ \uacf5\uc2dd\uc744 \uc0ac\uc6a9\ud558\ub294 \uac83\uc774 \uacc4\uc0b0\ud558\uae30\uc5d0 \ub354 \ud3b8\ub9ac\ud569\ub2c8\ub2e4.","\uacf5\uc2dd\uc5d0 \uac12\uc744 \ub300\uc785\ud558\uba74 $$S_4 = \\frac{8(1 - (\\frac{1}{2})^4)}{1 - \\frac{1}{2}}$$\uc774 \ub429\ub2c8\ub2e4. \ubd84\ubaa8\ub294 $\\frac{1}{2}$\uc774 \ub418\uace0, \ubd84\uc790\ub294 $8(1 - \\frac{1}{16}) = 8(\\frac{15}{16}) = \\frac{15}{2}$\uac00 \ub429\ub2c8\ub2e4. \uc774\ub97c \uacc4\uc0b0\ud558\uba74 $$S_4 = \\frac{15/2}{1/2} = \\frac{15}{2} \\times 2 = 15$$\uac00 \ub418\uc5b4, \uc81c4\ud56d\uae4c\uc9c0\uc758 \ud569\uc740 15\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),af5,B.r)],ai2),af5,B.r)],ai3),s3,s3,s3,s3,"concept_\ub4f1\ube44\uc218\uc5f4\uc758\ud569",0,"",1,s3,B.n,"\ub300\uc218 > \uc218\uc5f4 > \ub4f1\ube44\uc218\uc5f4 > \ub4f1\ube44\uc218\uc5f4\uc758\ud569",o7,af5,s3)
o8=A.a(["\uacf5\ud1b5\uc218\ud5592","\uba85\uc81c","\uba85\uc81c\uc758\ucc38\uac70\uc9d3"],ai0)
o8=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uba85\uc81c > \uba85\uc81c\uc758\ucc38\uac70\uc9d3 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uba85\uc81c\ub780 \ubb38\uc7a5\uc774\ub098 \uc2dd \uc911\uc5d0\uc11c \uadf8 \ucc38\uacfc \uac70\uc9d3\uc744 \uba85\ud655\ud558\uac8c \ud310\ubcc4\ud560 \uc218 \uc788\ub294 \uac83\uc744 \ub9d0\ud569\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 '3\uc740 5\ubcf4\ub2e4 \uc791\ub2e4'\ub294 \ucc38\uc778 \uba85\uc81c\uc774\uace0, '\uc11c\uc6b8\uc740 \ub300\ud55c\ubbfc\uad6d\uc758 \uc218\ub3c4\uc774\ub2e4' \uc5ed\uc2dc \ucc38\uc778 \uba85\uc81c\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc '\uc218\ud559\uc740 \uc7ac\ubbf8\uc788\ub2e4'\uc640 \uac19\uc774 \uc0ac\ub78c\ub9c8\ub2e4 \uc0dd\uac01\uc774 \ub2ec\ub77c \ucc38\uacfc \uac70\uc9d3\uc744 \uac1d\uad00\uc801\uc73c\ub85c \uc815\ud560 \uc218 \uc5c6\ub294 \ubb38\uc7a5\uc740 \uba85\uc81c\uac00 \uc544\ub2d9\ub2c8\ub2e4. \uba85\uc81c\ub294 \ubcf4\ud1b5 \uc18c\ubb38\uc790 $p, q, r$ \ub4f1\uc73c\ub85c \ub098\ud0c0\ub0b4\uba70, \ucc38\uc778 \uba85\uc81c\ub294 \uae30\ud638\ub85c $T$(True), \uac70\uc9d3\uc778 \uba85\uc81c\ub294 $F$(False)\ub85c \uad6c\ubd84\ud569\ub2c8\ub2e4.","\uba85\uc81c\uc758 \ucc38\uacfc \uac70\uc9d3\uc744 \ud310\ubcc4\ud560 \ub54c \uac00\uc7a5 \uc911\uc694\ud55c \uac83\uc740 \uc870\uac74\uc774 \ud3ec\ud568\ub41c \uba85\uc81c\uc785\ub2c8\ub2e4. \ubcc0\uc218 $x$\uc758 \uac12\uc5d0 \ub530\ub77c \ucc38\uc774 \ub418\uae30\ub3c4 \ud558\uace0 \uac70\uc9d3\uc774 \ub418\uae30\ub3c4 \ud558\ub294 \ubb38\uc7a5\uc744 '\uc870\uac74'\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4. \uc870\uac74 $p(x)$\uac00 \ucc38\uc774 \ub418\uac8c \ud558\ub294 \ubaa8\ub4e0 $x$\uc758 \uac12\uc758 \uc9d1\ud569\uc744 \uadf8 \uc870\uac74\uc758 '\uc9c4\ub9ac\uc9d1\ud569'\uc774\ub77c\uace0 \ud558\uba70, \ubcf4\ud1b5 \ub300\ubb38\uc790 $P$\ub85c \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \uc804\uccb4\uc9d1\ud569 $U$\uc758 \uc6d0\uc18c \uc911 \uc9c4\ub9ac\uc9d1\ud569 $P$\uc5d0 \uc18d\ud558\ub294 \uc6d0\uc18c\ub294 \uba85\uc81c\ub97c \ucc38\uc73c\ub85c \ub9cc\ub4e4\uace0, \uadf8\ub807\uc9c0 \uc54a\uc740 \uc6d0\uc18c\ub294 \uba85\uc81c\ub97c \uac70\uc9d3\uc73c\ub85c \ub9cc\ub4ed\ub2c8\ub2e4.","\uba85\uc81c $p$\uc5d0 \ub300\ud558\uc5ec 'p\uac00 \uc544\ub2c8\ub2e4'\ub97c \ubd80\uc815\uc774\ub77c \ud558\uba70, \uae30\ud638\ub85c $\\sim p$\ub77c\uace0 \uc501\ub2c8\ub2e4. \uba85\uc81c $p$\uac00 \ucc38\uc774\uba74 \ubd80\uc815 $\\sim p$\ub294 \uac70\uc9d3\uc774\uace0, \uba85\uc81c $p$\uac00 \uac70\uc9d3\uc774\uba74 \ubd80\uc815 $\\sim p$\ub294 \ucc38\uc774 \ub429\ub2c8\ub2e4. \ub610\ud55c, \ub450 \uc870\uac74 $p, q$\uc5d0 \ub300\ud558\uc5ec '$p$\uc774\uba74 $q$\uc774\ub2e4' \uaf34\uc758 \uba85\uc81c\ub294 $p \\implies q$\ub85c \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \uc774\ub54c \uc9c4\ub9ac\uc9d1\ud569 $P$\uac00 $Q$\uc758 \ubd80\ubd84\uc9d1\ud569($P \\subset Q$)\uc774\uba74 \uba85\uc81c $p \\implies q$\ub294 \ucc38\uc774 \ub418\uace0, \uadf8\ub807\uc9c0 \uc54a\uc73c\uba74 \uac70\uc9d3\uc774 \ub429\ub2c8\ub2e4.","\uc608\uc81c 1: \ub2e4\uc74c \uba85\uc81c\uc758 \ucc38\uacfc \uac70\uc9d3\uc744 \ud310\ubcc4\ud558\uace0, \uadf8 \uc774\uc720\ub97c \uc124\uba85\ud558\uc138\uc694. [\uba85\uc81c: '\ubaa8\ub4e0 \uc2e4\uc218 $x$\uc5d0 \ub300\ud558\uc5ec $x^2 > 0$\uc774\ub2e4.'] \ud480\uc774: \uc774 \uba85\uc81c\ub294 \uac70\uc9d3\uc785\ub2c8\ub2e4. \uc65c\ub0d0\ud558\uba74 $x=0$\uc77c \ub54c $x^2 = 0$\uc774 \ub418\uc5b4 $0 > 0$\uc774\ub77c\ub294 \ubd80\ub4f1\uc2dd\uc774 \uc131\ub9bd\ud558\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \uc989, $x=0$\uc774\ub77c\ub294 \ubc18\ub840(counterexample)\uac00 \uc874\uc7ac\ud558\ubbc0\ub85c \uc8fc\uc5b4\uc9c4 \uba85\uc81c\ub294 \uac70\uc9d3\uc785\ub2c8\ub2e4.","\uc608\uc81c 2: \uc804\uccb4\uc9d1\ud569 $U = \\{1, 2, 3, 4, 5, 6\\}$\uc5d0 \ub300\ud558\uc5ec, \uc870\uac74 $p: 'x$\ub294 12\uc758 \uc57d\uc218\uc774\ub2e4'\uc758 \uc9c4\ub9ac\uc9d1\ud569\uc744 \uad6c\ud558\uace0 \uba85\uc81c\uc758 \ucc38\uc744 \ud310\ubcc4\ud558\uc138\uc694. \ud480\uc774: \uba3c\uc800 12\uc758 \uc57d\uc218\ub97c \uad6c\ud558\uba74 $1, 2, 3, 4, 6, 12$\uc785\ub2c8\ub2e4. \uc804\uccb4\uc9d1\ud569 $U$\uc758 \uc6d0\uc18c \uc911\uc5d0\uc11c \uc774 \uc870\uac74\uc5d0 \ud574\ub2f9\ud558\ub294 \uc6d0\uc18c\ub97c \ucc3e\uc73c\uba74 \uc9c4\ub9ac\uc9d1\ud569 $P = \\{1, 2, 3, 4, 6\\}$\uc774 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c $U$\uc758 \ubaa8\ub4e0 \uc6d0\uc18c\uac00 $P$\uc5d0 \ud3ec\ud568\ub418\uc9c0\ub294 \uc54a\uc73c\ubbc0\ub85c(\uc608\ub97c \ub4e4\uc5b4 $5 \\notin P$), '\ubaa8\ub4e0 $x \\in U$\uc5d0 \ub300\ud558\uc5ec $p$\uc774\ub2e4'\ub77c\ub294 \uba85\uc81c\ub294 \uac70\uc9d3\uc785\ub2c8\ub2e4.","\uc608\uc81c 3: \ub450 \uc870\uac74 $p: x < 3$, $q: x < 5$\uc5d0 \ub300\ud558\uc5ec \uba85\uc81c $p \\implies q$\uc758 \ucc38\uacfc \uac70\uc9d3\uc744 \ud310\ubcc4\ud558\uc138\uc694. \ud480\uc774: \uc870\uac74 $p$\uc758 \uc9c4\ub9ac\uc9d1\ud569\uc744 $P$, \uc870\uac74 $q$\uc758 \uc9c4\ub9ac\uc9d1\ud569\uc744 $Q$\ub77c\uace0 \ud558\uba74 $P = \\{x \\mid x < 3\\}$, $Q = \\{x \\mid x < 5\\}$\uc785\ub2c8\ub2e4. \uc218\uc9c1\uc120 \uc704\uc5d0\uc11c $P$\uc758 \ubaa8\ub4e0 \uc6d0\uc18c\ub294 $Q$\uc758 \ubc94\uc704 \uc548\uc5d0 \ud3ec\ud568\ub418\ubbc0\ub85c $P \\subset Q$\uac00 \uc131\ub9bd\ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c \uba85\uc81c $p \\implies q$\ub294 \ucc38\uc785\ub2c8\ub2e4."],ai0),af6,B.r)],ai2),af6,B.r)],ai3),s3,s3,s3,s3,"concept_\uba85\uc81c\uc758\ucc38\uac70\uc9d3",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5592 > \uba85\uc81c > \uba85\uc81c\uc758\ucc38\uac70\uc9d3",o8,af6,s3)
o9=A.a(["\uacf5\ud1b5\uc218\ud5592","\uc88c\ud45c\ud3c9\uba74","\uc120\ubd84\uc758\ub0b4\ubd84\uc810","\ub0b4\ubd84\uc810\uacf5\uc2dd"],ai0)
o9=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \uc120\ubd84\uc758\ub0b4\ubd84\uc810 > \ub0b4\ubd84\uc810\uacf5\uc2dd \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uc218\uc9c1\uc120 \uc704\uc5d0\uc11c \ub450 \uc810 $A(x_1)$\uacfc $B(x_2)$\ub97c \uc787\ub294 \uc120\ubd84 $AB$\ub97c $m:n$\uc758 \ube44\uc728\ub85c \ub098\ub204\ub294 \uc810 $P(x)$\ub97c '\ub0b4\ubd84\uc810'\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4. \uc5ec\uae30\uc11c \ub0b4\ubd84\uc774\ub780 \uc120\ubd84 \uc548\ucabd\uc5d0\uc11c \uc810\uc774 \ub098\ub204\uc5b4\uc9c4\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4. \uc810 $P$\uac00 \uc120\ubd84 $AB$\ub97c $m:n$\uc73c\ub85c \ub0b4\ubd84\ud55c\ub2e4\ub294 \uac83\uc740 $AP:PB = m:n$\uc784\uc744 \uc758\ubbf8\ud558\uba70, \uc774\ub97c \ub9cc\uc871\ud558\ub294 \uc810 $P$\uc758 \uc88c\ud45c $x$\ub97c \uad6c\ud558\ub294 \uacf5\uc2dd\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.","\ub0b4\ubd84\uc810\uc758 \uc88c\ud45c $x$\ub97c \uad6c\ud558\ub294 \uacf5\uc2dd\uc740 \ub450 \uc810\uc758 \uc88c\ud45c\uc5d0 \ube44\ub840 \ubc30\ubd84\uc744 \uc801\uc6a9\ud55c \uacb0\uacfc\uc785\ub2c8\ub2e4. \uacf5\uc2dd\uc740 $$x = \\frac{mx_2 + nx_1}{m+n}$$\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uc774 \uacf5\uc2dd\uc740 \uc88c\ud45c\ud3c9\uba74\uc73c\ub85c \ud655\uc7a5\ud574\ub3c4 \ub3d9\uc77c\ud558\uac8c \uc801\uc6a9\ub429\ub2c8\ub2e4. \ub450 \uc810 $A(x_1, y_1)$\uacfc $B(x_2, y_2)$\ub97c $m:n$\uc73c\ub85c \ub0b4\ubd84\ud558\ub294 \uc810 $P(x, y)$\uc758 \uc88c\ud45c\ub294 $x$\uc88c\ud45c\uc640 $y$\uc88c\ud45c\ub97c \uac01\uac01 \ub530\ub85c \uacc4\uc0b0\ud558\uc5ec $$P\\left( \\frac{mx_2 + nx_1}{m+n}, \\frac{my_2 + ny_1}{m+n} \\right)$$\uc640 \uac19\uc774 \ub098\ud0c0\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uacf5\uc2dd\uc744 \uc678\uc6b8 \ub54c\ub294 \ubd84\ubaa8\uc5d0\ub294 \ube44\uc758 \ud569\uc778 $m+n$\uc744 \uc4f0\uace0, \ubd84\uc790\uc5d0\ub294 \ube44\uc640 \uc88c\ud45c\ub97c \uc11c\ub85c \uc5c7\uac08\ub824 \uacf1\ud55c \ub4a4 \ub354\ud55c\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud558\uba74 \uc27d\uc2b5\ub2c8\ub2e4. \ud2b9\ud788 $m=n=1$\uc778 \uacbd\uc6b0, \uc989 $1:1$\ub85c \ub0b4\ubd84\ud558\ub294 \uc810\uc740 \uc120\ubd84\uc758 \uc911\uc810\uc774 \ub418\uba70, \uc774\ub54c\uc758 \uc88c\ud45c\ub294 \ub450 \uc88c\ud45c\uc758 \ud3c9\uade0\uc778 $M\\left( \\frac{x_1+x_2}{2}, \\frac{y_1+y_2}{2} \\right)$\uac00 \ub429\ub2c8\ub2e4. \uc774 \uc131\uc9c8\uc740 \uae30\ud558\ud559\uc801 \ubb38\uc81c\ub97c \ud574\uacb0\ud560 \ub54c \ub9e4\uc6b0 \uc720\uc6a9\ud558\uac8c \uc0ac\uc6a9\ub429\ub2c8\ub2e4.","\uc608\uc81c \ubb38\uc81c\ub97c \ud1b5\ud574 \uacf5\uc2dd\uc744 \uc801\uc6a9\ud574 \ubd05\uc2dc\ub2e4. \ub450 \uc810 $A(1, 2)$\uc640 $B(7, 8)$\uc744 $2:1$\ub85c \ub0b4\ubd84\ud558\ub294 \uc810 $P$\uc758 \uc88c\ud45c\ub97c \uad6c\ud574\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uba3c\uc800 $x$\uc88c\ud45c\ub97c \uad6c\ud558\uba74, \uacf5\uc2dd\uc5d0 \ub530\ub77c $x = \\frac{2 \\times 7 + 1 \\times 1}{2+1}$\uc774 \ub429\ub2c8\ub2e4. \uc774\ub97c \uacc4\uc0b0\ud558\uba74 $x = \\frac{14+1}{3} = \\frac{15}{3} = 5$\uac00 \ub098\uc635\ub2c8\ub2e4.","\ub2e4\uc74c\uc73c\ub85c $y$\uc88c\ud45c\ub97c \uad6c\ud569\ub2c8\ub2e4. \uac19\uc740 \ubc29\uc2dd\uc73c\ub85c $y = \\frac{2 \\times 8 + 1 \\times 2}{2+1}$\uc744 \uacc4\uc0b0\ud569\ub2c8\ub2e4. \ubd84\uc790\ub97c \uc815\ub9ac\ud558\uba74 $y = \\frac{16+2}{3} = \\frac{18}{3} = 6$\uc774 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \ub450 \uc810 $A$\uc640 $B$\ub97c $2:1$\ub85c \ub0b4\ubd84\ud558\ub294 \uc810 $P$\uc758 \uc88c\ud45c\ub294 $(5, 6)$\uc785\ub2c8\ub2e4. \uc774\ucc98\ub7fc \ub0b4\ubd84\uc810 \uacf5\uc2dd\uc740 \ubcf5\uc7a1\ud55c \uc88c\ud45c \ubb38\uc81c\ub3c4 \uac04\ub2e8\ud55c \uc0b0\uc218 \uacfc\uc815\uc73c\ub85c \ud574\uacb0\ud560 \uc218 \uc788\uac8c \ud574\uc90d\ub2c8\ub2e4."],ai0),af7,B.r)],ai2),af7,B.r)],ai3),s3,s3,s3,s3,"concept_\ub0b4\ubd84\uc810\uacf5\uc2dd",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \uc120\ubd84\uc758\ub0b4\ubd84\uc810 > \ub0b4\ubd84\uc810\uacf5\uc2dd",o9,af7,s3)
p0=A.a(["\ub300\uc218","\uc9c0\uc218","\uc9c0\uc218\uc758\ud655\uc7a5","\uc720\ub9ac\uc218\uc9c0\uc218"],ai0)
p0=A.ay(s2,A.a([A.aA(A.a(["\ub300\uc218 > \uc9c0\uc218 > \uc9c0\uc218\uc758\ud655\uc7a5 > \uc720\ub9ac\uc218\uc9c0\uc218 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uc9c0\uc218\uc758 \ud655\uc7a5\uc774\ub780 \uc790\uc5f0\uc218 \ubc94\uc704\uc5d0\uc11c \uc815\uc758\ub418\uc5c8\ub358 \uc9c0\uc218 \ubc95\uce59\uc744 \uc815\uc218, \uc720\ub9ac\uc218, \ub098\uc544\uac00 \uc2e4\uc218 \ubc94\uc704\uae4c\uc9c0 \ub113\ud788\ub294 \uacfc\uc815\uc744 \ub9d0\ud569\ub2c8\ub2e4. \uba3c\uc800 \uc720\ub9ac\uc218 \uc9c0\uc218\ub294 \uac70\ub4ed\uc81c\uacf1\uadfc\uc758 \uac1c\ub150\uc744 \uc0ac\uc6a9\ud558\uc5ec \uc815\uc758\ud569\ub2c8\ub2e4. $n$\uc774 2 \uc774\uc0c1\uc758 \uc790\uc5f0\uc218\uc774\uace0 $a > 0$\uc77c \ub54c, $n$\uc81c\uacf1\ud558\uc5ec $a$\uac00 \ub418\ub294 \uc218 \uc911 \uc591\uc218\uc778 \uac83\uc744 $\\sqrt[n]{a}$\ub77c\uace0 \ud558\uba70, \uc774\ub97c \uc9c0\uc218 \ud615\ud0dc\ub85c \ub098\ud0c0\ub0b4\uba74 $a^{\\frac{1}{n}}$\uc774 \ub429\ub2c8\ub2e4. \uc989, $\\sqrt[n]{a} = a^{\\frac{1}{n}}$\uc774\ub77c\ub294 \uc57d\uc18d\uc744 \ud1b5\ud574 \uc9c0\uc218\uc5d0 \ubd84\uc218\uac00 \ub4f1\uc7a5\ud560 \uc218 \uc788\uac8c \ub429\ub2c8\ub2e4.","\ub354 \ub098\uc544\uac00 \ubd84\uc790\uac00 1\uc774 \uc544\ub2cc \uc720\ub9ac\uc218 \uc9c0\uc218\ub294 $a^{\\frac{m}{n}} = \\sqrt[n]{a^m} = (\\sqrt[n]{a})^m$\uc73c\ub85c \uc815\uc758\ud569\ub2c8\ub2e4. \uc5ec\uae30\uc11c $m$\uc740 \uc815\uc218\uc774\uace0 $n$\uc740 2 \uc774\uc0c1\uc758 \uc790\uc5f0\uc218\uc785\ub2c8\ub2e4. \uc774 \uc815\uc758\ub97c \uc0ac\uc6a9\ud558\uba74 \uc790\uc5f0\uc218 \ubc94\uc704\uc5d0\uc11c \uc131\ub9bd\ud558\ub358 \uc9c0\uc218 \ubc95\uce59\uc778 $a^p \\times a^q = a^{p+q}$, $(a^p)^q = a^{pq}$, $(ab)^p = a^p b^p$ \ub4f1\uc774 \uc9c0\uc218\uac00 \uc720\ub9ac\uc218\uc778 \uacbd\uc6b0\uc5d0\ub3c4 \uadf8\ub300\ub85c \uc131\ub9bd\ud558\uac8c \ub429\ub2c8\ub2e4. \ub2e8, \ubc11 $a$\uac00 0\ubcf4\ub2e4 \ucee4\uc57c \ud55c\ub2e4\ub294 \uc870\uac74\uc740 \uc720\ub9ac\uc218 \uc9c0\uc218\uc5d0\uc11c \ub9e4\uc6b0 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc720\ub9ac\uc218 \uc9c0\uc218\ub97c \ud65c\uc6a9\ud558\uba74 \ubcf5\uc7a1\ud55c \uac70\ub4ed\uc81c\uacf1\uadfc\uc758 \uacc4\uc0b0\uc744 \ud6e8\uc52c \uac04\ud3b8\ud558\uac8c \uc218\ud589\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \uc11c\ub85c \ub2e4\ub978 \uac70\ub4ed\uc81c\uacf1\uadfc\uc774 \uacf1\ud574\uc838 \uc788\ub294 \uc2dd\uc744 \uacc4\uc0b0\ud560 \ub54c, \ubaa8\ub4e0 \ud56d\uc744 \uc720\ub9ac\uc218 \uc9c0\uc218\ub85c \ubc14\uafb8\uc5b4 \uc9c0\uc218\ubc95\uce59\uc744 \uc801\uc6a9\ud558\uba74 \ubc11\uc774 \uac19\uc740 \uc218\ub4e4\uc758 \uc9c0\uc218\ub07c\ub9ac \ub354\ud558\uac70\ub098 \ube7c\ub294 \uac83\ub9cc\uc73c\ub85c \uac04\ub2e8\ud788 \uc815\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub294 \uc218\ud559\uc801 \uacc4\uc0b0\uc758 \ud6a8\uc728\uc131\uc744 \ub192\uc5ec\uc904 \ubfd0\ub9cc \uc544\ub2c8\ub77c, \uc774\ud6c4 \ubc30\uc6b0\uac8c \ub420 \ub85c\uadf8\ub098 \uc9c0\uc218\ud568\uc218\ub97c \uc774\ud574\ud558\ub294 \ub370 \ud544\uc218\uc801\uc778 \uae30\ucd08\uac00 \ub429\ub2c8\ub2e4.","\uc608\uc81c: \ub2e4\uc74c \uc2dd\uc744 \uac04\ub2e8\ud788 \ud558\uc2dc\uc624. $$\\sqrt[3]{2} \\times \\sqrt[6]{2^4}$$ \ub2e8\uacc4\ubcc4 \ud480\uc774: \uccab\uc9f8, \uac01 \uac70\ub4ed\uc81c\uacf1\uadfc\uc744 \uc720\ub9ac\uc218 \uc9c0\uc218\ub85c \ubcc0\ud658\ud569\ub2c8\ub2e4. $\\sqrt[3]{2} = 2^{\\frac{1}{3}}$\uc774\uace0, $\\sqrt[6]{2^4} = 2^{\\frac{4}{6}}$\uc785\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uc9c0\uc218 $\\frac{4}{6}$\uc740 \uc57d\ubd84\ud558\uc5ec $\\frac{2}{3}$\ub85c \ub098\ud0c0\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc2dd\uc740 $2^{\\frac{1}{3}} \\times 2^{\\frac{2}{3}}$\uc774 \ub429\ub2c8\ub2e4.","\ub458\uc9f8, \uc9c0\uc218\ubc95\uce59 $a^p \\times a^q = a^{p+q}$\ub97c \uc801\uc6a9\ud569\ub2c8\ub2e4. \ubc11\uc774 2\ub85c \uac19\uc73c\ubbc0\ub85c \uc9c0\uc218\ub07c\ub9ac \ub354\ud558\uba74 $2^{\\frac{1}{3} + \\frac{2}{3}} = 2^{\\frac{3}{3}}$\uc774 \ub429\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc9c0\uc218\ub97c \uacc4\uc0b0\ud558\uba74 $2^1 = 2$\ub77c\ub294 \uacb0\uacfc\ub97c \uc5bb\uc2b5\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uc720\ub9ac\uc218 \uc9c0\uc218\ub97c \uc774\uc6a9\ud558\uba74 \ubcf5\uc7a1\ud574 \ubcf4\uc774\ub294 \uac70\ub4ed\uc81c\uacf1\uadfc\uc758 \uacf1\uc148\ub3c4 \uc9c0\uc218\uc758 \ub367\uc148\ub9cc\uc73c\ub85c \uc27d\uac8c \ud574\uacb0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),af8,B.r)],ai2),af8,B.r)],ai3),s3,s3,s3,s3,"concept_\uc720\ub9ac\uc218\uc9c0\uc218",0,"",1,s3,B.n,"\ub300\uc218 > \uc9c0\uc218 > \uc9c0\uc218\uc758\ud655\uc7a5 > \uc720\ub9ac\uc218\uc9c0\uc218",p0,af8,s3)
p1=A.a(["\uacf5\ud1b5\uc218\ud5591","\uc774\ucc28\ud568\uc218","\uc774\ucc28\ud568\uc218\uc758\ucd5c\ub300\ucd5c\uc18c","\uc815\uc758\uc5ed\uc5d0\uc11c\uc758\ucd5c\ub300\ucd5c\uc18c"],ai0)
p1=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5591 > \uc774\ucc28\ud568\uc218 > \uc774\ucc28\ud568\uc218\uc758\ucd5c\ub300\ucd5c\uc18c > \uc815\uc758\uc5ed\uc5d0\uc11c\uc758\ucd5c\ub300\ucd5c\uc18c \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uc774\ucc28\ud568\uc218\uc758 \ucd5c\ub300\uc640 \ucd5c\uc18c\ub294 \ud568\uc218\uc758 \uadf8\ub798\ud504\uac00 \uc544\ub798\ub85c \ubcfc\ub85d\ud55c\uc9c0, \uc704\ub85c \ubcfc\ub85d\ud55c\uc9c0\uc5d0 \ub530\ub77c \uacb0\uc815\ub429\ub2c8\ub2e4. \uc815\uc758\uc5ed\uc774 \uc2e4\uc218 \uc804\uccb4\uc77c \ub54c\ub294 \uaf2d\uc9d3\uc810\uc5d0\uc11c \ucd5c\ub313\uac12 \ub610\ub294 \ucd5c\uc19f\uac12\uc744 \uac16\uc9c0\ub9cc, \uc815\uc758\uc5ed\uc774 \ud2b9\uc815 \uad6c\uac04 $[p, q]$\ub85c \uc81c\ud55c\ub418\uba74 \uc0c1\ud669\uc774 \ub2ec\ub77c\uc9d1\ub2c8\ub2e4. \uc774\ub54c\ub294 \uc8fc\uc5b4\uc9c4 \uad6c\uac04 \ub0b4\uc5d0\uc11c \uadf8\ub798\ud504\uc758 \uac00\uc7a5 \ub192\uc740 \uc810\uacfc \uac00\uc7a5 \ub0ae\uc740 \uc810\uc744 \ucc3e\uc544\uc57c \ud569\ub2c8\ub2e4.","\uc815\uc758\uc5ed\uc774 \uc81c\ud55c\ub41c \uc774\ucc28\ud568\uc218 $f(x) = a(x-m)^2 + n$\uc758 \ucd5c\ub313\uac12\uacfc \ucd5c\uc19f\uac12\uc744 \uad6c\ud558\ub294 \ubc29\ubc95\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uaf2d\uc9d3\uc810\uc758 $x$\uc88c\ud45c\uc778 $m$\uc774 \uc8fc\uc5b4\uc9c4 \uad6c\uac04 $[p, q]$\uc5d0 \ud3ec\ud568\ub418\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4. \ub9cc\uc57d $m$\uc774 \uad6c\uac04 \uc548\uc5d0 \uc788\ub2e4\uba74, \uaf2d\uc9d3\uc810\uc5d0\uc11c\uc758 \ud568\uc22b\uac12 $f(m)$\uacfc \uad6c\uac04\uc758 \uc591 \ub05d\uc810\uc5d0\uc11c\uc758 \ud568\uc22b\uac12 $f(p), f(q)$\ub97c \ubaa8\ub450 \ube44\uad50\ud558\uc5ec \uac00\uc7a5 \ud070 \uac12\uc774 \ucd5c\ub313\uac12, \uac00\uc7a5 \uc791\uc740 \uac12\uc774 \ucd5c\uc19f\uac12\uc774 \ub429\ub2c8\ub2e4.","\ub9cc\uc57d \uaf2d\uc9d3\uc810\uc758 $x$\uc88c\ud45c\uc778 $m$\uc774 \uad6c\uac04 $[p, q]$ \ubc16\uc5d0 \uc788\ub2e4\uba74, \uaf2d\uc9d3\uc810\uc744 \ud3ec\ud568\ud558\uc9c0 \uc54a\uc73c\ubbc0\ub85c \uad6c\uac04\uc758 \uc591 \ub05d\uc810\uc778 $f(p)$\uc640 $f(q)$ \uc911\uc5d0\uc11c \ucd5c\ub313\uac12\uacfc \ucd5c\uc19f\uac12\uc774 \uacb0\uc815\ub429\ub2c8\ub2e4. \uc989, \uadf8\ub798\ud504\uac00 \uad6c\uac04 \ub0b4\uc5d0\uc11c \uacc4\uc18d \uc99d\uac00\ud558\uac70\ub098 \uac10\uc18c\ud558\ub294 \uc0c1\ud0dc\uc774\ubbc0\ub85c, \uc591 \ub05d\uc810\uc758 \ud568\uc22b\uac12\ub9cc \ube44\uad50\ud558\uba74 \ub429\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uc815\uc758\uc5ed\uc758 \ubc94\uc704\uc5d0 \ub530\ub77c \ucd5c\ub313\uac12\uacfc \ucd5c\uc19f\uac12\uc774 \ub2ec\ub77c\uc9c0\ub294 \uc810\uc744 \uc8fc\uc758\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc608\uc81c: \uc774\ucc28\ud568\uc218 $f(x) = x^2 - 4x + 5$\uc758 \uc815\uc758\uc5ed\uc774 $0 \\le x \\le 3$\uc77c \ub54c, \uc774 \ud568\uc218\uc758 \ucd5c\ub313\uac12\uacfc \ucd5c\uc19f\uac12\uc744 \uad6c\ud558\uc2dc\uc624. \uba3c\uc800 \ud568\uc218\uc2dd\uc744 \ud45c\uc900\ud615\uc73c\ub85c \ubc14\uafb8\uba74 $f(x) = (x-2)^2 + 1$\uc774 \ub429\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uaf2d\uc9d3\uc810\uc758 \uc88c\ud45c\ub294 $(2, 1)$\uc774\uace0, $x=2$\ub294 \uc8fc\uc5b4\uc9c4 \uad6c\uac04 $[0, 3]$ \uc548\uc5d0 \ud3ec\ud568\ub429\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uac04\uc758 \uc591 \ub05d\uc810\uacfc \uaf2d\uc9d3\uc810\uc5d0\uc11c\uc758 \ud568\uc22b\uac12\uc744 \uac01\uac01 \uad6c\ud569\ub2c8\ub2e4. $f(2) = 1$ (\uaf2d\uc9d3\uc810), $f(0) = 0^2 - 4(0) + 5 = 5$ (\uc67c\ucabd \ub05d\uc810), $f(3) = 3^2 - 4(3) + 5 = 2$ (\uc624\ub978\ucabd \ub05d\uc810)\uc785\ub2c8\ub2e4. \uc774 \uc138 \ud568\uc22b\uac12 $1, 5, 2$\ub97c \ube44\uad50\ud558\uba74 \uac00\uc7a5 \ud070 \uac12\uc740 $5$\uc774\uace0 \uac00\uc7a5 \uc791\uc740 \uac12\uc740 $1$\uc785\ub2c8\ub2e4.","\ub530\ub77c\uc11c \uc8fc\uc5b4\uc9c4 \uc815\uc758\uc5ed $0 \\le x \\le 3$\uc5d0\uc11c \uc774\ucc28\ud568\uc218 $f(x)$\uc758 \ucd5c\ub313\uac12\uc740 $5$\uc774\uace0, \ucd5c\uc19f\uac12\uc740 $1$\uc785\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uad6c\uac04 \ub0b4\uc5d0 \uaf2d\uc9d3\uc810\uc774 \ud3ec\ud568\ub418\ub294 \uacbd\uc6b0\uc5d0\ub294 \ubc18\ub4dc\uc2dc \uaf2d\uc9d3\uc810\uc758 \ud568\uc22b\uac12\uacfc \uc591 \ub05d\uc810\uc758 \ud568\uc22b\uac12\uc744 \ubaa8\ub450 \uacc4\uc0b0\ud558\uc5ec \ube44\uad50\ud558\ub294 \uc2b5\uad00\uc744 \uac00\uc838\uc57c \ud569\ub2c8\ub2e4."],ai0),af9,B.r)],ai2),af9,B.r)],ai3),s3,s3,s3,s3,"concept_\uc815\uc758\uc5ed\uc5d0\uc11c\uc758\ucd5c\ub300\ucd5c\uc18c",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5591 > \uc774\ucc28\ud568\uc218 > \uc774\ucc28\ud568\uc218\uc758\ucd5c\ub300\ucd5c\uc18c > \uc815\uc758\uc5ed\uc5d0\uc11c\uc758\ucd5c\ub300\ucd5c\uc18c",p1,af9,s3)
p2=A.a(["\ubbf8\uc801\ubd84\u2160","\ud568\uc218\uc758\uc99d\uac00\uc640\uac10\uc18c","\uc99d\uac00\ud568\uc218"],ai0)
p2=A.ay(s2,A.a([A.aA(A.a(["\ubbf8\uc801\ubd84\u2160 > \ud568\uc218\uc758\uc99d\uac00\uc640\uac10\uc18c > \uc99d\uac00\ud568\uc218 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(['[   "\ud568\uc218 $f(x)$\uac00 \uc5b4\ub5a4 \uad6c\uac04\uc5d0 \uc18d\ud558\ub294 \uc784\uc758\uc758 \ub450 \uc2e4\uc218 $x_1, x_2$\uc5d0 \ub300\ud558\uc5ec $x_1 < x_2$\uc77c \ub54c, \ud56d\uc0c1 $f(x_1) < f(x_2)$\uac00 \uc131\ub9bd\ud558\uba74 \uc774 \ud568\uc218\ub97c \uadf8 \uad6c\uac04\uc5d0\uc11c \'\uc99d\uac00\ud568\uc218\'\ub77c\uace0 \ud569\ub2c8\ub2e4. \uc27d\uac8c \ub9d0\ud574, \uadf8\ub798\ud504\ub97c \uc67c\ucabd\uc5d0\uc11c \uc624\ub978\ucabd\uc73c\ub85c \ub530\ub77c\uac08 \ub54c \ud568\uc218\uc758 \ub192\uc774(\ud568\uc22b\uac12)\uac00 \uc810\uc810 \ub192\uc544\uc9c0\ub294 \uc0c1\ud0dc\ub97c \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc9c1\uad00\uc801\uc73c\ub85c\ub294 \uadf8\ub798\ud504\uac00 \uc624\ub978\ucabd \uc704\ub97c \ud5a5\ud574 \ubed7\uc5b4 \ub098\uac00\ub294 \ubaa8\uc591\uc744 \uc0c1\uc0c1\ud558\uba74 \uc774\ud574\ud558\uae30 \uc27d\uc2b5\ub2c8\ub2e4.",   "\ubbf8\ubd84 \uac00\ub2a5\ud55c \ud568\uc218 $f(x)$\uac00 \uc5b4\ub5a4 \uad6c\uac04\uc5d0\uc11c \uc99d\uac00\ud568\uc218\uc778\uc9c0 \ud310\ubcc4\ud558\ub824\uba74 \ub3c4\ud568\uc218 $f\'(x)$\ub97c \uc774\uc6a9\ud569\ub2c8\ub2e4. \ub9cc\uc57d \uc5b4\ub5a4 \uad6c\uac04\uc758 \ubaa8\ub4e0 $x$\uc5d0 \ub300\ud558\uc5ec $f\'(x) > 0$\uc774\uba74, \ud568\uc218 $f(x)$\ub294 \uadf8 \uad6c\uac04\uc5d0\uc11c \uc99d\uac00\ud569\ub2c8\ub2e4. \ub2e4\ub9cc, $f\'(x) = 0$\uc778 \uc810\uc774 \uc788\ub354\ub77c\ub3c4 \uadf8 \uc810\uc774 \uc5f0\uc18d\uc801\uc73c\ub85c \uc774\uc5b4\uc9c0\uc9c0 \uc54a\uace0 \ub4dc\ubb38\ub4dc\ubb38 \uc874\uc7ac\ud55c\ub2e4\uba74 \ud568\uc218 \uc804\uccb4\ub294 \uc5ec\uc804\ud788 \uc99d\uac00\ud558\ub294 \uc0c1\ud0dc\ub85c \ubd05\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc77c\ubc18\uc801\uc73c\ub85c \ud568\uc218 $f(x)$\uac00 \uad6c\uac04\uc5d0\uc11c \uc99d\uac00\ud558\uae30 \uc704\ud55c \ud544\uc694\ucda9\ubd84\uc870\uac74\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$f\'(x) \\\\ge 0$$",   "\uc99d\uac00\ud568\uc218\uc758 \ud575\uc2ec \uc131\uc9c8\uc740 \ud568\uc22b\uac12\uc758 \ub300\uc18c \uad00\uacc4\uac00 \uc815\uc758\uc5ed\uc758 \ub300\uc18c \uad00\uacc4\uc640 \uc77c\uce58\ud55c\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4. \uc989, $x$\uac12\uc774 \ucee4\uc9c8\uc218\ub85d $y$\uac12\ub3c4 \ucee4\uc9c0\uac70\ub098 \uc77c\uc815\ud558\uac8c \uc720\uc9c0\ub429\ub2c8\ub2e4. \ub9cc\uc57d \uad6c\uac04 \ub0b4\uc758 \ubaa8\ub4e0 \uc810\uc5d0\uc11c $f\'(x) > 0$\uc774\ub77c\uba74 \ud568\uc218\ub294 \uc5c4\uaca9\ud558\uac8c \uc99d\uac00\ud558\uba70, $f\'(x) \\ge 0$\uc774\uba74\uc11c \ud2b9\uc815 \uad6c\uac04\uc5d0\uc11c $f\'(x) = 0$\uc774 \ub41c\ub2e4\uba74 \uadf8 \uad6c\uac04\uc5d0\uc11c\ub294 \uadf8\ub798\ud504\uac00 \uc7a0\uc2dc \ud3c9\ud3c9\ud574\uc84c\ub2e4\uac00 \ub2e4\uc2dc \uc62c\ub77c\uac00\ub294 \ud615\ud0dc\uac00 \ub429\ub2c8\ub2e4.",   "\uc608\uc81c: \ud568\uc218 $f(x) = x^3 - 3x + 5$\uac00 \uc99d\uac00\ud558\ub294 \uad6c\uac04\uc744 \uad6c\ud558\uc2dc\uc624. \uba3c\uc800 \ud568\uc218\uac00 \uc99d\uac00\ud558\uae30 \uc704\ud55c \uc870\uac74\uc778 $f\'(x) \\\\ge 0$\uc744 \ub9cc\uc871\ud558\ub294 \ubc94\uc704\ub97c \ucc3e\uc544\uc57c \ud569\ub2c8\ub2e4. \uc8fc\uc5b4\uc9c4 \ud568\uc218\ub97c $x$\uc5d0 \ub300\ud558\uc5ec \ubbf8\ubd84\ud558\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$f\'(x) = 3x^2 - 3$$",   "\uc774\uc81c \ubd80\ub4f1\uc2dd $3x^2 - 3 \\\\ge 0$\uc744 \ud480\uc5b4\ubd05\uc2dc\ub2e4. \uc591\ubcc0\uc744 3\uc73c\ub85c \ub098\ub204\uba74 $x^2 - 1 \\\\ge 0$\uc774 \ub418\uace0, \uc774\ub97c \uc778\uc218\ubd84\ud574\ud558\uba74 $(x+1)(x-1) \\\\ge 0$\uc774 \ub429\ub2c8\ub2e4. \uc774\ucc28\ubd80\ub4f1\uc2dd\uc758 \uc131\uc9c8\uc5d0 \ub530\ub77c \uc774 \uc2dd\uc744 \ub9cc\uc871\ud558\ub294 $x$\uc758 \ubc94\uc704\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$x \\\\le -1 \\\\quad \\\\text{\ub610\ub294} \\\\quad x \\\\ge 1$$",   "\ub530\ub77c\uc11c \ud568\uc218 $f(x) = x^3 - 3x + 5$\ub294 \uad6c\uac04 $(-\\\\infty, -1]$\uacfc $[1, \\\\infty)$\uc5d0\uc11c \uc99d\uac00\ud569\ub2c8\ub2e4. \uc774\ucc98\ub7fc \ub3c4\ud568\uc218\uc758 \ubd80\ud638\ub97c \uc870\uc0ac\ud558\uba74 \ud568\uc218\uc758 \uc99d\uac00\uc640 \uac10\uc18c \uc0c1\ud0dc\ub97c \uba85\ud655\ud558\uac8c \ud30c\uc545\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uadf8\ub798\ud504\ub97c \uadf8\ub824\ubcf4\uba74 $x=-1$\uacfc $x=1$\uc744 \uae30\uc900\uc73c\ub85c \ud568\uc218\uc758 \ubc29\ud5a5\uc774 \ubc14\ub00c\ub294 \uac83\uc744 \ud655\uc778\ud560 \uc218 \uc788\uc73c\uba70, \uc774\ub294 \ubbf8\ubd84\uc744 \ud1b5\ud574 \ud568\uc218\uc758 \uac1c\ud615\uc744 \ucd94\ub860\ud558\ub294 \uac00\uc7a5 \uae30\ubcf8\uc801\uc778 \uacfc\uc815\uc785\ub2c8\ub2e4." ]'],ai0),ag0,B.r)],ai2),ag0,B.r)],ai3),s3,s3,s3,s3,"concept_\uc99d\uac00\ud568\uc218",0,"",1,s3,B.n,"\ubbf8\uc801\ubd84\u2160 > \ud568\uc218\uc758\uc99d\uac00\uc640\uac10\uc18c > \uc99d\uac00\ud568\uc218",p2,ag0,s3)
p3=A.a(["\uacf5\ud1b5\uc218\ud5592","\uba85\uc81c","\uba85\uc81c\uc758\uc5ed\uacfc\ub300\uc6b0","\uc5ed"],ai0)
p3=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uba85\uc81c > \uba85\uc81c\uc758\uc5ed\uacfc\ub300\uc6b0 > \uc5ed \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uba85\uc81c\ub780 \ucc38\uacfc \uac70\uc9d3\uc744 \uba85\ud655\ud558\uac8c \ud310\ubcc4\ud560 \uc218 \uc788\ub294 \ubb38\uc7a5\uc774\ub098 \uc2dd\uc744 \ub9d0\ud569\ub2c8\ub2e4. \uc77c\ubc18\uc801\uc73c\ub85c \uba85\uc81c\ub294 '\uac00\uc815'\uacfc '\uacb0\ub860'\uc73c\ub85c \uc774\ub8e8\uc5b4\uc838 \uc788\uc73c\uba70, \uc774\ub97c \uae30\ud638\ub85c \ub098\ud0c0\ub0b4\uba74 '$p \\rightarrow q$'\uc640 \uac19\uc774 \ud45c\ud604\ud569\ub2c8\ub2e4. \uc5ec\uae30\uc11c '$p$'\ub294 \uac00\uc815, '$q$'\ub294 \uacb0\ub860\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \uba85\uc81c\uc758 '\uc5ed'\uc774\ub780, \uc6d0\ub798 \uba85\uc81c\uc758 \uac00\uc815\uacfc \uacb0\ub860\uc758 \uc704\uce58\ub97c \uc11c\ub85c \ubc14\uafb8\uc5b4 \ub193\uc740 \uc0c8\ub85c\uc6b4 \uba85\uc81c\ub97c \ub9d0\ud569\ub2c8\ub2e4. \uc989, \uba85\uc81c '$p \\rightarrow q$'\uc758 \uc5ed\uc740 '$q \\rightarrow p$'\uac00 \ub429\ub2c8\ub2e4.","\uc5ed\uc744 \ub9cc\ub4dc\ub294 \ubc29\ubc95\uc740 \ub9e4\uc6b0 \uac04\ub2e8\ud569\ub2c8\ub2e4. \uc6d0\ub798 \uba85\uc81c\uc5d0\uc11c '~\uc774\uba74' \ub4a4\uc5d0 \uc624\ub294 \uacb0\ub860 \ubd80\ubd84\uc744 \uac00\uc815\uc73c\ub85c \uc62e\uae30\uace0, \ucc98\uc74c\uc5d0 \uc788\ub358 \uac00\uc815 \ubd80\ubd84\uc744 \uacb0\ub860\uc73c\ub85c \uc62e\uae30\uba74 \ub429\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 'x\uac00 2\uc774\uba74 x^2\uc740 4\uc774\ub2e4'\ub77c\ub294 \uba85\uc81c\uac00 \uc788\ub2e4\uba74, \uadf8 \uc5ed\uc740 'x^2\uc774 4\uc774\uba74 x\ub294 2\uc774\ub2e4'\uac00 \ub429\ub2c8\ub2e4. \uc8fc\uc758\ud560 \uc810\uc740 \uc6d0\ub798 \uba85\uc81c\uac00 \ucc38\uc774\ub77c\uace0 \ud574\uc11c \uadf8 \uc5ed\ub3c4 \ubc18\ub4dc\uc2dc \ucc38\uc778 \uac83\uc740 \uc544\ub2c8\ub77c\ub294 \uc0ac\uc2e4\uc785\ub2c8\ub2e4. \uc5ed\uc740 \uc6d0\ub798 \uba85\uc81c\uc640\ub294 \ub3c5\ub9bd\uc801\uc778 \uc0c8\ub85c\uc6b4 \uba85\uc81c\uc774\ubbc0\ub85c, \ucc38\uacfc \uac70\uc9d3\uc744 \ubcc4\ub3c4\ub85c \ud310\ubcc4\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc5ed\uc758 \uc131\uc9c8\uc744 \uc774\ud574\ud560 \ub54c \uac00\uc7a5 \uc911\uc694\ud55c \uac83\uc740 '\ub17c\ub9ac\uc801 \uad00\uacc4'\uc785\ub2c8\ub2e4. \uba85\uc81c '$p \\rightarrow q$'\uac00 \ucc38\uc774\ub77c\uace0 \ud574\uc11c \uadf8 \uc5ed\uc778 '$q \\rightarrow p$'\uac00 \ud56d\uc0c1 \ucc38\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 '\uc0ac\ub78c\uc774\uba74 \ub3d9\ubb3c\uc774\ub2e4'\ub294 \ucc38\uc774\uc9c0\ub9cc, \uadf8 \uc5ed\uc778 '\ub3d9\ubb3c\uc774\uba74 \uc0ac\ub78c\uc774\ub2e4'\ub294 \uac70\uc9d3\uc785\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc5b4\ub5a4 \uba85\uc81c\uc758 \uc5ed\uc744 \uad6c\ud560 \ub54c\ub294 \ub2e8\uc21c\ud788 \uc704\uce58\ub9cc \ubc14\uafb8\ub294 \uac83\uc5d0 \uadf8\uce58\uc9c0 \uc54a\uace0, \ubc14\ub010 \ubb38\uc7a5\uc774 \ub17c\ub9ac\uc801\uc73c\ub85c \uc131\ub9bd\ud558\ub294\uc9c0 \ubc18\ub4dc\uc2dc \uac80\ud1a0\ud558\ub294 \uc2b5\uad00\uc744 \uae38\ub7ec\uc57c \ud569\ub2c8\ub2e4.","\uc608\uc81c \ubb38\uc81c\ub97c \ud1b5\ud574 \uc5ed\uc744 \uad6c\ud558\ub294 \uacfc\uc815\uc744 \uc0b4\ud3b4\ubd05\uc2dc\ub2e4. \uba85\uc81c 'x\uac00 6\uc758 \ubc30\uc218\uc774\uba74 x\ub294 3\uc758 \ubc30\uc218\uc774\ub2e4'\uc758 \uc5ed\uc744 \uad6c\ud558\uace0 \ucc38, \uac70\uc9d3\uc744 \ud310\ubcc4\ud574 \ubcf4\uc138\uc694. \uba3c\uc800, \uc774 \uba85\uc81c\uc758 \uac00\uc815\uc740 'x\uac00 6\uc758 \ubc30\uc218\uc774\ub2e4'\uc774\uace0, \uacb0\ub860\uc740 'x\ub294 3\uc758 \ubc30\uc218\uc774\ub2e4'\uc785\ub2c8\ub2e4. \uc5ed\uc740 \uac00\uc815\uacfc \uacb0\ub860\uc758 \uc704\uce58\ub97c \ubc14\uafb8\uc5b4 '$q \\rightarrow p$'\uc758 \ud615\ud0dc\ub85c \ub9cc\ub4ed\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc5ed\uc740 'x\uac00 3\uc758 \ubc30\uc218\uc774\uba74 x\ub294 6\uc758 \ubc30\uc218\uc774\ub2e4'\uac00 \ub429\ub2c8\ub2e4.","\uc774\uc81c \uad6c\ud55c \uc5ed\uc758 \ucc38\uacfc \uac70\uc9d3\uc744 \ud310\ubcc4\ud574 \ubd05\uc2dc\ub2e4. \uc5ed\uc778 'x\uac00 3\uc758 \ubc30\uc218\uc774\uba74 x\ub294 6\uc758 \ubc30\uc218\uc774\ub2e4'\uc5d0\uc11c, x\uac00 3\uc778 \uacbd\uc6b0\ub97c \uc0dd\uac01\ud574 \ubd05\uc2dc\ub2e4. 3\uc740 3\uc758 \ubc30\uc218\uc774\uc9c0\ub9cc 6\uc758 \ubc30\uc218\ub294 \uc544\ub2d9\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uac00\uc815\uc740 \ub9cc\uc871\ud558\uc9c0\ub9cc \uacb0\ub860\uc744 \ub9cc\uc871\ud558\uc9c0 \uc54a\ub294 \uacbd\uc6b0\ub97c '\ubc18\ub840'\ub77c\uace0 \ud569\ub2c8\ub2e4. \ubc18\ub840\uac00 \ud558\ub098\ub77c\ub3c4 \uc874\uc7ac\ud558\ubbc0\ub85c, \uc774 \uba85\uc81c\uc758 \uc5ed\uc740 '\uac70\uc9d3'\uc774 \ub429\ub2c8\ub2e4. \uc774\uc640 \uac19\uc774 \uc5ed\uc744 \uad6c\ud560 \ub54c\ub294 \ubc18\ub840\ub97c \ucc3e\uc544\ubcf4\ub294 \uacfc\uc815\uc774 \ub9e4\uc6b0 \uc911\uc694\ud569\ub2c8\ub2e4."],ai0),"\uc5ed",B.r)],ai2),"\uc5ed",B.r)],ai3),s3,s3,s3,s3,"concept_\uc5ed",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5592 > \uba85\uc81c > \uba85\uc81c\uc758\uc5ed\uacfc\ub300\uc6b0 > \uc5ed",p3,"\uc5ed",s3)
p4=A.a(["\ub300\uc218","\uc218\uc5f4","\ub4f1\ube44\uc218\uc5f4","\ub4f1\ube44\uc911\ud56d"],ai0)
p4=A.ay(s2,A.a([A.aA(A.a(["\ub300\uc218 > \uc218\uc5f4 > \ub4f1\ube44\uc218\uc5f4 > \ub4f1\ube44\uc911\ud56d \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\ub4f1\ube44\uc218\uc5f4\uc5d0\uc11c \uc5f0\uc18d\ud558\ub294 \uc138 \ud56d $a, b, c$\uac00 \uc774 \uc21c\uc11c\ub300\ub85c \ub4f1\ube44\uc218\uc5f4\uc744 \uc774\ub8f0 \ub54c, \uac00\uc6b4\ub370 \uc788\ub294 \ud56d $b$\ub97c $a$\uc640 $c$\uc758 '\ub4f1\ube44\uc911\ud56d'\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4. \ub4f1\ube44\uc218\uc5f4\uc758 \uc815\uc758\uc5d0 \ub530\ub77c \ub450 \ubc88\uc9f8 \ud56d\uc744 \uccab \ubc88\uc9f8 \ud56d\uc73c\ub85c \ub098\ub208 \ube44\uc640 \uc138 \ubc88\uc9f8 \ud56d\uc744 \ub450 \ubc88\uc9f8 \ud56d\uc73c\ub85c \ub098\ub208 \ube44\ub294 \uc11c\ub85c \uac19\uc544\uc57c \ud558\ubbc0\ub85c, $\\frac{b}{a} = \\frac{c}{b}$\ub77c\ub294 \uad00\uacc4\uc2dd\uc774 \uc131\ub9bd\ud569\ub2c8\ub2e4.","\uc704\uc758 \uc2dd\uc744 \uc815\ub9ac\ud558\uba74 $b^2 = ac$\ub77c\ub294 \uc911\uc694\ud55c \uacf5\uc2dd\uc774 \uc720\ub3c4\ub429\ub2c8\ub2e4. \uc989, \uc138 \uc218 $a, b, c$\uac00 \ub4f1\ube44\uc218\uc5f4\uc744 \uc774\ub8f0 \ub54c, \uac00\uc6b4\ub370 \ud56d\uc758 \uc81c\uacf1\uc740 \uc591\uc606\uc758 \ub450 \ud56d\uc744 \uacf1\ud55c \uac83\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uc774\ub97c \ud1b5\ud574 $b = \\pm\\sqrt{ac}$\uc784\uc744 \uc54c \uc218 \uc788\uc73c\uba70, \uc774\ub54c $\\sqrt{ac}$\ub97c $a$\uc640 $c$\uc758 \uc591\uc758 \ub4f1\ube44\uc911\ud56d, $-\\sqrt{ac}$\ub97c \uc74c\uc758 \ub4f1\ube44\uc911\ud56d\uc774\ub77c\uace0 \ubd80\ub985\ub2c8\ub2e4.","\ub4f1\ube44\uc911\ud56d\uc740 \ub2e8\uc21c\ud788 \uc138 \uc218 \uc0ac\uc774\uc758 \uad00\uacc4\ub97c \ub118\uc5b4, \uc218\uc5f4\uc758 \uaddc\uce59\uc131\uc744 \ud30c\uc545\ud558\ub294 \ub370 \ub9e4\uc6b0 \uc720\uc6a9\ud569\ub2c8\ub2e4. \ub9cc\uc57d \uc5b4\ub5a4 \uc218\uc5f4\uc758 \uc5f0\uc18d\ub41c \uc138 \ud56d\uc774 \ub4f1\ube44\uc218\uc5f4\uc744 \uc774\ub8ec\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uba74, \ub4f1\ube44\uc911\ud56d \uacf5\uc2dd\uc744 \uc0ac\uc6a9\ud558\uc5ec \ubbf8\uc9c0\uc218\ub97c \ube60\ub974\uac8c \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub294 \ubcf5\uc7a1\ud55c \uacc4\uc0b0 \uacfc\uc815\uc744 \uc904\uc5ec\uc8fc\uba70, \ub4f1\ube44\uc218\uc5f4\uc758 \uc131\uc9c8\uc744 \uc774\ud574\ud558\ub294 \ud575\uc2ec\uc801\uc778 \ub3c4\uad6c\uac00 \ub429\ub2c8\ub2e4.","\uc608\uc81c: \uc138 \uc218 $4, x, 16$\uc774 \uc774 \uc21c\uc11c\ub300\ub85c \ub4f1\ube44\uc218\uc5f4\uc744 \uc774\ub8f0 \ub54c, \uc591\uc218 $x$\uc758 \uac12\uc744 \uad6c\ud558\uc2dc\uc624. \ud480\uc774 \ub2e8\uacc4\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uccab\uc9f8, \ub4f1\ube44\uc911\ud56d\uc758 \uc815\uc758\uc5d0 \ub530\ub77c \uac00\uc6b4\ub370 \ud56d\uc758 \uc81c\uacf1\uc740 \uc591\uc606\uc758 \ub450 \ud56d\uc758 \uacf1\uacfc \uac19\uc73c\ubbc0\ub85c $x^2 = 4 \\times 16$\uc774 \uc131\ub9bd\ud569\ub2c8\ub2e4.","\ub458\uc9f8, \uc6b0\ubcc0\uc744 \uacc4\uc0b0\ud558\uba74 $x^2 = 64$\uac00 \ub429\ub2c8\ub2e4. \uc14b\uc9f8, \uc81c\uacf1\ud558\uc5ec $64$\uac00 \ub418\ub294 \uc218\ub294 $8$\uacfc $-8$\uc785\ub2c8\ub2e4. \ubb38\uc81c\uc5d0\uc11c $x$\uac00 \uc591\uc218\ub77c\ub294 \uc870\uac74\uc774 \uc8fc\uc5b4\uc84c\uc73c\ubbc0\ub85c, \ucd5c\uc885\uc801\uc73c\ub85c \uad6c\ud558\ub294 \uac12\uc740 $x = 8$\uc785\ub2c8\ub2e4. \uc774\ucc98\ub7fc \ub4f1\ube44\uc911\ud56d \uacf5\uc2dd\uc744 \ud65c\uc6a9\ud558\uba74 \ubbf8\uc9c0\uc218 $x$\ub97c \uac04\ub2e8\ud788 \ucc3e\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),ag1,B.r)],ai2),ag1,B.r)],ai3),s3,s3,s3,s3,"concept_\ub4f1\ube44\uc911\ud56d",0,"",1,s3,B.n,"\ub300\uc218 > \uc218\uc5f4 > \ub4f1\ube44\uc218\uc5f4 > \ub4f1\ube44\uc911\ud56d",p4,ag1,s3)
p5=A.a(["\uacf5\ud1b5\uc218\ud5591","\ub2e4\ud56d\uc2dd","\ud56d\ub4f1\uc2dd","\ubbf8\uc815\uacc4\uc218\ubc95"],ai0)
p5=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5591 > \ub2e4\ud56d\uc2dd > \ud56d\ub4f1\uc2dd > \ubbf8\uc815\uacc4\uc218\ubc95 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\ubbf8\uc815\uacc4\uc218\ubc95\uc774\ub780 \ub2e4\ud56d\uc2dd\uc758 \ud56d\ub4f1\uc2dd\uc5d0\uc11c \uc544\uc9c1 \uc815\ud574\uc9c0\uc9c0 \uc54a\uc740 \uacc4\uc218\ub97c \uad6c\ud558\ub294 \ubc29\ubc95\uc744 \ub9d0\ud569\ub2c8\ub2e4. \ud56d\ub4f1\uc2dd\uc774\ub780 \ubcc0\uc218 $x$\uc5d0 \uc5b4\ub5a4 \uac12\uc744 \ub300\uc785\ud574\ub3c4 \ud56d\uc0c1 \uc131\ub9bd\ud558\ub294 \ub4f1\uc2dd\uc744 \uc758\ubbf8\ud558\ub294\ub370, \uc774\ub54c \uc591\ubcc0\uc758 \ub300\uc751\ud558\ub294 \ud56d\uc758 \uacc4\uc218\uac00 \uc11c\ub85c \uac19\ub2e4\ub294 \uc131\uc9c8\uc744 \uc774\uc6a9\ud569\ub2c8\ub2e4. \uc989, $ax^2 + bx + c = a'x^2 + b'x + c'$\uac00 $x$\uc5d0 \ub300\ud55c \ud56d\ub4f1\uc2dd\uc774 \ub418\ub824\uba74 $a=a'$, $b=b'$, $c=c'$\uac00 \ub9cc\uc871\ub418\uc5b4\uc57c \ud55c\ub2e4\ub294 \uc6d0\ub9ac\uc785\ub2c8\ub2e4.","\ubbf8\uc815\uacc4\uc218\ubc95\uc740 \ud06c\uac8c '\uacc4\uc218\ube44\uad50\ubc95'\uacfc '\uc218\uce58\ub300\uc785\ubc95' \ub450 \uac00\uc9c0\ub85c \ub098\ub269\ub2c8\ub2e4. \uacc4\uc218\ube44\uad50\ubc95\uc740 \uc591\ubcc0\uc758 \ub2e4\ud56d\uc2dd\uc744 \uc804\uac1c\ud558\uc5ec \ub0b4\ub9bc\ucc28\uc21c\uc73c\ub85c \uc815\ub9ac\ud55c \ub4a4, \uac19\uc740 \ucc28\uc218\uc758 \ud56d\ub07c\ub9ac \uacc4\uc218\ub97c \ube44\uad50\ud558\uc5ec \ubbf8\uc9c0\uc218\ub97c \uad6c\ud558\ub294 \ubc29\uc2dd\uc785\ub2c8\ub2e4. \ubc18\uba74, \uc218\uce58\ub300\uc785\ubc95\uc740 \ud56d\ub4f1\uc2dd\uc758 \uc131\uc9c8\uc744 \uc774\uc6a9\ud558\uc5ec $x$\uc5d0 \uc801\uc808\ud55c \uac12\uc744 \ub300\uc785\ud568\uc73c\ub85c\uc368 \ubbf8\uc9c0\uc218\ub97c \uad6c\ud558\ub294 \ubc29\uc2dd\uc785\ub2c8\ub2e4. \ubcf4\ud1b5 \uc2dd\uc744 \uc804\uac1c\ud558\uae30 \ubcf5\uc7a1\ud560 \ub54c\ub294 \uc218\uce58\ub300\uc785\ubc95\uc774, \uc2dd\uc758 \uad6c\uc870\uac00 \ub2e8\uc21c\ud560 \ub54c\ub294 \uacc4\uc218\ube44\uad50\ubc95\uc774 \ud6a8\uc728\uc801\uc785\ub2c8\ub2e4.","\uc608\ub97c \ub4e4\uc5b4, \ub4f1\uc2dd $ax(x-1) + b(x-1) + c = 2x^2 - 3x + 1$\uc774 \ubaa8\ub4e0 $x$\uc5d0 \ub300\ud558\uc5ec \uc131\ub9bd\ud560 \ub54c, \uacc4\uc218 $a, b, c$\ub97c \uad6c\ud574\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uacc4\uc218\ube44\uad50\ubc95\uc744 \uc0ac\uc6a9\ud558\uba74, \uc88c\ubcc0\uc744 \uc804\uac1c\ud558\uc5ec $ax^2 + (b-a)x + (c-b) = 2x^2 - 3x + 1$\ub85c \ub9cc\ub4ed\ub2c8\ub2e4. \uc774\uc81c \uac01 \ud56d\uc758 \uacc4\uc218\ub97c \ube44\uad50\ud558\uba74 $a=2$, $b-a=-3$, $c-b=1$\uc774\ub77c\ub294 \uc5f0\ub9bd\ubc29\uc815\uc2dd\uc744 \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc704\uc758 \uc5f0\ub9bd\ubc29\uc815\uc2dd\uc744 \ub2e8\uacc4\ubcc4\ub85c \ud480\uc5b4\ubd05\uc2dc\ub2e4. \uccab\uc9f8, $x^2$\uc758 \uacc4\uc218\ub97c \ube44\uad50\ud558\uba74 \uc989\uc2dc $a=2$\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub458\uc9f8, $x$\uc758 \uacc4\uc218\ub97c \ube44\uad50\ud55c \uc2dd $b-a=-3$\uc5d0 $a=2$\ub97c \ub300\uc785\ud558\uba74 $b-2=-3$\uc774 \ub418\uc5b4 $b=-1$\uc774 \ub429\ub2c8\ub2e4. \uc14b\uc9f8, \uc0c1\uc218\ud56d\uc744 \ube44\uad50\ud55c \uc2dd $c-b=1$\uc5d0 $b=-1$\uc744 \ub300\uc785\ud558\uba74 $c-(-1)=1$\uc774 \ub418\uc5b4 $c=0$\uc774 \ub098\uc635\ub2c8\ub2e4. \ub530\ub77c\uc11c \uad6c\ud558\ub294 \uacc4\uc218\ub294 $a=2, b=-1, c=0$\uc785\ub2c8\ub2e4.","\uc774\ubc88\uc5d0\ub294 \uc218\uce58\ub300\uc785\ubc95\uc744 \ud65c\uc6a9\ud55c \uc608\uc81c\ub97c \uc0b4\ud3b4\ubd05\uc2dc\ub2e4. $x^2 + 3x + 2 = a(x-1)(x-2) + b(x-2) + c$\uac00 \ud56d\ub4f1\uc2dd\uc77c \ub54c $a, b, c$\ub97c \uad6c\ud558\ub294 \ubb38\uc81c\uc785\ub2c8\ub2e4. \uc774 \uc2dd\uc740 $x=1, x=2$\ub97c \ub300\uc785\ud558\uba74 \uacc4\uc0b0\uc774 \ub9e4\uc6b0 \uac04\ud3b8\ud574\uc9d1\ub2c8\ub2e4. \uba3c\uc800 $x=1$\uc744 \ub300\uc785\ud558\uba74 $1+3+2 = a(0) + b(-1) + c$\uac00 \ub418\uc5b4 $-b+c=6$\uc744 \uc5bb\uc2b5\ub2c8\ub2e4. \ub2e4\uc74c\uc73c\ub85c $x=2$\ub97c \ub300\uc785\ud558\uba74 $4+6+2 = a(0) + b(0) + c$\uac00 \ub418\uc5b4 $c=12$\ub97c \ubc14\ub85c \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ub9c8\uc9c0\ub9c9\uc73c\ub85c $c=12$\ub97c $-b+c=6$\uc5d0 \ub300\uc785\ud558\uba74 $-b+12=6$\uc774 \ub418\uc5b4 $b=6$\uc774 \ub429\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9\uc73c\ub85c $a$\ub97c \uad6c\ud558\uae30 \uc704\ud574 $x=0$\uc744 \ub300\uc785\ud558\uba74 $2 = a(-1)(-2) + b(-2) + c$\uac00 \ub418\uace0, \uc5ec\uae30\uc5d0 $b=6, c=12$\ub97c \ub300\uc785\ud558\uba74 $2 = 2a - 12 + 12$\uac00 \ub418\uc5b4 $2a=2$, \uc989 $a=1$\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ucc98\ub7fc \ubbf8\uc815\uacc4\uc218\ubc95\uc740 \ubb38\uc81c\uc758 \ud615\ud0dc\uc5d0 \ub530\ub77c \uc801\uc808\ud55c \ubc29\ubc95\uc744 \uc120\ud0dd\ud558\uba74 \ubcf5\uc7a1\ud55c \uc2dd\ub3c4 \uc27d\uac8c \ud574\uacb0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),ag2,B.r)],ai2),ag2,B.r)],ai3),s3,s3,s3,s3,"concept_\ubbf8\uc815\uacc4\uc218\ubc95",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5591 > \ub2e4\ud56d\uc2dd > \ud56d\ub4f1\uc2dd > \ubbf8\uc815\uacc4\uc218\ubc95",p5,ag2,s3)
p6=A.a(["\uacf5\ud1b5\uc218\ud5592","\uc88c\ud45c\ud3c9\uba74","\uc120\ubd84\uc758\ub0b4\ubd84\uc810","\uc678\ubd84\uc810"],ai0)
p6=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \uc120\ubd84\uc758\ub0b4\ubd84\uc810 > \uc678\ubd84\uc810 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uc88c\ud45c\ud3c9\uba74 \uc704\uc758 \ub450 \uc810 $A(x_1, y_1)$\uacfc $B(x_2, y_2)$\ub97c \uc787\ub294 \uc120\ubd84 $AB$\uac00 \uc788\uc744 \ub54c, \uc120\ubd84 $AB$\uc758 \uc5f0\uc7a5\uc120 \uc704\uc5d0 \uc788\uc73c\uba74\uc11c $AP : BP = m : n$ ($m \\neq n$)\uc744 \ub9cc\uc871\ud558\ub294 \uc810 $P$\ub97c \uc120\ubd84 $AB$\uc758 \uc678\ubd84\uc810\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4. \ub0b4\ubd84\uc810\uc774 \uc120\ubd84 \uc548\ucabd\uc5d0\uc11c \ube44\uc728\uc744 \ub098\ub204\ub294 \uc810\uc774\ub77c\uba74, \uc678\ubd84\uc810\uc740 \uc120\ubd84 \ubc16\uc5d0\uc11c \uadf8 \ube44\uc728\uc744 \uc720\uc9c0\ud558\uba70 \uc704\uce58\ud558\ub294 \uc810\uc785\ub2c8\ub2e4. \uc774\ub54c $m > n$\uc774\uba74 \uc810 $P$\ub294 \uc810 $B$\uc758 \ubc14\uae65\ucabd\uc5d0, $m < n$\uc774\uba74 \uc810 $A$\uc758 \ubc14\uae65\ucabd\uc5d0 \uc704\uce58\ud558\uac8c \ub429\ub2c8\ub2e4.","\uc678\ubd84\uc810 $P$\uc758 \uc88c\ud45c\ub97c \uad6c\ud558\ub294 \uacf5\uc2dd\uc740 \ub0b4\ubd84\uc810 \uacf5\uc2dd\uc5d0\uc11c \ube44\uc728 \uc911 \ud558\ub098\ub97c \uc74c\uc218\ub85c \ubc14\uafb8\uc5b4 \uc0dd\uac01\ud558\uba74 \uc27d\uac8c \uc720\ub3c4\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub450 \uc810 $A(x_1, y_1)$\uacfc $B(x_2, y_2)$\ub97c $m : n$\uc73c\ub85c \uc678\ubd84\ud558\ub294 \uc810 $P(x, y)$\uc758 \uc88c\ud45c\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$P = \\left( \\frac{mx_2 - nx_1}{m - n}, \\frac{my_2 - ny_1}{m - n} \\right)$$ \uc774 \uacf5\uc2dd\uc740 $m$\uacfc $n$\uc774 \ub2e4\ub97c \ub54c\ub9cc \uc131\ub9bd\ud558\uba70, \ubd84\ubaa8\uc640 \ubd84\uc790\uc5d0 \uac01\uac01 \uc678\ubd84\ud558\ub294 \ube44\uc728\uc758 \ucc28\uc640 \uacf1\uc758 \ucc28\ub97c \uc801\uc6a9\ud558\ub294 \uac83\uc774 \ud575\uc2ec\uc785\ub2c8\ub2e4.","\uc678\ubd84\uc810\uc758 \uc131\uc9c8\uc744 \uc774\ud574\ud560 \ub54c \uac00\uc7a5 \uc911\uc694\ud55c \uac83\uc740 '\uac70\ub9ac\uc758 \ube44'\uc785\ub2c8\ub2e4. \uc810 $P$\uac00 \uc120\ubd84 $AB$\ub97c $m : n$\uc73c\ub85c \uc678\ubd84\ud55c\ub2e4\ub294 \uac83\uc740 \uc810 $P$\ub85c\ubd80\ud130 \uc810 $A$\uae4c\uc9c0\uc758 \uac70\ub9ac\uc640 \uc810 $P$\ub85c\ubd80\ud130 \uc810 $B$\uae4c\uc9c0\uc758 \uac70\ub9ac\uc758 \ube44\uac00 $m : n$\uc784\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \ub9cc\uc57d $m=n$\uc774\ub77c\uba74 \ub450 \uc810 \uc0ac\uc774\uc758 \uac70\ub9ac\uac00 \uac19\uc544\uc9c0\ubbc0\ub85c \uc678\ubd84\uc810\uc740 \uc874\uc7ac\ud558\uc9c0 \uc54a\uac8c \ub418\uba70, \uc774\ub294 \uacf5\uc2dd\uc758 \ubd84\ubaa8\uc778 $m-n$\uc774 $0$\uc774 \ub418\uc5b4 \uc815\uc758\ud560 \uc218 \uc5c6\ub294 \uc0c1\ud669\uacfc \uc77c\uce58\ud569\ub2c8\ub2e4.","\uc608\uc81c: \ub450 \uc810 $A(1, 2)$\uc640 $B(4, 8)$\uc5d0 \ub300\ud558\uc5ec \uc120\ubd84 $AB$\ub97c $2 : 1$\ub85c \uc678\ubd84\ud558\ub294 \uc810 $P$\uc758 \uc88c\ud45c\ub97c \uad6c\ud574\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uacf5\uc2dd\uc5d0 \uc8fc\uc5b4\uc9c4 \uac12\ub4e4\uc744 \ub300\uc785\ud569\ub2c8\ub2e4. \uc5ec\uae30\uc11c $x_1=1, y_1=2, x_2=4, y_2=8, m=2, n=1$\uc785\ub2c8\ub2e4. \uc678\ubd84\uc810 \uacf5\uc2dd\uc5d0 \ub530\ub77c $x$\uc88c\ud45c\uc640 $y$\uc88c\ud45c\ub97c \uac01\uac01 \uacc4\uc0b0\ud569\ub2c8\ub2e4.","\ub2e8\uacc4\ubcc4 \ud480\uc774: \uba3c\uc800 $x$\uc88c\ud45c\ub97c \uad6c\ud558\uba74 $x = \\frac{2 \\times 4 - 1 \\times 1}{2 - 1} = \\frac{8 - 1}{1} = 7$\uc785\ub2c8\ub2e4. \uc774\uc5b4\uc11c $y$\uc88c\ud45c\ub97c \uad6c\ud558\uba74 $y = \\frac{2 \\times 8 - 1 \\times 2}{2 - 1} = \\frac{16 - 2}{1} = 14$\uac00 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uad6c\ud558\ub294 \uc678\ubd84\uc810 $P$\uc758 \uc88c\ud45c\ub294 $(7, 14)$\uc785\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uc678\ubd84\uc810 \uacf5\uc2dd\uc740 \ubcf5\uc7a1\ud574 \ubcf4\uc774\uc9c0\ub9cc, \uac01 \uc88c\ud45c\uc5d0 \ub300\ud574 \ube44\ub840 \ubc30\ubd84\uacfc \uc720\uc0ac\ud55c \uc5f0\uc0b0\uc744 \uc218\ud589\ud558\uba74 \ub204\uad6c\ub098 \uc815\ud655\ud558\uac8c \uc88c\ud45c\ub97c \ucc3e\uc544\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),"\uc678\ubd84\uc810",B.r)],ai2),"\uc678\ubd84\uc810",B.r)],ai3),s3,s3,s3,s3,"concept_\uc678\ubd84\uc810",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \uc120\ubd84\uc758\ub0b4\ubd84\uc810 > \uc678\ubd84\uc810",p6,"\uc678\ubd84\uc810",s3)
p7=A.a(["\ubbf8\uc801\ubd84\u2160","\ud568\uc218\uc758\uc99d\uac00\uc640\uac10\uc18c","\uac10\uc18c\ud568\uc218"],ai0)
p7=A.ay(s2,A.a([A.aA(A.a(["\ubbf8\uc801\ubd84\u2160 > \ud568\uc218\uc758\uc99d\uac00\uc640\uac10\uc18c > \uac10\uc18c\ud568\uc218 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(['[   "\ud568\uc218\uc758 \uc99d\uac00\uc640 \uac10\uc18c\ub294 \uadf8\ub798\ud504\uc758 \ubaa8\uc591\uc744 \uacb0\uc815\ud558\ub294 \ub9e4\uc6b0 \uc911\uc694\ud55c \uc694\uc18c\uc785\ub2c8\ub2e4. \uc5b4\ub5a4 \uad6c\uac04\uc5d0 \uc18d\ud558\ub294 \uc784\uc758\uc758 \ub450 \uc2e4\uc218 $x_1, x_2$\uc5d0 \ub300\ud558\uc5ec $x_1 < x_2$\uc77c \ub54c, \ud568\uc22b\uac12\uc758 \ub300\uc18c \uad00\uacc4\uac00 $f(x_1) > f(x_2)$\ub97c \ub9cc\uc871\ud558\uba74 \ud568\uc218 $f(x)$\ub294 \uadf8 \uad6c\uac04\uc5d0\uc11c \'\uac10\uc18c\ud55c\ub2e4\'\uace0 \ud569\ub2c8\ub2e4. \uc989, $x$\uc758 \uac12\uc774 \ucee4\uc9c8\uc218\ub85d \ub300\uc751\ud558\ub294 $y$\uc758 \uac12\uc740 \uc810\uc810 \uc791\uc544\uc9c0\ub294 \uc0c1\ud0dc\ub97c \uc758\ubbf8\ud558\uba70, \uadf8\ub798\ud504\ub97c \uc67c\ucabd\uc5d0\uc11c \uc624\ub978\ucabd\uc73c\ub85c \ub530\ub77c\uac14\uc744 \ub54c \uc544\ub798\ub85c \ub0b4\ub824\uac00\ub294 \ubaa8\uc591\uc744 \ub760\uac8c \ub429\ub2c8\ub2e4.",   "\ubbf8\ubd84\uac00\ub2a5\ud55c \ud568\uc218 $f(x)$\uc5d0 \ub300\ud558\uc5ec, \uc5b4\ub5a4 \uad6c\uac04\uc5d0\uc11c $f\'(x) < 0$\uc774\uba74 \ud568\uc218 $f(x)$\ub294 \uadf8 \uad6c\uac04\uc5d0\uc11c \uac10\uc18c\ud569\ub2c8\ub2e4. \ub610\ud55c, \uad6c\uac04 \ub0b4\uc758 \ubaa8\ub4e0 $x$\uc5d0 \ub300\ud558\uc5ec $f\'(x) \\leq 0$\uc774\ub354\ub77c\ub3c4 \ud568\uc218\uac00 \ud2b9\uc815 \uc9c0\uc810\uc5d0\uc11c \uc7a0\uc2dc \uba48\ucd9c \ubfd0 \uc804\uccb4\uc801\uc73c\ub85c \uac10\uc18c\ud558\ub294 \uacbd\ud5a5\uc744 \ubcf4\uc778\ub2e4\uba74 \uc774\ub97c \uac10\uc18c\ud568\uc218\ub85c \uc815\uc758\ud569\ub2c8\ub2e4. \uc774\ub97c \uc218\uc2dd\uc73c\ub85c \uc815\ub9ac\ud558\uba74, \uad6c\uac04 \ub0b4\uc758 \ubaa8\ub4e0 $x$\uc5d0 \ub300\ud558\uc5ec $$f\'(x) \\leq 0$$\uc77c \ub54c, \ud568\uc218 $f(x)$\ub294 \ud574\ub2f9 \uad6c\uac04\uc5d0\uc11c \uac10\uc18c\ud55c\ub2e4\uace0 \ub9d0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.",   "\uac10\uc18c\ud568\uc218\uc758 \uc131\uc9c8\uc744 \uc774\ud574\ud560 \ub54c \uc8fc\uc758\ud560 \uc810\uc740 \ub3c4\ud568\uc218\uc758 \ubd80\ud638\uc785\ub2c8\ub2e4. \ub3c4\ud568\uc218 $f\'(x)$\ub294 \uadf8\ub798\ud504\uc758 \uc811\uc120\uc758 \uae30\uc6b8\uae30\ub97c \uc758\ubbf8\ud558\ubbc0\ub85c, \uc811\uc120\uc758 \uae30\uc6b8\uae30\uac00 \uc74c\uc218\ub77c\ub294 \uac83\uc740 \uadf8\ub798\ud504\uac00 \uc624\ub978\ucabd \uc544\ub798\ub85c \ud5a5\ud558\uace0 \uc788\uc74c\uc744 \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \ub530\ub77c\uc11c \ud568\uc218\uac00 \uac10\uc18c\ud558\ub294 \uad6c\uac04\uc744 \ucc3e\uc73c\ub824\uba74 \uba3c\uc800 \uc8fc\uc5b4\uc9c4 \ud568\uc218\ub97c \ubbf8\ubd84\ud558\uc5ec \ub3c4\ud568\uc218\ub97c \uad6c\ud55c \ub4a4, \uadf8 \ub3c4\ud568\uc218\uac00 0\ubcf4\ub2e4 \uc791\uac70\ub098 \uac19\uc740 \ubc94\uc704\ub97c \ucc3e\uc544\ub0b4\uba74 \ub429\ub2c8\ub2e4.",   "\uc608\uc81c: \ud568\uc218 $f(x) = -x^3 + 3x^2 + 9x + 5$\uac00 \uac10\uc18c\ud558\ub294 \uad6c\uac04\uc744 \uad6c\ud558\uc2dc\uc624. \uba3c\uc800 \ud568\uc218\ub97c \ubbf8\ubd84\ud558\uc5ec \ub3c4\ud568\uc218 $f\'(x)$\ub97c \uad6c\ud569\ub2c8\ub2e4. $$f\'(x) = -3x^2 + 6x + 9$$ \uc785\ub2c8\ub2e4. \ud568\uc218\uac00 \uac10\uc18c\ud558\uae30 \uc704\ud574\uc11c\ub294 $f\'(x) \\leq 0$\uc774\uc5b4\uc57c \ud558\ubbc0\ub85c, \ubd80\ub4f1\uc2dd $-3x^2 + 6x + 9 \\leq 0$\uc744 \ud480\uc5b4\uc57c \ud569\ub2c8\ub2e4.",   "\uc704 \ubd80\ub4f1\uc2dd\uc758 \uc591\ubcc0\uc744 $-3$\uc73c\ub85c \ub098\ub204\uba74 \ubd80\ub4f1\ud638\uc758 \ubc29\ud5a5\uc774 \ubc14\ub00c\uc5b4 $$x^2 - 2x - 3 \\geq 0$$\uc774 \ub429\ub2c8\ub2e4. \uc774\ub97c \uc778\uc218\ubd84\ud574\ud558\uba74 $$(x - 3)(x + 1) \\geq 0$$\uc774 \ub429\ub2c8\ub2e4. \uc774\ucc28\ubd80\ub4f1\uc2dd\uc758 \ud574\ub97c \uad6c\ud558\uba74 $x \\leq -1$ \ub610\ub294 $x \\geq 3$\uc774 \ub098\uc635\ub2c8\ub2e4. \ub530\ub77c\uc11c \ud568\uc218 $f(x)$\ub294 \uad6c\uac04 $(-\\\\infty, -1]$\uacfc $[3, \\\\infty)$\uc5d0\uc11c \uac10\uc18c\ud55c\ub2e4\uace0 \uacb0\ub860 \ub0b4\ub9b4 \uc218 \uc788\uc2b5\ub2c8\ub2e4." ]'],ai0),ag3,B.r)],ai2),ag3,B.r)],ai3),s3,s3,s3,s3,"concept_\uac10\uc18c\ud568\uc218",0,"",1,s3,B.n,"\ubbf8\uc801\ubd84\u2160 > \ud568\uc218\uc758\uc99d\uac00\uc640\uac10\uc18c > \uac10\uc18c\ud568\uc218",p7,ag3,s3)
p8=A.a(["\uacf5\ud1b5\uc218\ud5591","\uc774\ucc28\ud568\uc218","\uc774\ucc28\ud568\uc218\uc640\uc774\ucc28\ubc29\uc815\uc2dd"],ai0)
p8=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5591 > \uc774\ucc28\ud568\uc218 > \uc774\ucc28\ud568\uc218\uc640\uc774\ucc28\ubc29\uc815\uc2dd \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uc774\ucc28\ud568\uc218 $y = ax^2 + bx + c$ ($a \\neq 0$)\uc758 \uadf8\ub798\ud504\uc640 $x$\ucd95\uc758 \uad50\uc810\uc740 \uc774\ucc28\ud568\uc218\uc758 \ud568\uc22b\uac12\uc774 $0$\uc774 \ub418\ub294 \uc9c0\uc810, \uc989 $ax^2 + bx + c = 0$\uc744 \ub9cc\uc871\ud558\ub294 $x$\uc758 \uac12\uacfc \uac19\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc774\ucc28\ud568\uc218\uc758 \uadf8\ub798\ud504\uac00 $x$\ucd95\uacfc \ub9cc\ub098\ub294 \uc810\uc758 $x$\uc88c\ud45c\ub294 \uc774\ucc28\ubc29\uc815\uc2dd\uc758 \uc2e4\uadfc\uacfc \uc77c\uce58\ud569\ub2c8\ub2e4. \uadf8\ub798\ud504\uac00 $x$\ucd95\uacfc \ub9cc\ub098\ub294 \uc704\uce58\uc640 \uac1c\uc218\ub294 \uc774\ucc28\ubc29\uc815\uc2dd\uc758 \ud310\ubcc4\uc2dd $D = b^2 - 4ac$\uc758 \ubd80\ud638\uc5d0 \ub530\ub77c \uacb0\uc815\ub429\ub2c8\ub2e4.","\ud310\ubcc4\uc2dd $D$\uc758 \uac12\uc5d0 \ub530\ub978 \uc774\ucc28\ud568\uc218 \uadf8\ub798\ud504\uc640 $x$\ucd95\uc758 \uc704\uce58 \uad00\uacc4\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uccab\uc9f8, $D > 0$\uc774\uba74 \uc11c\ub85c \ub2e4\ub978 \ub450 \uc810\uc5d0\uc11c \ub9cc\ub098\uace0, \ub458\uc9f8, $D = 0$\uc774\uba74 \ud55c \uc810(\uaf2d\uc9d3\uc810)\uc5d0\uc11c \uc811\ud558\uba70, \uc14b\uc9f8, $D < 0$\uc774\uba74 $x$\ucd95\uacfc \ub9cc\ub098\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uc774\ucc28\ud568\uc218\uc758 \uadf8\ub798\ud504\ub97c \ud1b5\ud574 \uc774\ucc28\ubc29\uc815\uc2dd\uc758 \uadfc\uc758 \uac1c\uc218\ub97c \uae30\ud558\ud559\uc801\uc73c\ub85c \ud574\uc11d\ud560 \uc218 \uc788\uc73c\uba70, \uc774\ub294 \ud568\uc218\uc640 \ubc29\uc815\uc2dd\uc774 \uc11c\ub85c \ubc00\uc811\ud558\uac8c \uc5f0\uacb0\ub418\uc5b4 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uc911\uc694\ud55c \uc6d0\ub9ac\uc785\ub2c8\ub2e4.","\uc774\uc81c \uc774\ucc28\ud568\uc218 $y = x^2 - 4x + 3$\uc758 \uadf8\ub798\ud504\uc640 $x$\ucd95\uc758 \uad50\uc810 \uc88c\ud45c\ub97c \uad6c\ud558\ub294 \uc608\uc81c\ub97c \uc0b4\ud3b4\ubd05\uc2dc\ub2e4. \uad50\uc810\uc744 \uad6c\ud558\uae30 \uc704\ud574\uc11c\ub294 \ud568\uc22b\uac12 $y$\uc5d0 $0$\uc744 \ub300\uc785\ud558\uc5ec \uc774\ucc28\ubc29\uc815\uc2dd $x^2 - 4x + 3 = 0$\uc744 \uc138\uc6cc\uc57c \ud569\ub2c8\ub2e4. \uc774 \ubc29\uc815\uc2dd\uc740 \uc778\uc218\ubd84\ud574\ub97c \ud1b5\ud574 $(x - 1)(x - 3) = 0$\uc73c\ub85c \ubcc0\ud615\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc704\uc758 \uc2dd\uc744 \ud480\uba74 $x = 1$ \ub610\ub294 $x = 3$\uc774\ub77c\ub294 \ub450 \uac1c\uc758 \uadfc\uc744 \uc5bb\uac8c \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc774\ucc28\ud568\uc218 $y = x^2 - 4x + 3$\uc758 \uadf8\ub798\ud504\ub294 $x$\ucd95\uacfc \uc810 $(1, 0)$\uacfc $(3, 0)$\uc5d0\uc11c \ub9cc\ub09c\ub2e4\ub294 \uac83\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uc774\ucc28\ubc29\uc815\uc2dd\uc758 \ud574\ub97c \uad6c\ud558\ub294 \uacfc\uc815\uc740 \uace7 \uc774\ucc28\ud568\uc218 \uadf8\ub798\ud504\uc758 \uc808\ud3b8\uc744 \ucc3e\ub294 \uacfc\uc815\uacfc \ub3d9\uc77c\ud569\ub2c8\ub2e4.","\ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc774\ucc28\ud568\uc218 $y = x^2 - 2x + 2$\uac00 $x$\ucd95\uacfc \ub9cc\ub098\ub294\uc9c0 \ud655\uc778\ud574 \ubd05\uc2dc\ub2e4. \ud310\ubcc4\uc2dd $D = b^2 - 4ac$\uc5d0 \uacc4\uc218\ub97c \ub300\uc785\ud558\uba74 $D = (-2)^2 - 4 \\times 1 \\times 2 = 4 - 8 = -4$\uac00 \ub429\ub2c8\ub2e4. \ud310\ubcc4\uc2dd\uc758 \uac12\uc774 $0$\ubcf4\ub2e4 \uc791\uc73c\ubbc0\ub85c, \uc774 \uc774\ucc28\ud568\uc218\uc758 \uadf8\ub798\ud504\ub294 $x$\ucd95\uacfc \ub9cc\ub098\uc9c0 \uc54a\ub294\ub2e4\ub294 \uacb0\ub860\uc744 \ub0b4\ub9b4 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),ag4,B.r)],ai2),ag4,B.r)],ai3),s3,s3,s3,s3,"concept_\uc774\ucc28\ud568\uc218\uc640\uc774\ucc28\ubc29\uc815\uc2dd",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5591 > \uc774\ucc28\ud568\uc218 > \uc774\ucc28\ud568\uc218\uc640\uc774\ucc28\ubc29\uc815\uc2dd",p8,ag4,s3)
p9=A.a(["\ub300\uc218","\uc9c0\uc218","\uc9c0\uc218\uc758\ud655\uc7a5","\uc2e4\uc218\uc9c0\uc218"],ai0)
p9=A.ay(s2,A.a([A.aA(A.a(["\ub300\uc218 > \uc9c0\uc218 > \uc9c0\uc218\uc758\ud655\uc7a5 > \uc2e4\uc218\uc9c0\uc218 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uc9c0\uc218\uc758 \ud655\uc7a5\uc740 \uc790\uc5f0\uc218\uc5d0\uc11c \uc815\uc218\ub85c, \ub2e4\uc2dc \uc720\ub9ac\uc218\ub85c \ud655\uc7a5\ub418\ub294 \uacfc\uc815\uc744 \uac70\uccd0 \ucd5c\uc885\uc801\uc73c\ub85c \uc2e4\uc218 \uc804\uccb4\uc758 \ubc94\uc704\uae4c\uc9c0 \ub113\uc5b4\uc9d1\ub2c8\ub2e4. \uc2e4\uc218\uc9c0\uc218\ub780 \uc9c0\uc218 \uc790\ub9ac\uc5d0 \uc720\ub9ac\uc218\uac00 \uc544\ub2cc \ubb34\ub9ac\uc218(\uc608: $\\sqrt{2}, \\pi$ \ub4f1)\uac00 \uc624\ub294 \uacbd\uc6b0\ub97c \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc720\ub9ac\uc218 \uc9c0\uc218 $a^r$ ($a>0, r$\uc740 \uc720\ub9ac\uc218)\uac00 \uc815\uc758\ub420 \ub54c, \ubb34\ub9ac\uc218 \uc9c0\uc218 $a^x$ ($x$\ub294 \ubb34\ub9ac\uc218)\ub294 $x$\uc5d0 \ud55c\uc5c6\uc774 \uac00\uae4c\uc6cc\uc9c0\ub294 \uc720\ub9ac\uc218\ub4e4\uc758 \uc218\uc5f4\uc744 \uc774\uc6a9\ud558\uc5ec \uadf8 \uadf9\ud55c\uac12\uc73c\ub85c \uc815\uc758\ud569\ub2c8\ub2e4. \uc774\ub54c \ubc11 $a$\ub294 \ud56d\uc0c1 \uc591\uc218($a>0$)\uc5ec\uc57c \ud55c\ub2e4\ub294 \uc810\uc774 \ub9e4\uc6b0 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc2e4\uc218\uc9c0\uc218\uc5d0\uc11c\ub3c4 \uc9c0\uc218\ubc95\uce59\uc740 \uadf8\ub300\ub85c \uc131\ub9bd\ud569\ub2c8\ub2e4. $a>0, b>0$\uc774\uace0 $x, y$\uac00 \uc784\uc758\uc758 \uc2e4\uc218\uc77c \ub54c, \ub2e4\uc74c\uc758 \ud575\uc2ec \uacf5\uc2dd\ub4e4\uc774 \uc131\ub9bd\ud569\ub2c8\ub2e4. \uccab\uc9f8, $a^x \\cdot a^y = a^{x+y}$\uc774\uba70, \ub458\uc9f8, $(a^x)^y = a^{xy}$\uc785\ub2c8\ub2e4. \uc14b\uc9f8, $(ab)^x = a^x b^x$\uc774\uace0, \ub137\uc9f8, $a^x / a^y = a^{x-y}$\uc785\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc131\uc9c8\ub4e4\uc740 \uc9c0\uc218\uac00 \uc2e4\uc218 \ubc94\uc704\ub85c \ud655\uc7a5\ub418\uc5b4\ub3c4 \uc9c0\uc218\ubc95\uce59\uc774 \uc77c\uad00\ub418\uac8c \uc801\uc6a9\ub428\uc744 \ubcf4\uc5ec\uc8fc\uba70, \uc774\ub294 \ubcf5\uc7a1\ud55c \uc218\uc2dd\uc744 \uac04\uacb0\ud558\uac8c \uacc4\uc0b0\ud558\ub294 \uac15\ub825\ud55c \ub3c4\uad6c\uac00 \ub429\ub2c8\ub2e4.","\uc2e4\uc218\uc9c0\uc218\ub97c \ud65c\uc6a9\ud558\uba74 $2^{\\sqrt{2}}$\uc640 \uac19\uc774 \uc9c1\uad00\uc801\uc73c\ub85c \uacc4\uc0b0\ud558\uae30 \uc5b4\ub824\uc6b4 \uac12\ub3c4 \uc218\uc5f4\uc758 \uadf9\ud55c\uc744 \ud1b5\ud574 \uadf8 \uc704\uce58\ub97c \ud30c\uc545\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, $\\sqrt{2} \\approx 1.414...$\uc774\ubbc0\ub85c $2^{1.4}, 2^{1.41}, 2^{1.414}, \\dots$\uc640 \uac19\uc740 \uac12\ub4e4\uc744 \ucc28\ub840\ub85c \uacc4\uc0b0\ud558\uba74 \ud558\ub098\uc758 \uc77c\uc815\ud55c \uac12\uc73c\ub85c \uc218\ub834\ud558\uac8c \ub418\ub294\ub370, \uc774 \uac12\uc744 $2^{\\sqrt{2}}$\ub85c \uc815\uc758\ud558\ub294 \uac83\uc785\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uc2e4\uc218\uc9c0\uc218\ub294 \uc9c0\uc218\ud568\uc218\uc758 \uc5f0\uc18d\uc131\uc744 \ubcf4\uc7a5\ud558\uba70, \uc218\ud559\uc801 \ubaa8\ub378\ub9c1\uc5d0\uc11c \uc131\uc7a5\uacfc \uac10\uc1e0\ub97c \ub2e4\ub8f0 \ub54c \ud544\uc218\uc801\uc778 \uac1c\ub150\uc785\ub2c8\ub2e4.","\uc608\uc81c: \ub2e4\uc74c \uc2dd\uc744 \uac04\ub2e8\ud788 \ud558\uc2dc\uc624. $(3^{\\sqrt{2}})^{\\sqrt{8}} \\div 3^2$. \uc774 \ubb38\uc81c\ub97c \ud480\uae30 \uc704\ud574\uc11c\ub294 \uc9c0\uc218\ubc95\uce59 $(a^x)^y = a^{xy}$\uc640 $a^x \\div a^y = a^{x-y}$\ub97c \uc21c\ucc28\uc801\uc73c\ub85c \uc801\uc6a9\ud574\uc57c \ud569\ub2c8\ub2e4. \uba3c\uc800 \uad04\ud638 \uc548\uc758 \uc9c0\uc218\ub97c \uacc4\uc0b0\ud558\uba74 $\\sqrt{2} \\times \\sqrt{8} = \\sqrt{16} = 4$\uac00 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc2dd\uc740 $3^4 \\div 3^2$\uc774 \ub429\ub2c8\ub2e4.","\ub2e8\uacc4\ubcc4 \ud480\uc774\ub97c \uc9c4\ud589\ud558\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uccab\uc9f8, $(3^{\\sqrt{2}})^{\\sqrt{8}} = 3^{\\sqrt{2} \\times \\sqrt{8}} = 3^{\\sqrt{16}} = 3^4$\uc785\ub2c8\ub2e4. \ub458\uc9f8, \uc774\ub97c \ub098\ub217\uc148 \uc2dd\uc5d0 \ub300\uc785\ud558\uba74 $3^4 \\div 3^2$\uc774 \ub429\ub2c8\ub2e4. \uc14b\uc9f8, \uc9c0\uc218\ubc95\uce59 $a^x \\div a^y = a^{x-y}$\uc5d0 \uc758\ud574 $3^{4-2} = 3^2$\uc774 \ub429\ub2c8\ub2e4. \ucd5c\uc885\uc801\uc73c\ub85c $3^2 = 9$\ub77c\ub294 \uac12\uc744 \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),ag5,B.r)],ai2),ag5,B.r)],ai3),s3,s3,s3,s3,"concept_\uc2e4\uc218\uc9c0\uc218",0,"",1,s3,B.n,"\ub300\uc218 > \uc9c0\uc218 > \uc9c0\uc218\uc758\ud655\uc7a5 > \uc2e4\uc218\uc9c0\uc218",p9,ag5,s3)
q0=A.a(["\uacf5\ud1b5\uc218\ud5592","\uba85\uc81c","\uba85\uc81c\uc758\uc5ed\uacfc\ub300\uc6b0","\ub300\uc6b0"],ai0)
q0=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uba85\uc81c > \uba85\uc81c\uc758\uc5ed\uacfc\ub300\uc6b0 > \ub300\uc6b0 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uba85\uc81c '\uc774\uba74 $p$\uc774\uba74 $q$\uc774\ub2e4'\ub97c \uae30\ud638\ub85c $p \\implies q$\ub77c\uace0 \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uac00\uc815\uc778 $p$\uc640 \uacb0\ub860\uc778 $q$\uc758 \uc704\uce58\ub97c \ubc14\uafb8\uace0, \uac01\uac01\uc744 \ubd80\uc815\ud558\uc5ec '\uc774\uba74 $q$\uac00 \uc544\ub2c8\uba74 $p$\uac00 \uc544\ub2c8\ub2e4'\ub85c \ub9cc\ub4e0 \uba85\uc81c\ub97c \uc6d0\ub798 \uba85\uc81c\uc758 '\ub300\uc6b0'\ub77c\uace0 \ud569\ub2c8\ub2e4. \uc774\ub97c \uae30\ud638\ub85c \ub098\ud0c0\ub0b4\uba74 $\\neg q \\implies \\neg p$\uac00 \ub429\ub2c8\ub2e4. \ub300\uc6b0\ub294 \uba85\uc81c\uc640 \ub9e4\uc6b0 \ud2b9\ubcc4\ud55c \uad00\uacc4\ub97c \ub9fa\uace0 \uc788\ub294\ub370, \uc6d0\ub798 \uba85\uc81c\uac00 \ucc38\uc774\uba74 \uadf8 \ub300\uc6b0\ub3c4 \ubc18\ub4dc\uc2dc \ucc38\uc774\uace0, \uc6d0\ub798 \uba85\uc81c\uac00 \uac70\uc9d3\uc774\uba74 \uadf8 \ub300\uc6b0\ub3c4 \ubc18\ub4dc\uc2dc \uac70\uc9d3\uc774\ub77c\ub294 \uc131\uc9c8\uc774 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\ub7ec\ud55c \uc131\uc9c8\uc774 \uc911\uc694\ud55c \uc774\uc720\ub294 \uc5b4\ub5a4 \uba85\uc81c\uc758 \ucc38\uacfc \uac70\uc9d3\uc744 \ud310\ubcc4\ud558\uae30 \uc5b4\ub824\uc6b8 \ub54c, \uadf8 \ub300\uc6b0\ub97c \uc774\uc6a9\ud558\uba74 \ud6e8\uc52c \uc27d\uac8c \ud574\uacb0\ud560 \uc218 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, '\uc5b4\ub5a4 \uc870\uac74\uc774 \ubcf5\uc7a1\ud558\uac8c \uc5bd\ud600 \uc788\uc5b4 \uc9c1\uc811 \uc99d\uba85\ud558\uae30 \ud798\ub4e4 \ub54c' \uadf8 \ub300\uc6b0\ub97c \uad6c\ud558\uc5ec \uc99d\uba85\ud558\uba74 \ub17c\ub9ac\uc801\uc73c\ub85c \uc644\ubcbd\ud558\uac8c \uc6d0\ub798 \uba85\uc81c\uc758 \ucc38, \uac70\uc9d3\uc744 \ubc1d\ud600\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc218\ud559\uc5d0\uc11c \ub300\uc6b0\ub294 \ubcf5\uc7a1\ud55c \ubb38\uc81c\ub97c \ub2e8\uc21c\ud55c \ubb38\uc81c\ub85c \ubc14\uafb8\uc5b4 \ud574\uacb0\ud558\ub294 \uac15\ub825\ud55c \ub3c4\uad6c\ub85c \uc0ac\uc6a9\ub429\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud1b5\ud574 \ub300\uc6b0\ub97c \uad6c\ud558\ub294 \ubc29\ubc95\uc744 \uc54c\uc544\ubd05\uc2dc\ub2e4. \uba85\uc81c '$x$\uac00 \ud640\uc218\uc774\uba74 $x^2$\uc740 \ud640\uc218\uc774\ub2e4'\ub77c\ub294 \ubb38\uc7a5\uc774 \uc788\uc744 \ub54c, \uc774 \uba85\uc81c\uc758 \ub300\uc6b0\ub97c \uad6c\ud574\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uac00\uc815\uc778 '$x$\uac00 \ud640\uc218\uc774\ub2e4'\uc758 \ubd80\uc815\uc740 '$x$\uac00 \uc9dd\uc218\uc774\ub2e4'\uac00 \ub418\uace0, \uacb0\ub860\uc778 '$x^2$\uc740 \ud640\uc218\uc774\ub2e4'\uc758 \ubd80\uc815\uc740 '$x^2$\uc740 \uc9dd\uc218\uc774\ub2e4'\uac00 \ub429\ub2c8\ub2e4. \uc774\uc81c \uac00\uc815\uacfc \uacb0\ub860\uc758 \uc704\uce58\ub97c \ubc14\uafb8\uc5b4 \uc5f0\uacb0\ud558\uba74 \ub300\uc6b0\ub294 '$x^2$\uc774 \uc9dd\uc218\uc774\uba74 $x$\ub294 \uc9dd\uc218\uc774\ub2e4'\uac00 \ub429\ub2c8\ub2e4.","\ub610 \ub2e4\ub978 \uc608\uc81c\ub85c, '\ub450 \uc2e4\uc218 $a, b$\uc5d0 \ub300\ud558\uc5ec $a+b > 2$\uc774\uba74 $a > 1$ \ub610\ub294 $b > 1$\uc774\ub2e4'\ub77c\ub294 \uba85\uc81c\uc758 \ub300\uc6b0\ub97c \uad6c\ud574\ubd05\uc2dc\ub2e4. \uc5ec\uae30\uc11c '\ub610\ub294'\uc758 \ubd80\uc815\uc740 '\uadf8\ub9ac\uace0'\uac00 \ub428\uc744 \uc8fc\uc758\ud574\uc57c \ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c \uac00\uc815\uacfc \uacb0\ub860\uc758 \uc704\uce58\ub97c \ubc14\uafb8\uace0 \uac01\uac01\uc744 \ubd80\uc815\ud558\uba74, \ub300\uc6b0\ub294 '$a \\le 1$\uc774\uace0 $b \\le 1$\uc774\uba74 $a+b \\le 2$\uc774\ub2e4'\uac00 \ub429\ub2c8\ub2e4. \uc774\ucc98\ub7fc \ub300\uc6b0\ub97c \uad6c\ud560 \ub54c\ub294 '\uadf8\ub9ac\uace0'\uc640 '\ub610\ub294'\uc758 \uad00\uacc4\uac00 \uc11c\ub85c \ubc14\ub010\ub2e4\ub294 \uc810\uc744 \ud56d\uc0c1 \uae30\uc5b5\ud574\uc57c \ud569\ub2c8\ub2e4.","\ub9c8\uc9c0\ub9c9\uc73c\ub85c \ub300\uc6b0\ub97c \uc774\uc6a9\ud55c \uc99d\uba85 \ubb38\uc81c\ub97c \ud480\uc5b4\ubd05\uc2dc\ub2e4. '\uc790\uc5f0\uc218 $n$\uc5d0 \ub300\ud558\uc5ec $n^2$\uc774 3\uc758 \ubc30\uc218\uc774\uba74 $n$\ub3c4 3\uc758 \ubc30\uc218\uc774\ub2e4'\ub77c\ub294 \uba85\uc81c\ub97c \uc99d\uba85\ud558\uae30 \uc704\ud574 \ub300\uc6b0\ub97c \uc774\uc6a9\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uc774 \uba85\uc81c\uc758 \ub300\uc6b0\ub294 '$n$\uc774 3\uc758 \ubc30\uc218\uac00 \uc544\ub2c8\uba74 $n^2$\ub3c4 3\uc758 \ubc30\uc218\uac00 \uc544\ub2c8\ub2e4'\uc785\ub2c8\ub2e4. $n$\uc774 3\uc758 \ubc30\uc218\uac00 \uc544\ub2c8\uba74 $n$\uc740 $3k+1$ \ub610\ub294 $3k+2$ (\ub2e8, $k$\ub294 0 \uc774\uc0c1\uc758 \uc815\uc218) \uaf34\ub85c \ub098\ud0c0\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uccab\uc9f8, $n = 3k+1$\uc77c \ub54c $n^2 = (3k+1)^2 = 9k^2 + 6k + 1 = 3(3k^2 + 2k) + 1$\uc774 \ub418\uc5b4 3\uc758 \ubc30\uc218\uac00 \uc544\ub2d9\ub2c8\ub2e4. \ub458\uc9f8, $n = 3k+2$\uc77c \ub54c $n^2 = (3k+2)^2 = 9k^2 + 12k + 4 = 3(3k^2 + 4k + 1) + 1$\uc774 \ub418\uc5b4 \uc5ed\uc2dc 3\uc758 \ubc30\uc218\uac00 \uc544\ub2d9\ub2c8\ub2e4. \ub300\uc6b0\uac00 \ucc38\uc784\uc744 \ud655\uc778\ud588\uc73c\ubbc0\ub85c, \uc6d0\ub798 \uba85\uc81c\uc778 '$n^2$\uc774 3\uc758 \ubc30\uc218\uc774\uba74 $n$\ub3c4 3\uc758 \ubc30\uc218\uc774\ub2e4'\ub3c4 \ucc38\uc774\ub77c\ub294 \uacb0\ub860\uc744 \ub0b4\ub9b4 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),"\ub300\uc6b0",B.r)],ai2),"\ub300\uc6b0",B.r)],ai3),s3,s3,s3,s3,"concept_\ub300\uc6b0",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5592 > \uba85\uc81c > \uba85\uc81c\uc758\uc5ed\uacfc\ub300\uc6b0 > \ub300\uc6b0",q0,"\ub300\uc6b0",s3)
q1=A.a(["\uacf5\ud1b5\uc218\ud5591","\ub2e4\ud56d\uc2dd","\ub098\uba38\uc9c0\uc815\ub9ac","\ub098\uba38\uc9c0\uc815\ub9ac\uc99d\uba85"],ai0)
q1=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5591 > \ub2e4\ud56d\uc2dd > \ub098\uba38\uc9c0\uc815\ub9ac > \ub098\uba38\uc9c0\uc815\ub9ac\uc99d\uba85 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\ub098\uba38\uc9c0\uc815\ub9ac\ub780 \ub2e4\ud56d\uc2dd $P(x)$\ub97c \uc77c\ucc28\uc2dd $x-a$\ub85c \ub098\ub204\uc5c8\uc744 \ub54c\uc758 \ub098\uba38\uc9c0\ub97c \uc9c1\uc811 \ub098\ub217\uc148\uc744 \ud558\uc9c0 \uc54a\uace0\ub3c4 \uac04\ub2e8\ud788 \uad6c\ud560 \uc218 \uc788\ub294 \uc815\ub9ac\uc785\ub2c8\ub2e4. \ub2e4\ud56d\uc2dd $P(x)$\ub97c $x-a$\ub85c \ub098\ub204\uc5c8\uc744 \ub54c\uc758 \ubaab\uc744 $Q(x)$, \ub098\uba38\uc9c0\ub97c $R$\uc774\ub77c\uace0 \ud558\uba74, \ub098\ub217\uc148\uc758 \uc6d0\ub9ac\uc5d0 \uc758\ud574 $P(x) = (x-a)Q(x) + R$\uc774\ub77c\ub294 \ud56d\ub4f1\uc2dd\uc774 \uc131\ub9bd\ud569\ub2c8\ub2e4. \uc774\ub54c \ub098\uba38\uc9c0\ub294 \ub098\ub204\ub294 \uc2dd\uc758 \ucc28\uc218\ubcf4\ub2e4 \ub0ae\uc544\uc57c \ud558\ubbc0\ub85c, \uc77c\ucc28\uc2dd\uc73c\ub85c \ub098\ub204\uc5c8\uc744 \ub54c\uc758 \ub098\uba38\uc9c0 $R$\uc740 \uc0c1\uc218\ud56d\uc774 \ub429\ub2c8\ub2e4.","\uc774 \ud56d\ub4f1\uc2dd\uc5d0\uc11c $x$\uc5d0 \uc5b4\ub5a4 \uac12\uc744 \ub300\uc785\ud574\ub3c4 \ub4f1\uc2dd\uc740 \ud56d\uc0c1 \uc131\ub9bd\ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c $x$ \ub300\uc2e0 $a$\ub97c \ub300\uc785\ud558\uba74 $P(a) = (a-a)Q(a) + R$\uc774 \ub429\ub2c8\ub2e4. \uc5ec\uae30\uc11c $(a-a)$\ub294 $0$\uc774\ubbc0\ub85c $0 \\cdot Q(a)$\ub294 \uc0ac\ub77c\uc9c0\uace0, \uacb0\uacfc\uc801\uc73c\ub85c $P(a) = R$\uc774\ub77c\ub294 \uacb0\ub860\uc744 \uc5bb\uac8c \ub429\ub2c8\ub2e4. \uc989, \ub2e4\ud56d\uc2dd $P(x)$\ub97c $x-a$\ub85c \ub098\ub208 \ub098\uba38\uc9c0\ub294 \ub2e4\ud56d\uc2dd\uc5d0 $x=a$\ub97c \ub300\uc785\ud55c \uac12\uc778 $P(a)$\uc640 \uac19\uc2b5\ub2c8\ub2e4.","\uc774 \uc131\uc9c8\uc744 \ud655\uc7a5\ud558\uba74 $P(x)$\ub97c $ax+b$ \uaf34\uc758 \uc77c\ucc28\uc2dd\uc73c\ub85c \ub098\ub20c \ub54c\ub3c4 \uc801\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. $P(x) = (ax+b)Q(x) + R$\uc5d0\uc11c $ax+b=0$\uc774 \ub418\ub294 $x$\uac12\uc778 $-\\frac{b}{a}$\ub97c \ub300\uc785\ud558\uba74, $P(-\\frac{b}{a}) = (a \\cdot (-\\frac{b}{a}) + b)Q(-\\frac{b}{a}) + R$\uc774 \ub418\uc5b4 \uacb0\uad6d $P(-\\frac{b}{a}) = R$\uc774 \uc131\ub9bd\ud568\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uc608\uc81c\ub97c \ud1b5\ud574 \uc9c1\uc811 \uc801\uc6a9\ud574 \ubd05\uc2dc\ub2e4. \ub2e4\ud56d\uc2dd $P(x) = 2x^3 - 3x^2 + x + 5$\ub97c $x-2$\ub85c \ub098\ub204\uc5c8\uc744 \ub54c\uc758 \ub098\uba38\uc9c0\ub97c \uad6c\ud558\ub294 \ubb38\uc81c\uc785\ub2c8\ub2e4. \ub098\uba38\uc9c0\uc815\ub9ac\uc5d0 \ub530\ub974\uba74 \ub098\uba38\uc9c0\ub294 $P(2)$\uc758 \uac12\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uba3c\uc800 $x$ \uc790\ub9ac\uc5d0 $2$\ub97c \ub300\uc785\ud558\uc5ec \uc2dd\uc744 \uc138\uc6c1\ub2c8\ub2e4. $P(2) = 2(2)^3 - 3(2)^2 + 2 + 5$.","\ub2e8\uacc4\ubcc4\ub85c \uacc4\uc0b0\ud558\uba74, $2^3 = 8$\uc774\ubbc0\ub85c $2 \\times 8 = 16$\uc774\uace0, $2^2 = 4$\uc774\ubbc0\ub85c $3 \\times 4 = 12$\uac00 \ub429\ub2c8\ub2e4. \uc774\ub97c \uc2dd\uc5d0 \ub300\uc785\ud558\uba74 $P(2) = 16 - 12 + 2 + 5$\uac00 \ub429\ub2c8\ub2e4. \uc774\ub97c \ucc28\ub840\ub300\ub85c \uacc4\uc0b0\ud558\uba74 $16 - 12 = 4$\uc774\uace0, $4 + 2 + 5 = 11$\uc774 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \ub2e4\ud56d\uc2dd $P(x)$\ub97c $x-2$\ub85c \ub098\ub208 \ub098\uba38\uc9c0\ub294 $11$\uc785\ub2c8\ub2e4."],ai0),ag6,B.r)],ai2),ag6,B.r)],ai3),s3,s3,s3,s3,"concept_\ub098\uba38\uc9c0\uc815\ub9ac\uc99d\uba85",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5591 > \ub2e4\ud56d\uc2dd > \ub098\uba38\uc9c0\uc815\ub9ac > \ub098\uba38\uc9c0\uc815\ub9ac\uc99d\uba85",q1,ag6,s3)
q2=A.a(["\ub300\uc218","\uc218\uc5f4","\ud569\uc758\uae30\ud638\uc2dc\uadf8\ub9c8","\uc2dc\uadf8\ub9c8\uc758\uc131\uc9c8"],ai0)
q2=A.ay(s2,A.a([A.aA(A.a(["\ub300\uc218 > \uc218\uc5f4 > \ud569\uc758\uae30\ud638\uc2dc\uadf8\ub9c8 > \uc2dc\uadf8\ub9c8\uc758\uc131\uc9c8 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uc218\uc5f4\uc758 \ud569\uc744 \ub098\ud0c0\ub0b4\ub294 \uae30\ud638\uc778 \uc2dc\uadf8\ub9c8($\\sum$)\ub294 \ubcf5\uc7a1\ud55c \uc218\uc5f4\uc758 \ud569\uc744 \uac04\uacb0\ud558\uac8c \ud45c\ud604\ud558\uae30 \uc704\ud574 \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \uc2dc\uadf8\ub9c8\uc758 \uc131\uc9c8\uc744 \uc774\ud574\ud558\uba74 \uc218\uc5f4\uc758 \ud569\uc744 \uacc4\uc0b0\ud560 \ub54c \uc77c\uc77c\uc774 \ub098\uc5f4\ud558\uc9c0 \uc54a\uace0\ub3c4 \ud6a8\uc728\uc801\uc73c\ub85c \uac12\uc744 \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uac00\uc7a5 \uae30\ubcf8\uc801\uc778 \uc131\uc9c8\uc740 \ud569\uc758 \uae30\ud638 \uc548\uc5d0\uc11c \uc0c1\uc218\ubc30\uac00 \ub418\uc5b4 \uc788\ub294 \uacbd\uc6b0 \uc0c1\uc218\ub97c \uae30\ud638 \uc55e\uc73c\ub85c \ub044\uc9d1\uc5b4\ub0bc \uc218 \uc788\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4. \uc989, \uc0c1\uc218 $c$\uc5d0 \ub300\ud558\uc5ec $$\\sum_{k=1}^{n} c a_k = c \\sum_{k=1}^{n} a_k$$ \uac00 \uc131\ub9bd\ud569\ub2c8\ub2e4.","\ub610\ud55c, \uc2dc\uadf8\ub9c8\ub294 \ub367\uc148\uacfc \ube84\uc148\uc5d0 \ub300\ud574 \uac01\uac01 \ubd84\ubc30\uac00 \uac00\ub2a5\ud558\ub2e4\ub294 \uc911\uc694\ud55c \uc131\uc9c8\uc744 \uac00\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4. \ub450 \uc218\uc5f4 $a_k$\uc640 $b_k$\uc5d0 \ub300\ud558\uc5ec \ud569\uacfc \ucc28\uc758 \uc2dc\uadf8\ub9c8\ub294 \uac01\uac01\uc758 \uc2dc\uadf8\ub9c8\ub97c \ub354\ud558\uac70\ub098 \ube80 \uac83\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uc774\ub97c \uc2dd\uc73c\ub85c \ub098\ud0c0\ub0b4\uba74 $$\\sum_{k=1}^{n} (a_k + b_k) = \\sum_{k=1}^{n} a_k + \\sum_{k=1}^{n} b_k$$ \uc774\uace0, $$\\sum_{k=1}^{n} (a_k - b_k) = \\sum_{k=1}^{n} a_k - \\sum_{k=1}^{n} b_k$$ \uc785\ub2c8\ub2e4. \ub2e4\ub9cc, \uacf1\uc148\uc774\ub098 \ub098\ub217\uc148\uc5d0 \ub300\ud574\uc11c\ub294 \uc774\ub7ec\ud55c \ubd84\ubc30 \ubc95\uce59\uc774 \uc131\ub9bd\ud558\uc9c0 \uc54a\uc73c\ubbc0\ub85c \uc8fc\uc758\ud574\uc57c \ud569\ub2c8\ub2e4.","\ub9c8\uc9c0\ub9c9\uc73c\ub85c, \uc2dc\uadf8\ub9c8 \uae30\ud638 \uc548\uc758 \uac12\uc774 \uc0c1\uc218\uc778 \uacbd\uc6b0\uc758 \uc131\uc9c8\uc785\ub2c8\ub2e4. \ub9cc\uc57d $k$\uac12\uc5d0 \uad00\uacc4\uc5c6\uc774 \ud56d\uc0c1 \uc77c\uc815\ud55c \uc0c1\uc218 $c$\ub97c $n$\ubc88 \ub354\ud55c\ub2e4\uba74, \uadf8 \uacb0\uacfc\ub294 \uc0c1\uc218 $c$\uc5d0 \ud56d\uc758 \uac1c\uc218\uc778 $n$\uc744 \uacf1\ud55c \uac83\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uc989, $$\\sum_{k=1}^{n} c = nc$$ \ub77c\ub294 \uacf5\uc2dd\uc774 \uc131\ub9bd\ud569\ub2c8\ub2e4. \uc774 \uc138 \uac00\uc9c0 \uc131\uc9c8(\uc0c1\uc218\ubc30, \ub367\uc148\xb7\ube84\uc148\uc758 \ubd84\ubc30, \uc0c1\uc218\ud56d\uc758 \ud569)\uc744 \uc801\uc808\ud788 \uc870\ud569\ud558\uba74 \uc5b4\ub5a4 \ub2e4\ud56d\uc2dd \ud615\ud0dc\uc758 \uc218\uc5f4 \ud569\uc774\ub77c\ub3c4 \uc27d\uac8c \uacc4\uc0b0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uc608\uc81c\ub97c \ud1b5\ud574 \uc2dc\uadf8\ub9c8\uc758 \uc131\uc9c8\uc744 \uc801\uc6a9\ud574 \ubd05\uc2dc\ub2e4. \ubb38\uc81c: $\\sum_{k=1}^{10} (3k + 2)$\uc758 \uac12\uc744 \uad6c\ud558\uc2dc\uc624. \uba3c\uc800 \uc2dc\uadf8\ub9c8\uc758 \ub367\uc148 \uc131\uc9c8\uc744 \uc774\uc6a9\ud558\uc5ec \uc2dd\uc744 \ubd84\ub9ac\ud569\ub2c8\ub2e4. $$\\sum_{k=1}^{10} (3k + 2) = \\sum_{k=1}^{10} 3k + \\sum_{k=1}^{10} 2$$ \ub85c \ub098\ub20c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uccab \ubc88\uc9f8 \ud56d\uc740 \uc0c1\uc218\ubc30 \uc131\uc9c8\uc744 \uc774\uc6a9\ud574 $3 \\sum_{k=1}^{10} k$\ub85c \ubcc0\ud615\ud569\ub2c8\ub2e4.","\uc774\uc81c \uac01 \ubd80\ubd84\uc744 \uacc4\uc0b0\ud569\ub2c8\ub2e4. \uc790\uc5f0\uc218\uc758 \ud569 \uacf5\uc2dd $\\sum_{k=1}^{n} k = \\frac{n(n+1)}{2}$\uc744 \uc774\uc6a9\ud558\uba74, $3 \\sum_{k=1}^{10} k = 3 \\times \\frac{10 \\times 11}{2} = 3 \\times 55 = 165$\uac00 \ub429\ub2c8\ub2e4. \ub610\ud55c \uc0c1\uc218\ud56d\uc758 \uc131\uc9c8\uc5d0 \uc758\ud574 $\\sum_{k=1}^{10} 2 = 2 \\times 10 = 20$\uc774 \ub429\ub2c8\ub2e4. \ucd5c\uc885\uc801\uc73c\ub85c \ub450 \uac12\uc744 \ub354\ud558\uba74 $165 + 20 = 185$\ub77c\ub294 \uacb0\uacfc\ub97c \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),ag7,B.r)],ai2),ag7,B.r)],ai3),s3,s3,s3,s3,"concept_\uc2dc\uadf8\ub9c8\uc758\uc131\uc9c8",0,"",1,s3,B.n,"\ub300\uc218 > \uc218\uc5f4 > \ud569\uc758\uae30\ud638\uc2dc\uadf8\ub9c8 > \uc2dc\uadf8\ub9c8\uc758\uc131\uc9c8",q2,ag7,s3)
q3=A.a(["\uacf5\ud1b5\uc218\ud5592","\uc88c\ud45c\ud3c9\uba74","\uc120\ubd84\uc758\ub0b4\ubd84\uc810","\uc911\uc810"],ai0)
q3=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \uc120\ubd84\uc758\ub0b4\ubd84\uc810 > \uc911\uc810 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uc88c\ud45c\ud3c9\uba74 \uc704\uc758 \ub450 \uc810 $A(x_1, y_1)$\uacfc $B(x_2, y_2)$\ub97c \uc787\ub294 \uc120\ubd84 $AB$\uac00 \uc788\uc744 \ub54c, \uc774 \uc120\ubd84\uc744 \ub611\uac19\uc740 \uae38\uc774\ub85c \uc774\ub4f1\ubd84\ud558\ub294 \uc810\uc744 '\uc911\uc810'\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4. \uc911\uc810\uc740 \uc120\ubd84\uc758 \uc591 \ub05d\uc810\uc73c\ub85c\ubd80\ud130 \uac19\uc740 \uac70\ub9ac\uc5d0 \uc704\uce58\ud558\uba70, \uae30\ud558\ud559\uc801\uc73c\ub85c\ub294 \uc120\ubd84\uc758 \ubb34\uac8c\uc911\uc2ec\uacfc \uac19\uc740 \uc5ed\ud560\uc744 \ud569\ub2c8\ub2e4. \uc911\uc810\uc758 \uc88c\ud45c\ub97c \uad6c\ud558\ub294 \uac83\uc740 \uc120\ubd84\uc744 $1:1$\uc758 \ube44\uc728\ub85c \ub0b4\ubd84\ud558\ub294 \uc810\uc744 \ucc3e\ub294 \uac83\uacfc \ub3d9\uc77c\ud55c \uc6d0\ub9ac\uc785\ub2c8\ub2e4.","\uc911\uc810\uc758 \uc88c\ud45c\ub97c \uad6c\ud558\ub294 \uacf5\uc2dd\uc740 \ub9e4\uc6b0 \uc9c1\uad00\uc801\uc785\ub2c8\ub2e4. \ub450 \uc810\uc758 $x$\uc88c\ud45c\ub07c\ub9ac \ub354\ud574\uc11c $2$\ub85c \ub098\ub204\uace0, $y$\uc88c\ud45c\ub07c\ub9ac \ub354\ud574\uc11c $2$\ub85c \ub098\ub204\uba74 \ub429\ub2c8\ub2e4. \uc989, \uc120\ubd84 $AB$\uc758 \uc911\uc810 $M(x, y)$\uc758 \uc88c\ud45c\ub294 \ub2e4\uc74c\uacfc \uac19\uc774 \uc815\uc758\ub429\ub2c8\ub2e4. $$M = \\left( \\frac{x_1 + x_2}{2}, \\frac{y_1 + y_2}{2} \\right)$$ \uc774 \uacf5\uc2dd\uc740 \uc218\uc9c1\uc120 \uc704\uc5d0\uc11c \ub450 \uc810\uc758 \ud3c9\uade0\uc744 \uad6c\ud558\ub294 \uac83\uacfc \uac19\uc740 \ub17c\ub9ac\uc774\uba70, \uc88c\ud45c\ud3c9\uba74\uc5d0\uc11c\ub294 $x$\ucd95\uacfc $y$\ucd95\uc5d0 \ub300\ud574 \uac01\uac01 \ud3c9\uade0\uc744 \uad6c\ud558\ub294 \uac83\uc73c\ub85c \uc774\ud574\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc608\ub97c \ub4e4\uc5b4, \uc88c\ud45c\ud3c9\uba74 \uc704\uc758 \ub450 \uc810 $A(2, 4)$\uc640 $B(6, 8)$\uc744 \uc787\ub294 \uc120\ubd84 $AB$\uc758 \uc911\uc810 $M$\uc744 \uad6c\ud558\ub294 \uacfc\uc815\uc744 \uc0b4\ud3b4\ubd05\uc2dc\ub2e4. \uc911\uc810\uc758 $x$\uc88c\ud45c\ub294 \ub450 \uc810\uc758 $x$\uc88c\ud45c\uc778 $2$\uc640 $6$\uc758 \ud3c9\uade0\uc774\ubbc0\ub85c $\\frac{2+6}{2} = 4$\uac00 \ub429\ub2c8\ub2e4. \ub9c8\ucc2c\uac00\uc9c0\ub85c $y$\uc88c\ud45c\ub294 \ub450 \uc810\uc758 $y$\uc88c\ud45c\uc778 $4$\uc640 $8$\uc758 \ud3c9\uade0\uc774\ubbc0\ub85c $\\frac{4+8}{2} = 6$\uc774 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uad6c\ud558\ub294 \uc911\uc810 $M$\uc758 \uc88c\ud45c\ub294 $(4, 6)$\uc785\ub2c8\ub2e4.","\uc870\uae08 \ub354 \ubcf5\uc7a1\ud55c \uc608\uc81c\ub85c, \uc810 $A(-3, 5)$\uc640 \uc810 $B(5, -1)$\uc744 \uc787\ub294 \uc120\ubd84 $AB$\uc758 \uc911\uc810 $M$\uc744 \uad6c\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uacf5\uc2dd\uc5d0 \ub530\ub77c $x$\uc88c\ud45c\uc640 $y$\uc88c\ud45c\ub97c \uac01\uac01 \uacc4\uc0b0\ud558\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uba3c\uc800 $x$\uc88c\ud45c\ub294 $x = \\frac{-3 + 5}{2} = \\frac{2}{2} = 1$\uc785\ub2c8\ub2e4. \ub2e4\uc74c\uc73c\ub85c $y$\uc88c\ud45c\ub294 $y = \\frac{5 + (-1)}{2} = \\frac{4}{2} = 2$\uc785\ub2c8\ub2e4. \uacb0\uacfc\uc801\uc73c\ub85c \uc911\uc810 $M$\uc758 \uc88c\ud45c\ub294 $(1, 2)$\uac00 \ub429\ub2c8\ub2e4.","\ub9c8\uc9c0\ub9c9\uc73c\ub85c, \uc911\uc810\uc758 \uc131\uc9c8\uc744 \ud65c\uc6a9\ud558\uc5ec \ubbf8\uc9c0\uc218\ub97c \uad6c\ud558\ub294 \ubb38\uc81c\ub97c \ud480\uc5b4\ubd05\uc2dc\ub2e4. \uc120\ubd84 $AB$\uc758 \uc911\uc810\uc774 $M(3, 2)$\uc774\uace0, \uc810 $A$\uc758 \uc88c\ud45c\uac00 $(1, 5)$\uc77c \ub54c, \uc810 $B(x, y)$\uc758 \uc88c\ud45c\ub97c \uad6c\ud558\ub294 \ubb38\uc81c\uc785\ub2c8\ub2e4. \uc911\uc810 \uacf5\uc2dd\uc5d0 \uc758\ud574 $\\frac{1+x}{2} = 3$\uc774\uace0 $\\frac{5+y}{2} = 2$\uac00 \uc131\ub9bd\ud569\ub2c8\ub2e4. \uccab \ubc88\uc9f8 \uc2dd\uc5d0\uc11c $1+x = 6$\uc774 \ub418\uc5b4 $x = 5$\ub97c \uc5bb\uace0, \ub450 \ubc88\uc9f8 \uc2dd\uc5d0\uc11c $5+y = 4$\uac00 \ub418\uc5b4 $y = -1$\uc744 \uc5bb\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc810 $B$\uc758 \uc88c\ud45c\ub294 $(5, -1)$\uc785\ub2c8\ub2e4."],ai0),"\uc911\uc810",B.r)],ai2),"\uc911\uc810",B.r)],ai3),s3,s3,s3,s3,"concept_\uc911\uc810",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \uc120\ubd84\uc758\ub0b4\ubd84\uc810 > \uc911\uc810",q3,"\uc911\uc810",s3)
q4=A.a(["\ub300\uc218","\uc9c0\uc218","\uc9c0\uc218\ubc95\uce59","\uc9c0\uc218\ubc95\uce59\uc758\uc131\uc9c8"],ai0)
q4=A.ay(s2,A.a([A.aA(A.a(["\ub300\uc218 > \uc9c0\uc218 > \uc9c0\uc218\ubc95\uce59 > \uc9c0\uc218\ubc95\uce59\uc758\uc131\uc9c8 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uc9c0\uc218\ubc95\uce59\uc774\ub780 \uac70\ub4ed\uc81c\uacf1\uc758 \uacc4\uc0b0\uc744 \uac04\ud3b8\ud558\uac8c \ud558\uae30 \uc704\ud574 \ub9cc\ub4e4\uc5b4\uc9c4 \uc218\ud559\uc801 \uc57d\uc18d\uc785\ub2c8\ub2e4. \uc5b4\ub5a4 \uc218 $a$\ub97c $n$\ubc88 \uacf1\ud55c \uac83\uc744 $a^n$\uc774\ub77c \uc4f0\uace0, \uc774\ub54c $a$\ub97c \ubc11, $n$\uc744 \uc9c0\uc218\ub77c\uace0 \ud569\ub2c8\ub2e4. \uc9c0\uc218\ubc95\uce59\uc758 \uac00\uc7a5 \uae30\ucd08\uac00 \ub418\ub294 \uc131\uc9c8\uc740 \ubc11\uc774 \uac19\uc740 \ub450 \uac70\ub4ed\uc81c\uacf1\uc744 \uacf1\ud560 \ub54c \uc9c0\uc218\ub07c\ub9ac \ub354\ud558\ub294 \uac83\uc785\ub2c8\ub2e4. \uc989, $a^m \\times a^n = a^{m+n}$\uc774 \uc131\ub9bd\ud569\ub2c8\ub2e4. \uc774\ub294 $a$\ub97c $m$\ubc88 \uacf1\ud55c \uac83\uc5d0 $a$\ub97c $n$\ubc88 \ub354 \uacf1\ud558\uba74 \ucd1d $a$\ub97c $m+n$\ubc88 \uacf1\ud558\uac8c \ub41c\ub2e4\ub294 \uc6d0\ub9ac\uc5d0\uc11c \ube44\ub86f\ub429\ub2c8\ub2e4.","\uc9c0\uc218\ubc95\uce59\uc5d0\ub294 \uacf1\uc148 \uc678\uc5d0\ub3c4 \ub098\ub217\uc148\uacfc \uac70\ub4ed\uc81c\uacf1\uc758 \uac70\ub4ed\uc81c\uacf1\uc5d0 \uad00\ud55c \uc131\uc9c8\uc774 \uc788\uc2b5\ub2c8\ub2e4. \ub098\ub217\uc148\uc758 \uacbd\uc6b0 $a^m \\div a^n = a^{m-n}$ ($m > n$\uc77c \ub54c)\uc774 \uc131\ub9bd\ud558\uba70, \uac70\ub4ed\uc81c\uacf1\uc758 \uac70\ub4ed\uc81c\uacf1\uc740 $(a^m)^n = a^{m \\times n}$\uc73c\ub85c \uacc4\uc0b0\ud569\ub2c8\ub2e4. \ub610\ud55c, \uad04\ud638 \uc548\uc758 \uacf1\uc148\uc774\ub098 \ub098\ub217\uc148\uc5d0 \uc9c0\uc218\uac00 \ubd99\uc5b4 \uc788\uc744 \ub54c\ub294 $(ab)^n = a^n b^n$ \ub610\ub294 $(\\frac{a}{b})^n = \\frac{a^n}{b^n}$\uacfc \uac19\uc774 \uc9c0\uc218\ub97c \uac01\uac01 \ubd84\ubc30\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc131\uc9c8\ub4e4\uc744 \uc775\ud788\uba74 \ubcf5\uc7a1\ud55c \uc2dd\uc744 \ub9e4\uc6b0 \uac04\ub2e8\ud558\uac8c \uc815\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud1b5\ud574 \uc9c0\uc218\ubc95\uce59\uc744 \uc801\uc6a9\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uccab \ubc88\uc9f8 \ubb38\uc81c\ub294 $2^3 \\times 2^4$\uc744 \uacc4\uc0b0\ud558\ub294 \uac83\uc785\ub2c8\ub2e4. \uc774 \uc2dd\uc740 \ubc11\uc774 2\ub85c \uac19\uc73c\ubbc0\ub85c \uc9c0\uc218\ubc95\uce59 $a^m \\times a^n = a^{m+n}$\uc744 \uc801\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c $2^3 \\times 2^4 = 2^{3+4} = 2^7$\uc774 \ub429\ub2c8\ub2e4. $2^7$\uc740 2\ub97c 7\ubc88 \uacf1\ud55c \uac12\uc778 128\uc774\ubbc0\ub85c, \ucd5c\uc885 \uacb0\uacfc\ub294 128\uc785\ub2c8\ub2e4.","\ub450 \ubc88\uc9f8 \uc608\uc81c\ub85c \uc2dd $(x^2 y^3)^4$\uc744 \uac04\ub2e8\ud788 \uc815\ub9ac\ud574 \ubd05\uc2dc\ub2e4. \uc774 \uc2dd\uc740 \uad04\ud638 \uc548\uc758 \uac01 \ud56d\uc5d0 \uc9c0\uc218 4\ub97c \ubd84\ubc30\ud558\ub294 \ubc95\uce59\uc778 $(a^m b^n)^p = a^{m \\times p} b^{n \\times p}$\ub97c \uc774\uc6a9\ud569\ub2c8\ub2e4. \uba3c\uc800 $x^2$\uc5d0 4\ub97c \uacf1\ud558\uc5ec $x^{2 \\times 4} = x^8$\uc774 \ub418\uace0, $y^3$\uc5d0 4\ub97c \uacf1\ud558\uc5ec $y^{3 \\times 4} = y^{12}$\uac00 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc2dd\uc744 \uc815\ub9ac\ud558\uba74 $x^8 y^{12}$\ub77c\ub294 \uacb0\uacfc\ub97c \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ub9c8\uc9c0\ub9c9\uc73c\ub85c \ub098\ub217\uc148\uc774 \ud3ec\ud568\ub41c \uc2dd $\\frac{3^6}{3^2}$\uc744 \uacc4\uc0b0\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uc9c0\uc218\ubc95\uce59 $a^m \\div a^n = a^{m-n}$\uc744 \uc801\uc6a9\ud558\uba74 \ubc11\uc774 3\uc77c \ub54c \uc9c0\uc218\ub07c\ub9ac \ube7c\uc8fc\uba74 \ub429\ub2c8\ub2e4. \uc989, $3^{6-2} = 3^4$\uc774 \ub429\ub2c8\ub2e4. $3^4$\uc740 $3 \\times 3 \\times 3 \\times 3$\uc744 \uc758\ubbf8\ud558\ubbc0\ub85c, $9 \\times 9 = 81$\uc774 \ucd5c\uc885 \uc815\ub2f5\uc785\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uc9c0\uc218\ubc95\uce59\uc744 \ud65c\uc6a9\ud558\uba74 \ud070 \uc218\ub97c \uc9c1\uc811 \uacf1\ud558\uc9c0 \uc54a\uace0\ub3c4 \ube60\ub974\uace0 \uc815\ud655\ud558\uac8c \uacc4\uc0b0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),ag8,B.r)],ai2),ag8,B.r)],ai3),s3,s3,s3,s3,"concept_\uc9c0\uc218\ubc95\uce59\uc758\uc131\uc9c8",0,"",1,s3,B.n,"\ub300\uc218 > \uc9c0\uc218 > \uc9c0\uc218\ubc95\uce59 > \uc9c0\uc218\ubc95\uce59\uc758\uc131\uc9c8",q4,ag8,s3)
q5=A.a(["\ubbf8\uc801\ubd84\u2160","\ud568\uc218\uc758\uc99d\uac00\uc640\uac10\uc18c","\ub3c4\ud568\uc218\uc758\ubd80\ud638"],ai0)
q5=A.ay(s2,A.a([A.aA(A.a(["\ubbf8\uc801\ubd84\u2160 > \ud568\uc218\uc758\uc99d\uac00\uc640\uac10\uc18c > \ub3c4\ud568\uc218\uc758\ubd80\ud638 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["[   \"\ud568\uc218\uc758 \uc99d\uac00\uc640 \uac10\uc18c\ub97c \ud310\ub2e8\ud560 \ub54c \uac00\uc7a5 \uac15\ub825\ud55c \ub3c4\uad6c\ub294 \ubc14\ub85c '\ub3c4\ud568\uc218\uc758 \ubd80\ud638'\uc785\ub2c8\ub2e4. \uc5b4\ub5a4 \uad6c\uac04\uc5d0\uc11c \ubbf8\ubd84\uac00\ub2a5\ud55c \ud568\uc218 $f(x)$\uac00 \uc788\uc744 \ub54c, \uadf8 \uad6c\uac04\uc758 \ubaa8\ub4e0 $x$\uc5d0 \ub300\ud558\uc5ec $f'(x) > 0$\uc774\uba74 \ud568\uc218 $f(x)$\ub294 \uadf8 \uad6c\uac04\uc5d0\uc11c \uc99d\uac00\ud569\ub2c8\ub2e4. \ubc18\ub300\ub85c $f'(x) < 0$\uc774\uba74 \ud568\uc218 $f(x)$\ub294 \uadf8 \uad6c\uac04\uc5d0\uc11c \uac10\uc18c\ud558\uac8c \ub429\ub2c8\ub2e4. \uc774\ub294 \ub3c4\ud568\uc218 $f'(x)$\uac00 \ud574\ub2f9 \uc9c0\uc810\uc5d0\uc11c\uc758 \uc811\uc120\uc758 \uae30\uc6b8\uae30\ub97c \uc758\ubbf8\ud558\uae30 \ub54c\ubb38\uc778\ub370, \uae30\uc6b8\uae30\uac00 \uc591\uc218\ub77c\ub294 \uac83\uc740 \uc624\ub978\ucabd \uc704\ub85c \ud5a5\ud558\ub294 \uadf8\ub798\ud504\ub97c, \uc74c\uc218\ub77c\ub294 \uac83\uc740 \uc624\ub978\ucabd \uc544\ub798\ub85c \ud5a5\ud558\ub294 \uadf8\ub798\ud504\ub97c \uadf8\ub9b0\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.\",   \"\uc870\uae08 \ub354 \uc5c4\ubc00\ud558\uac8c \ub9d0\ud558\uba74, \uad6c\uac04 \ub0b4\uc758 \ubaa8\ub4e0 $x$\uc5d0 \ub300\ud558\uc5ec $f'(x) \\geq 0$\uc774\uace0, \uc5b4\ub5a4 \uc5f4\ub9b0 \uad6c\uac04\uc5d0\uc11c\ub3c4 $f'(x)$\uac00 \ud56d\uc0c1 $0$\uc774 \ub418\uc9c0 \uc54a\ub294\ub2e4\uba74 \ud568\uc218 $f(x)$\ub294 \uadf8 \uad6c\uac04\uc5d0\uc11c \uc99d\uac00\ud55c\ub2e4\uace0 \ub9d0\ud569\ub2c8\ub2e4. \ub9c8\ucc2c\uac00\uc9c0\ub85c $f'(x) \\leq 0$\uc778 \uacbd\uc6b0\uc5d0\ub3c4 \ub3d9\uc77c\ud55c \ub17c\ub9ac\uac00 \uc801\uc6a9\ub429\ub2c8\ub2e4. \uc989, \ub3c4\ud568\uc218\uc758 \ubd80\ud638\ub294 \ud568\uc218\uc758 \uadf8\ub798\ud504\uac00 \uc704\ub85c \uc62c\ub77c\uac00\ub294\uc9c0, \uc544\ub2c8\uba74 \uc544\ub798\ub85c \ub0b4\ub824\uac00\ub294\uc9c0\ub97c \uacb0\uc815\uc9d3\ub294 \ud575\uc2ec\uc801\uc778 \uc9c0\ud45c\uac00 \ub429\ub2c8\ub2e4.\",   \"\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud1b5\ud574 \ub3c4\ud568\uc218\uc758 \ubd80\ud638\ub97c \ud65c\uc6a9\ud558\ub294 \ubc29\ubc95\uc744 \uc54c\uc544\ubd05\uc2dc\ub2e4. \ud568\uc218 $f(x) = x^3 - 3x^2 + 2$\uac00 \uc99d\uac00\ud558\ub294 \uad6c\uac04\uacfc \uac10\uc18c\ud558\ub294 \uad6c\uac04\uc744 \uad6c\ud574\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \ud568\uc218\ub97c \ubbf8\ubd84\ud558\uc5ec \ub3c4\ud568\uc218\ub97c \uad6c\ud558\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$f'(x) = 3x^2 - 6x$$\",   \"\ub3c4\ud568\uc218\uc758 \ubd80\ud638\ub97c \uc870\uc0ac\ud558\uae30 \uc704\ud574 $f'(x) = 0$\uc774 \ub418\ub294 \uc9c0\uc810\uc744 \ucc3e\uc2b5\ub2c8\ub2e4. $$3x(x - 2) = 0$$ \uc774 \uc2dd\uc744 \ud480\uba74 $x = 0$ \ub610\ub294 $x = 2$\uac00 \ub429\ub2c8\ub2e4. \uc774\uc81c \uc774 \ub450 \uc9c0\uc810\uc744 \uae30\uc900\uc73c\ub85c \uad6c\uac04\uc744 \ub098\ub204\uc5b4 \ub3c4\ud568\uc218\uc758 \ubd80\ud638\ub97c \ud655\uc778\ud569\ub2c8\ub2e4. $x < 0$\uc778 \uad6c\uac04\uc5d0\uc11c\ub294 $f'(x) > 0$\uc774\ubbc0\ub85c \ud568\uc218\ub294 \uc99d\uac00\ud558\uace0, $0 < x < 2$\uc778 \uad6c\uac04\uc5d0\uc11c\ub294 $f'(x) < 0$\uc774\ubbc0\ub85c \ud568\uc218\ub294 \uac10\uc18c\ud569\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9\uc73c\ub85c $x > 2$\uc778 \uad6c\uac04\uc5d0\uc11c\ub294 \ub2e4\uc2dc $f'(x) > 0$\uc774 \ub418\uc5b4 \ud568\uc218\ub294 \uc99d\uac00\ud558\uac8c \ub429\ub2c8\ub2e4.\",   \"\uacb0\uacfc\uc801\uc73c\ub85c \ud568\uc218 $f(x) = x^3 - 3x^2 + 2$\ub294 \uad6c\uac04 $(-\\\\infty, 0]$\uacfc $[2, \\\\infty)$\uc5d0\uc11c \uc99d\uac00\ud558\uba70, \uad6c\uac04 $[0, 2]$\uc5d0\uc11c \uac10\uc18c\ud55c\ub2e4\ub294 \uacb0\ub860\uc744 \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ucc98\ub7fc \ub3c4\ud568\uc218\uc758 \ubd80\ud638\ub97c \uc870\uc0ac\ud558\ub294 \uacfc\uc815\uc740 \ud568\uc218\uc758 \uac1c\ud615\uc744 \ud30c\uc545\ud558\ub294 \uac00\uc7a5 \uae30\ucd08\uc801\uc774\uba74\uc11c\ub3c4 \uc911\uc694\ud55c \ub2e8\uacc4\uc785\ub2c8\ub2e4. \uc5ec\ub7ec\ubd84\ub3c4 \ub2e4\uc591\ud55c \ub2e4\ud56d\ud568\uc218\ub97c \ubbf8\ubd84\ud574\ubcf4\uace0, \ub3c4\ud568\uc218\uac00 0\uc774 \ub418\ub294 \uc9c0\uc810\uc744 \ucc3e\uc544 \uadf8\ub798\ud504\uc758 \ubaa8\uc591\uc744 \uc9c1\uc811 \uadf8\ub824\ubcf4\ub294 \uc5f0\uc2b5\uc744 \ud574\ubcf4\uae38 \ubc14\ub78d\ub2c8\ub2e4.\" ]"],ai0),ag9,B.r)],ai2),ag9,B.r)],ai3),s3,s3,s3,s3,"concept_\ub3c4\ud568\uc218\uc758\ubd80\ud638",0,"",1,s3,B.n,"\ubbf8\uc801\ubd84\u2160 > \ud568\uc218\uc758\uc99d\uac00\uc640\uac10\uc18c > \ub3c4\ud568\uc218\uc758\ubd80\ud638",q5,ag9,s3)
q6=A.a(["\uacf5\ud1b5\uc218\ud5591","\uc774\ucc28\ud568\uc218","\uc774\ucc28\ud568\uc218\uc640\uc774\ucc28\ubd80\ub4f1\uc2dd"],ai0)
q6=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5591 > \uc774\ucc28\ud568\uc218 > \uc774\ucc28\ud568\uc218\uc640\uc774\ucc28\ubd80\ub4f1\uc2dd \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uc774\ucc28\ud568\uc218 $y = ax^2 + bx + c$ ($a \\neq 0$)\uc758 \uadf8\ub798\ud504\ub294 \ud3ec\ubb3c\uc120 \ubaa8\uc591\uc744 \ub760\uba70, \uc774 \uadf8\ub798\ud504\uc640 $x$\ucd95\uc758 \uc704\uce58 \uad00\uacc4\ub294 \uc774\ucc28\ubc29\uc815\uc2dd $ax^2 + bx + c = 0$\uc758 \ud310\ubcc4\uc2dd $D = b^2 - 4ac$\uc758 \uac12\uc5d0 \ub530\ub77c \uacb0\uc815\ub429\ub2c8\ub2e4. \uc774\ucc28\ubd80\ub4f1\uc2dd $ax^2 + bx + c > 0$ \ub610\ub294 $ax^2 + bx + c < 0$\uc744 \ud47c\ub2e4\ub294 \uac83\uc740, \uc774\ucc28\ud568\uc218\uc758 \uadf8\ub798\ud504\uac00 $x$\ucd95\ubcf4\ub2e4 \uc704\ucabd\uc5d0 \uc788\uac70\ub098 \uc544\ub798\ucabd\uc5d0 \uc788\ub294 $x$\uc758 \uac12\uc758 \ubc94\uc704\ub97c \ucc3e\ub294 \uac83\uacfc \uac19\uc2b5\ub2c8\ub2e4.","\uc774\ucc28\ubd80\ub4f1\uc2dd\uc744 \ud480\uae30 \uc704\ud574\uc11c\ub294 \uba3c\uc800 \uc774\ucc28\ubc29\uc815\uc2dd $ax^2 + bx + c = 0$\uc758 \ub450 \uc2e4\uadfc\uc744 $\\alpha, \\beta$ ($\\alpha < \\beta$)\ub77c \ud560 \ub54c, $a > 0$\uc778 \uacbd\uc6b0 \ub2e4\uc74c\uacfc \uac19\uc740 \uc131\uc9c8\uc744 \uc774\uc6a9\ud569\ub2c8\ub2e4. $ax^2 + bx + c > 0$\uc758 \ud574\ub294 $x < \\alpha$ \ub610\ub294 $x > \\beta$\uc774\uace0, $ax^2 + bx + c < 0$\uc758 \ud574\ub294 $\\alpha < x < \\beta$\uc785\ub2c8\ub2e4. \ub9cc\uc57d \ud310\ubcc4\uc2dd $D=0$\uc774\ub77c\uba74 \uadf8\ub798\ud504\uac00 $x$\ucd95\uc5d0 \uc811\ud558\ubbc0\ub85c \ud574\ub294 \ud2b9\uc218\ud55c \ud615\ud0dc\uac00 \ub418\uba70, $D < 0$\uc774\uba74 \uadf8\ub798\ud504\uac00 \ud56d\uc0c1 $x$\ucd95 \uc704\uc5d0 \ub5a0 \uc788\uc5b4 \ud574\uac00 \ubaa8\ub4e0 \uc2e4\uc218\uac00 \ub418\uac70\ub098 \ud574\uac00 \uc5c6\uc744 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud1b5\ud574 \ud655\uc778\ud574 \ubd05\uc2dc\ub2e4. \uc774\ucc28\ubd80\ub4f1\uc2dd $x^2 - 5x + 6 < 0$\uc744 \ud480\uc5b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uc774 \uc2dd\uc5d0 \ub300\uc751\ud558\ub294 \uc774\ucc28\ubc29\uc815\uc2dd $x^2 - 5x + 6 = 0$\uc744 \uc778\uc218\ubd84\ud574\ud558\uba74 $(x - 2)(x - 3) = 0$\uc774 \ub418\uc5b4 \ub450 \uadfc\uc740 $x = 2$\uc640 $x = 3$\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\ucc28\ud568\uc218 $y = x^2 - 5x + 6$\uc758 \uadf8\ub798\ud504\ub294 \uc544\ub798\ub85c \ubcfc\ub85d\ud55c \ud3ec\ubb3c\uc120\uc774\uba70 $x$\ucd95\uacfc \ub450 \uc810 $(2, 0)$\uacfc $(3, 0)$\uc5d0\uc11c \ub9cc\ub0a9\ub2c8\ub2e4. \ubd80\ub4f1\uc2dd\uc5d0\uc11c $0$\ubcf4\ub2e4 \uc791\uc740 \ubc94\uc704\ub97c \uad6c\ud558\ub77c\uace0 \ud588\uc73c\ubbc0\ub85c, \uadf8\ub798\ud504\uac00 $x$\ucd95\ubcf4\ub2e4 \uc544\ub798\ucabd\uc5d0 \uc704\uce58\ud558\ub294 \uad6c\uac04\uc744 \ucc3e\uc73c\uba74 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uad6c\ud558\ub294 \ud574\ub294 $2 < x < 3$\uc774 \ub429\ub2c8\ub2e4.","\ub610 \ub2e4\ub978 \uc608\ub85c $x^2 - 2x - 3 \\geq 0$\uc744 \ud480\uc5b4\ubd05\uc2dc\ub2e4. \uba3c\uc800 \ubc29\uc815\uc2dd $x^2 - 2x - 3 = 0$\uc744 \uc778\uc218\ubd84\ud574\ud558\uba74 $(x + 1)(x - 3) = 0$\uc774 \ub418\uc5b4 \uadfc\uc740 $x = -1$\uacfc $x = 3$\uc785\ub2c8\ub2e4. \uadf8\ub798\ud504\ub294 \uc544\ub798\ub85c \ubcfc\ub85d\ud558\uace0 $x$\ucd95\uacfc \ub450 \uc810\uc5d0\uc11c \ub9cc\ub0a9\ub2c8\ub2e4.","\uc774 \ubd80\ub4f1\uc2dd\uc740 $0$\ubcf4\ub2e4 \ud06c\uac70\ub098 \uac19\uc740 \ubc94\uc704\ub97c \ucc3e\ub294 \uac83\uc774\ubbc0\ub85c, \uadf8\ub798\ud504\uac00 $x$\ucd95 \uc704\ucabd\uc5d0 \uc788\uac70\ub098 $x$\ucd95\uacfc \ub9cc\ub098\ub294 \uc9c0\uc810\uc744 \ud3ec\ud568\ud574\uc57c \ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c \uadf8\ub798\ud504\uc758 \uc591 \ub05d\ubd80\ubd84\uc5d0 \ud574\ub2f9\ud558\ub294 \ubc94\uc704\uc778 $x \\leq -1$ \ub610\ub294 $x \\geq 3$\uc774 \ucd5c\uc885\uc801\uc778 \ud574\uac00 \ub429\ub2c8\ub2e4."],ai0),ah0,B.r)],ai2),ah0,B.r)],ai3),s3,s3,s3,s3,"concept_\uc774\ucc28\ud568\uc218\uc640\uc774\ucc28\ubd80\ub4f1\uc2dd",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5591 > \uc774\ucc28\ud568\uc218 > \uc774\ucc28\ud568\uc218\uc640\uc774\ucc28\ubd80\ub4f1\uc2dd",q6,ah0,s3)
q7=A.a(["\uacf5\ud1b5\uc218\ud5592","\uba85\uc81c","\uba85\uc81c\uc758\uc5ed\uacfc\ub300\uc6b0","\uc774"],ai0)
q7=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uba85\uc81c > \uba85\uc81c\uc758\uc5ed\uacfc\ub300\uc6b0 > \uc774 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uba85\uc81c\uc5d0\uc11c '\uc774(Converse)'\ub780 \uc8fc\uc5b4\uc9c4 \uc870\uac74\uba85\uc81c '$p \\rightarrow q$'\uc758 \uac00\uc815\uacfc \uacb0\ub860\uc744 \uc11c\ub85c \ubc14\uafb8\uc5b4 \ub9cc\ub4e0 \uc0c8\ub85c\uc6b4 \uba85\uc81c\ub97c \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc6d0\ub798 \uba85\uc81c '$p \\rightarrow q$'\uc5d0\uc11c '$p$'\ub294 \uac00\uc815, '$q$'\ub294 \uacb0\ub860\uc774\ub77c\uace0 \ubd80\ub974\ub294\ub370, \uc774\ub97c \ub4a4\uc9d1\uc5b4 '$q \\rightarrow p$'\uc758 \ud615\ud0dc\ub85c \ub9cc\ub4dc\ub294 \uac83\uc774 \ubc14\ub85c '\uc774'\uc785\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 '\ube44\uac00 \uc624\uba74 \ub545\uc774 \uc816\ub294\ub2e4'\ub77c\ub294 \uba85\uc81c\uac00 \uc788\ub2e4\uba74, \uc774 \uba85\uc81c\uc758 \uc774\ub294 '\ub545\uc774 \uc816\uc73c\uba74 \ube44\uac00 \uc628\ub2e4'\uac00 \ub429\ub2c8\ub2e4.","\uba85\uc81c\uc758 '\uc774'\ub97c \ub2e4\ub8f0 \ub54c \uc8fc\uc758\ud560 \uc810\uc740 \uc6d0\ub798 \uba85\uc81c\uc758 \ucc38\uacfc \uac70\uc9d3\uc774 \uadf8 '\uc774'\uc758 \ucc38\uacfc \uac70\uc9d3\uacfc \ud56d\uc0c1 \uc77c\uce58\ud558\uc9c0\ub294 \uc54a\ub294\ub2e4\ub294 \uac83\uc785\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 'x\uac00 4\uc758 \ubc30\uc218\uc774\uba74 x\ub294 \uc9dd\uc218\uc774\ub2e4'\ub77c\ub294 \uba85\uc81c\ub294 \ucc38\uc774\uc9c0\ub9cc, \uadf8 '\uc774'\uc778 'x\uac00 \uc9dd\uc218\uc774\uba74 x\ub294 4\uc758 \ubc30\uc218\uc774\ub2e4'\ub294 2\ub098 6\uacfc \uac19\uc740 \ubc18\ub840\uac00 \uc874\uc7ac\ud558\ubbc0\ub85c \uac70\uc9d3\uc774 \ub429\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uba85\uc81c\uc640 \uadf8 \uc774\ub294 \ub17c\ub9ac\uc801\uc73c\ub85c \uc11c\ub85c \ub2e4\ub978 \uc9c4\ub9bf\uac12\uc744 \uac00\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc218\ud559\uc801\uc73c\ub85c \uba85\uc81c '$p \\rightarrow q$'\uc758 \uc774\ub97c \uae30\ud638\ub85c \ub098\ud0c0\ub0b4\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uc6d0\ub798 \uba85\uc81c\uac00 '$p \\rightarrow q$'\uc77c \ub54c, \uadf8 \uc774\ub294 $$q \\rightarrow p$$\uac00 \ub429\ub2c8\ub2e4. \ub9cc\uc57d \uc8fc\uc5b4\uc9c4 \uba85\uc81c\uc5d0 \ubd80\uc815($\\sim$)\uc774 \ud3ec\ud568\ub418\uc5b4 \uc788\ub2e4\uba74, \uac00\uc815\uacfc \uacb0\ub860\uc758 \uc704\uce58\ub9cc \ubc14\uafb8\ub294 \uac83\uc774 '\uc774'\uc774\ubbc0\ub85c, '$\\sim p \\rightarrow \\sim q$'\uc758 \uc774\ub294 '$\\sim q \\rightarrow \\sim p$'\uac00 \ub428\uc744 \uae30\uc5b5\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc608\uc81c \ubb38\uc81c: \ub2e4\uc74c \uba85\uc81c\uc758 '\uc774'\ub97c \uad6c\ud558\uace0, \uc6d0\ub798 \uba85\uc81c\uc640 \uadf8 \uc774\uc758 \ucc38, \uac70\uc9d3\uc744 \ud310\ubcc4\ud558\uc2dc\uc624. [\uba85\uc81c: $x^2 = 9$\uc774\uba74 $x = 3$\uc774\ub2e4.]","\ud480\uc774 \ub2e8\uacc4 1: \uba3c\uc800 \uc8fc\uc5b4\uc9c4 \uba85\uc81c\uc758 \uac00\uc815 '$p$'\ub294 '$x^2 = 9$'\uc774\uace0, \uacb0\ub860 '$q$'\ub294 '$x = 3$'\uc785\ub2c8\ub2e4. \uc774\ub97c \uc11c\ub85c \ubc14\uafb8\uc5b4 '\uc774'\ub97c \ub9cc\ub4e4\uba74 '$x = 3$\uc774\uba74 $x^2 = 9$\uc774\ub2e4.'\uac00 \ub429\ub2c8\ub2e4. \uc6d0\ub798 \uba85\uc81c\uc5d0\uc11c $x^2 = 9$\ub97c \ub9cc\uc871\ud558\ub294 $x$\ub294 $3$\uacfc $-3$\uc774 \uc788\ub294\ub370, \uacb0\ub860\uc778 $x=3$\ub9cc\uc73c\ub85c\ub294 \uc774\ub97c \ubaa8\ub450 \uc124\uba85\ud560 \uc218 \uc5c6\uc73c\ubbc0\ub85c \uc6d0\ub798 \uba85\uc81c\ub294 \uac70\uc9d3\uc785\ub2c8\ub2e4.","\ud480\uc774 \ub2e8\uacc4 2: \uc774\uc81c \uad6c\ud55c '\uc774'\uc778 '$x = 3 \\rightarrow x^2 = 9$'\ub97c \uc0b4\ud3b4\ubd05\uc2dc\ub2e4. $x$\uac00 $3$\uc774\uba74 $x^2$\uc740 \ubc18\ub4dc\uc2dc $3^2 = 9$\uac00 \ub418\ubbc0\ub85c, \uc774 \uba85\uc81c\ub294 \ucc38\uc785\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc8fc\uc5b4\uc9c4 \uba85\uc81c\ub294 \uac70\uc9d3\uc774\uc9c0\ub9cc, \uadf8 '\uc774'\ub294 \ucc38\uc774 \ub418\ub294 \uacbd\uc6b0\uc784\uc744 \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uba85\uc81c\uc640 \uadf8 \uc774\ub294 \uac01\uac01 \ub3c5\ub9bd\uc801\uc73c\ub85c \ucc38\uacfc \uac70\uc9d3\uc744 \ud310\ubcc4\ud574\uc57c \ud569\ub2c8\ub2e4."],ai0),"\uc774",B.r)],ai2),"\uc774",B.r)],ai3),s3,s3,s3,s3,"concept_\uc774",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5592 > \uba85\uc81c > \uba85\uc81c\uc758\uc5ed\uacfc\ub300\uc6b0 > \uc774",q7,"\uc774",s3)
q8=A.a(["\ub300\uc218","\uc218\uc5f4","\ud569\uc758\uae30\ud638\uc2dc\uadf8\ub9c8","\uc2dc\uadf8\ub9c8\uacf5\uc2dd"],ai0)
q8=A.ay(s2,A.a([A.aA(A.a(["\ub300\uc218 > \uc218\uc5f4 > \ud569\uc758\uae30\ud638\uc2dc\uadf8\ub9c8 > \uc2dc\uadf8\ub9c8\uacf5\uc2dd \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uc218\uc5f4\uc758 \ud569\uc744 \ub098\ud0c0\ub0b4\ub294 \uae30\ud638\uc778 \uc2dc\uadf8\ub9c8($\\sum$)\ub294 \ubcf5\uc7a1\ud55c \uc218\uc5f4\uc758 \ud569\uc744 \uac04\uacb0\ud558\uac8c \ud45c\ud604\ud558\uae30 \uc704\ud574 \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \uc2dc\uadf8\ub9c8 \uae30\ud638 \uc544\ub798\uc5d0\ub294 \ubcc0\uc218\uc640 \uc2dc\uc791 \uac12\uc744, \uc704\uc5d0\ub294 \ub05d \uac12\uc744 \uc801\uc5b4 \uc218\uc5f4\uc758 \ud56d\ub4e4\uc744 \uc5b4\ub514\ubd80\ud130 \uc5b4\ub514\uae4c\uc9c0 \ub354\ud560\uc9c0 \uba85\uc2dc\ud569\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \uc218\uc5f4 $a_n$\uc758 \uccab\uc9f8 \ud56d\ubd80\ud130 \uc81c$n$\ud56d\uae4c\uc9c0\uc758 \ud569\uc740 $\\sum_{k=1}^{n} a_k$\uc640 \uac19\uc774 \ub098\ud0c0\ub0b4\uba70, \uc774\ub294 $a_1 + a_2 + \\dots + a_n$\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4.","\uc2dc\uadf8\ub9c8\ub294 \ud569\uc758 \uc131\uc9c8\uc5d0 \ub530\ub77c \uba87 \uac00\uc9c0 \uc911\uc694\ud55c \uacf5\uc2dd\ub4e4\uc744 \uac00\uc9d1\ub2c8\ub2e4. \uac00\uc7a5 \uae30\ubcf8\uc774 \ub418\ub294 \uacf5\uc2dd\uc740 \uc790\uc5f0\uc218\uc758 \uac70\ub4ed\uc81c\uacf1\uc758 \ud569\uc785\ub2c8\ub2e4. \uccab\uc9f8, \uc790\uc5f0\uc218 $k$\uc758 \ud569\uc740 $$\\sum_{k=1}^{n} k = \\frac{n(n+1)}{2}$$ \uc774\uace0, \ub458\uc9f8, \uc81c\uacf1\uc758 \ud569\uc740 $$\\sum_{k=1}^{n} k^2 = \\frac{n(n+1)(2n+1)}{6}$$ \uc785\ub2c8\ub2e4. \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc138\uc81c\uacf1\uc758 \ud569\uc740 $$\\sum_{k=1}^{n} k^3 = \\left\\{ \\frac{n(n+1)}{2} \\right\\}^2$$ \uc640 \uac19\uc774 \uc815\uc758\ub429\ub2c8\ub2e4.","\uc2dc\uadf8\ub9c8\ub294 \uc120\ud615\uc131\uc744 \uac00\uc9c0\uace0 \uc788\uc5b4, \uc0c1\uc218\ubc30\ub098 \ub367\uc148, \ube84\uc148\uc5d0 \ub300\ud574 \ubd84\ub9ac\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc989, $c$\uac00 \uc0c1\uc218\uc77c \ub54c $$\\sum_{k=1}^{n} c a_k = c \\sum_{k=1}^{n} a_k$$ \uac00 \uc131\ub9bd\ud558\uba70, $$\\sum_{k=1}^{n} (a_k \\pm b_k) = \\sum_{k=1}^{n} a_k \\pm \\sum_{k=1}^{n} b_k$$ \uc640 \uac19\uc774 \uac01\uac01\uc758 \ud569\uc73c\ub85c \ub098\ub204\uc5b4 \uacc4\uc0b0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub610\ud55c, \uc0c1\uc218 $c$\ub97c $n$\ubc88 \ub354\ud558\uba74 $$\\sum_{k=1}^{n} c = cn$$ \uc774 \ub41c\ub2e4\ub294 \uc810\ub3c4 \uae30\uc5b5\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc774\uc81c \uc608\uc81c\ub97c \ud1b5\ud574 \uc2dc\uadf8\ub9c8 \uacf5\uc2dd\uc744 \uc801\uc6a9\ud574 \ubd05\uc2dc\ub2e4. \ubb38\uc81c: $\\sum_{k=1}^{10} (2k + 3)$\uc758 \uac12\uc744 \uad6c\ud558\uc2dc\uc624. \uc774 \uc2dd\uc740 \uc2dc\uadf8\ub9c8\uc758 \uc131\uc9c8\uc744 \uc774\uc6a9\ud558\uc5ec \ub450 \ubd80\ubd84\uc73c\ub85c \ub098\ub20c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc989, $$\\sum_{k=1}^{10} 2k + \\sum_{k=1}^{10} 3$$ \uc73c\ub85c \ubd84\ub9ac\ud569\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uc0c1\uc218 2\ub97c \uc55e\uc73c\ub85c \ube7c\ub0b4\uba74 $2 \\sum_{k=1}^{10} k + \\sum_{k=1}^{10} 3$\uc774 \ub429\ub2c8\ub2e4.","\uc774\uc81c \uc704\uc5d0\uc11c \ubc30\uc6b4 \uacf5\uc2dd\uc744 \ub300\uc785\ud558\uc5ec \uacc4\uc0b0\ud569\ub2c8\ub2e4. \uccab \ubc88\uc9f8 \ud56d\uc740 $2 \\times \\frac{10(10+1)}{2} = 10 \\times 11 = 110$\uc774 \ub418\uace0, \ub450 \ubc88\uc9f8 \ud56d\uc740 \uc0c1\uc218\ub97c 10\ubc88 \ub354\ud558\ub294 \uac83\uc774\ubbc0\ub85c $3 \\times 10 = 30$\uc774 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc804\uccb4 \ud569\uc740 $110 + 30 = 140$\uc785\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uc2dc\uadf8\ub9c8 \uacf5\uc2dd\uc744 \ud65c\uc6a9\ud558\uba74 \uc77c\uc77c\uc774 \uc22b\uc790\ub97c \ub354\ud558\uc9c0 \uc54a\uace0\ub3c4 \ube60\ub974\uace0 \uc815\ud655\ud558\uac8c \uc218\uc5f4\uc758 \ud569\uc744 \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),ah1,B.r)],ai2),ah1,B.r)],ai3),s3,s3,s3,s3,"concept_\uc2dc\uadf8\ub9c8\uacf5\uc2dd",0,"",1,s3,B.n,"\ub300\uc218 > \uc218\uc5f4 > \ud569\uc758\uae30\ud638\uc2dc\uadf8\ub9c8 > \uc2dc\uadf8\ub9c8\uacf5\uc2dd",q8,ah1,s3)
q9=A.a(["\uacf5\ud1b5\uc218\ud5591","\ub2e4\ud56d\uc2dd","\ub098\uba38\uc9c0\uc815\ub9ac","\ub098\uba38\uc9c0\uc815\ub9ac\ud65c\uc6a9"],ai0)
q9=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5591 > \ub2e4\ud56d\uc2dd > \ub098\uba38\uc9c0\uc815\ub9ac > \ub098\uba38\uc9c0\uc815\ub9ac\ud65c\uc6a9 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\ub098\uba38\uc9c0\uc815\ub9ac\ub780 \ub2e4\ud56d\uc2dd $P(x)$\ub97c \uc77c\ucc28\uc2dd $x-a$\ub85c \ub098\ub204\uc5c8\uc744 \ub54c\uc758 \ub098\uba38\uc9c0\uac00 $P(a)$\uc640 \uac19\ub2e4\ub294 \ub9e4\uc6b0 \uc720\uc6a9\ud55c \uc131\uc9c8\uc785\ub2c8\ub2e4. \uc774\ub97c \ud65c\uc6a9\ud558\uba74 \ub2e4\ud56d\uc2dd\uc744 \uc2e4\uc81c\ub85c \ub098\ub204\uc9c0 \uc54a\uace0\ub3c4 \ub098\uba38\uc9c0\ub97c \ube60\ub974\uac8c \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub9cc\uc57d \ub2e4\ud56d\uc2dd $P(x)$\ub97c \uc774\ucc28\uc2dd $(x-a)(x-b)$\ub85c \ub098\ub204\ub294 \uacbd\uc6b0, \ub098\uba38\uc9c0\ub294 \uc77c\ucc28\uc2dd \ud615\ud0dc\uc778 $ax+b$\ub85c \uac00\uc815\ud558\uc5ec \ubb38\uc81c\ub97c \ud574\uacb0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub54c \ub098\ub204\ub294 \uc2dd\uc744 $P(x) = (x-a)(x-b)Q(x) + ax+b$\uc640 \uac19\uc774 \ud56d\ub4f1\uc2dd\uc73c\ub85c \ud45c\ud604\ud558\ub294 \uac83\uc774 \ud575\uc2ec\uc785\ub2c8\ub2e4.","\ub098\uba38\uc9c0\uc815\ub9ac\ub97c \ud65c\uc6a9\ud560 \ub54c \uac00\uc7a5 \uc911\uc694\ud55c \uac83\uc740 \ub098\ub204\ub294 \uc2dd\uc758 \uc778\uc218\ubd84\ud574 \uac00\ub2a5 \uc5ec\ubd80\uc785\ub2c8\ub2e4. \ub098\ub204\ub294 \uc2dd\uc774 $(x-a)^2$\uacfc \uac19\uc774 \uc644\uc804\uc81c\uacf1\uc2dd\uc778 \uacbd\uc6b0\uc5d0\ub294 \uc218\uce58\ub300\uc785\ubc95\uc744 \ud55c \ubc88\ub9cc \uc0ac\uc6a9\ud560 \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0, \ubbf8\ubd84\ubc95\uc744 \uc774\uc6a9\ud558\uac70\ub098 \uc2dd\uc744 \ubcc0\ud615\ud558\uc5ec \ub098\uba38\uc9c0 $R(x)$\ub97c \uad6c\ud569\ub2c8\ub2e4. \ub610\ud55c, \ub098\ub204\ub294 \uc2dd\uc774 \uc778\uc218\ubd84\ud574\ub418\uc9c0 \uc54a\ub294 \uc774\ucc28\uc2dd\uc77c \ub54c\ub294 \uc9c1\uc811\uc801\uc778 \ub300\uc785\ubcf4\ub2e4\ub294 \uacc4\uc218 \ube44\uad50\ubc95\uc774\ub098 \uc2dd\uc758 \uad6c\uc870\uc801 \ud2b9\uc9d5\uc744 \ud65c\uc6a9\ud558\uc5ec \ub098\uba38\uc9c0\ub97c \uacb0\uc815\ud558\uac8c \ub429\ub2c8\ub2e4.","\uc608\uc81c \ubb38\uc81c: \ub2e4\ud56d\uc2dd $P(x)$\ub97c $(x-1)$\ub85c \ub098\ub204\uba74 \ub098\uba38\uc9c0\uac00 2\uc774\uace0, $(x-2)$\ub85c \ub098\ub204\uba74 \ub098\uba38\uc9c0\uac00 3\uc785\ub2c8\ub2e4. \uc774\ub54c $P(x)$\ub97c $(x-1)(x-2)$\ub85c \ub098\ub208 \ub098\uba38\uc9c0\ub97c \uad6c\ud558\uc2dc\uc624. \uc774 \ubb38\uc81c\ub97c \ud480\uae30 \uc704\ud574 \uba3c\uc800 \ub098\uba38\uc9c0\uc815\ub9ac\uc5d0 \uc758\ud574 $P(1)=2$, $P(2)=3$\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uad6c\ud558\ub294 \ub098\uba38\uc9c0\ub97c $R(x)=ax+b$\ub77c\uace0 \ud558\uba74, $P(x) = (x-1)(x-2)Q(x) + ax+b$\ub77c\ub294 \ud56d\ub4f1\uc2dd\uc744 \uc138\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uc704 \ud56d\ub4f1\uc2dd\uc5d0 $x=1$\uacfc $x=2$\ub97c \ucc28\ub840\ub300\ub85c \ub300\uc785\ud558\uc5ec \uc5f0\ub9bd\ubc29\uc815\uc2dd\uc744 \ub9cc\ub4ed\ub2c8\ub2e4. $x=1$\uc744 \ub300\uc785\ud558\uba74 $P(1) = a(1) + b = 2$\uac00 \ub418\uace0, $x=2$\ub97c \ub300\uc785\ud558\uba74 $P(2) = a(2) + b = 3$\uc774 \ub429\ub2c8\ub2e4. \uc774 \ub450 \uc2dd\uc744 \uc5f0\ub9bd\ud558\uba74 $a+b=2$\uc640 $2a+b=3$\uc774 \ub098\uc635\ub2c8\ub2e4. \uc544\ub798 \uc2dd\uc5d0\uc11c \uc704 \uc2dd\uc744 \ube7c\uba74 $a=1$\uc744 \uc5bb\uace0, \uc774\ub97c \ub2e4\uc2dc \ub300\uc785\ud558\uba74 $b=1$\uc774 \ub428\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ub530\ub77c\uc11c \uc6b0\ub9ac\uac00 \uad6c\ud558\uace0\uc790 \ud558\ub294 \ub098\uba38\uc9c0 $R(x)$\ub294 $ax+b$\uc5d0 $a=1, b=1$\uc744 \ub300\uc785\ud55c $x+1$\uc774 \ub429\ub2c8\ub2e4. \uc774\ucc98\ub7fc \ub098\uba38\uc9c0\uc815\ub9ac\ub97c \ud65c\uc6a9\ud558\uba74 \ubcf5\uc7a1\ud55c \ub2e4\ud56d\uc2dd\uc758 \ub098\ub217\uc148 \uacfc\uc815\uc744 \uac70\uce58\uc9c0 \uc54a\uace0\ub3c4, \ub098\ub204\ub294 \uc2dd\uc758 \uadfc\uc744 \ub300\uc785\ud558\ub294 \uac83\ub9cc\uc73c\ub85c \ub098\uba38\uc9c0\ub97c \uc815\ud655\ud558\uac8c \ucc3e\uc544\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \ubc29\ubc95\uc740 \uace0\ub4f1 \uc218\ud559\uc5d0\uc11c \ub2e4\ud56d\uc2dd\uc758 \uc131\uc9c8\uc744 \uc774\ud574\ud558\uace0 \ubb38\uc81c\ub97c \ud6a8\uc728\uc801\uc73c\ub85c \ud574\uacb0\ud558\ub294 \ub370 \ud544\uc218\uc801\uc778 \ub3c4\uad6c\uc785\ub2c8\ub2e4."],ai0),ah2,B.r)],ai2),ah2,B.r)],ai3),s3,s3,s3,s3,"concept_\ub098\uba38\uc9c0\uc815\ub9ac\ud65c\uc6a9",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5591 > \ub2e4\ud56d\uc2dd > \ub098\uba38\uc9c0\uc815\ub9ac > \ub098\uba38\uc9c0\uc815\ub9ac\ud65c\uc6a9",q9,ah2,s3)
r0=A.a(["\uacf5\ud1b5\uc218\ud5592","\uc88c\ud45c\ud3c9\uba74","\uc9c1\uc120\uc758\ubc29\uc815\uc2dd","\uae30\uc6b8\uae30"],ai0)
r0=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \uc9c1\uc120\uc758\ubc29\uc815\uc2dd > \uae30\uc6b8\uae30 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uc88c\ud45c\ud3c9\uba74\uc5d0\uc11c \uc9c1\uc120\uc758 \uae30\uc6b8\uae30\ub294 \uc9c1\uc120\uc774 \uc5bc\ub9c8\ub098 \uac00\ud30c\ub974\uac8c \uae30\uc6b8\uc5b4\uc838 \uc788\ub294\uc9c0\ub97c \ub098\ud0c0\ub0b4\ub294 \ucc99\ub3c4\uc785\ub2c8\ub2e4. \uc9c1\uc120 \uc704\uc758 \uc11c\ub85c \ub2e4\ub978 \ub450 \uc810 $A(x_1, y_1)$\uacfc $B(x_2, y_2)$\ub97c \uc9c0\ub0a0 \ub54c, \uae30\uc6b8\uae30\ub294 '$x$\uc758 \uc99d\uac00\ub7c9\uc5d0 \ub300\ud55c $y$\uc758 \uc99d\uac00\ub7c9\uc758 \ube44\uc728'\ub85c \uc815\uc758\ud569\ub2c8\ub2e4. \uc989, $x$\uac12\uc774 $x_1$\uc5d0\uc11c $x_2$\ub85c \ubcc0\ud560 \ub54c $y$\uac12\uc774 $y_1$\uc5d0\uc11c $y_2$\ub85c \ubcc0\ud55c\ub2e4\uba74, \uae30\uc6b8\uae30 $m$\uc740 \ub2e4\uc74c\uacfc \uac19\uc740 \uacf5\uc2dd\uc73c\ub85c \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uae30\uc6b8\uae30 $m$\uc744 \uad6c\ud558\ub294 \uacf5\uc2dd\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$m = \\frac{y_2 - y_1}{x_2 - x_1} = \\frac{\\Delta y}{\\Delta x} \\quad (x_1 \\neq x_2)$$ \uc774 \uc2dd\uc5d0\uc11c \ubd84\ubaa8\uc778 $x_2 - x_1$\uc740 $x$\uc758 \ubcc0\ud654\ub7c9, \ubd84\uc790\uc778 $y_2 - y_1$\uc740 $y$\uc758 \ubcc0\ud654\ub7c9\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \ub9cc\uc57d $x_1 = x_2$\ub77c\uba74 \ubd84\ubaa8\uac00 0\uc774 \ub418\uc5b4 \uae30\uc6b8\uae30\ub97c \uc815\uc758\ud560 \uc218 \uc5c6\ub294\ub370, \uc774\ub294 \uc9c1\uc120\uc774 $y$\ucd95\uacfc \ud3c9\ud589\ud55c \uc218\uc9c1\uc120\uc778 \uacbd\uc6b0\ub97c \ub73b\ud569\ub2c8\ub2e4.","\uae30\uc6b8\uae30\uc758 \ubd80\ud638\ub294 \uc9c1\uc120\uc758 \ubc29\ud5a5\uc744 \uacb0\uc815\ud569\ub2c8\ub2e4. \uae30\uc6b8\uae30\uac00 \uc591\uc218($m > 0$)\uc774\uba74 \uc624\ub978\ucabd \uc704\ub85c \ud5a5\ud558\ub294 \uc9c1\uc120\uc774 \ub418\uace0, \uae30\uc6b8\uae30\uac00 \uc74c\uc218($m < 0$)\uc774\uba74 \uc624\ub978\ucabd \uc544\ub798\ub85c \ud5a5\ud558\ub294 \uc9c1\uc120\uc774 \ub429\ub2c8\ub2e4. \ub610\ud55c \uae30\uc6b8\uae30\uac00 0($m = 0$)\uc774\uba74 $x$\ucd95\uacfc \ud3c9\ud589\ud55c \uc218\ud3c9\uc120\uc774 \ub429\ub2c8\ub2e4. \uae30\uc6b8\uae30\uc758 \uc808\ub313\uac12\uc774 \ud074\uc218\ub85d \uc9c1\uc120\uc740 $y$\ucd95\uc5d0 \ub354 \uac00\uae5d\uac8c \uac00\ud30c\ub974\uac8c \uc11c \uc788\uac8c \ub429\ub2c8\ub2e4.","\uc608\uc81c: \ub450 \uc810 $A(1, 2)$\uc640 $B(3, 6)$\uc744 \uc9c0\ub098\ub294 \uc9c1\uc120\uc758 \uae30\uc6b8\uae30\ub97c \uad6c\ud574 \ubd05\uc2dc\ub2e4. \uba3c\uc800 \uacf5\uc2dd\uc5d0 \uac01 \uc810\uc758 \uc88c\ud45c\ub97c \ub300\uc785\ud569\ub2c8\ub2e4. \uc5ec\uae30\uc11c $x_1=1, y_1=2$\uc774\uace0 $x_2=3, y_2=6$\uc785\ub2c8\ub2e4. \uae30\uc6b8\uae30 $m$\uc740 \ub2e4\uc74c\uacfc \uac19\uc774 \uacc4\uc0b0\ub429\ub2c8\ub2e4. $$m = \\frac{6 - 2}{3 - 1} = \\frac{4}{2} = 2$$ \ub530\ub77c\uc11c \uc774 \uc9c1\uc120\uc758 \uae30\uc6b8\uae30\ub294 2\uc785\ub2c8\ub2e4.","\uc704\uc758 \uacb0\uacfc\uc5d0\uc11c \uae30\uc6b8\uae30\uac00 2\ub77c\ub294 \uac83\uc740 $x$\uac12\uc774 1\ub9cc\ud07c \uc99d\uac00\ud560 \ub54c $y$\uac12\uc740 2\ub9cc\ud07c \uc99d\uac00\ud55c\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4. \ub9cc\uc57d \uc810 $A$\uc5d0\uc11c \uc2dc\uc791\ud558\uc5ec $x$\ucd95 \ubc29\ud5a5\uc73c\ub85c 1\ub9cc\ud07c, $y$\ucd95 \ubc29\ud5a5\uc73c\ub85c 2\ub9cc\ud07c \uc774\ub3d9\ud558\uba74 \uc810 $(1+1, 2+2) = (2, 4)$\uc5d0 \ub3c4\ub2ec\ud558\uac8c \ub418\ub294\ub370, \uc774 \uc810 \uc5ed\uc2dc \ud574\ub2f9 \uc9c1\uc120 \uc704\uc5d0 \uc874\uc7ac\ud558\uac8c \ub429\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uae30\uc6b8\uae30\ub294 \uc9c1\uc120 \uc704\uc758 \uc784\uc758\uc758 \ub450 \uc810\uc744 \uc120\ud0dd\ud574\ub3c4 \ud56d\uc0c1 \uc77c\uc815\ud558\ub2e4\ub294 \uc131\uc9c8\uc744 \uac00\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4."],ai0),"\uae30\uc6b8\uae30",B.r)],ai2),"\uae30\uc6b8\uae30",B.r)],ai3),s3,s3,s3,s3,"concept_\uae30\uc6b8\uae30",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \uc9c1\uc120\uc758\ubc29\uc815\uc2dd > \uae30\uc6b8\uae30",r0,"\uae30\uc6b8\uae30",s3)
r1=A.a(["\ub300\uc218","\uc9c0\uc218\ud568\uc218","\uc9c0\uc218\ud568\uc218\uc758\uadf8\ub798\ud504"],ai0)
r1=A.ay(s2,A.a([A.aA(A.a(["\ub300\uc218 > \uc9c0\uc218\ud568\uc218 > \uc9c0\uc218\ud568\uc218\uc758\uadf8\ub798\ud504 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uc9c0\uc218\ud568\uc218\ub780 \ubcc0\uc218 $x$\uac00 \uc9c0\uc218\uc5d0 \uc788\ub294 \ud568\uc218\ub85c, \uc77c\ubc18\uc801\uc73c\ub85c $f(x) = a^x$ (\ub2e8, $a > 0, a \\neq 1$)\uc758 \uaf34\ub85c \ub098\ud0c0\ub0c5\ub2c8\ub2e4. \uc774\ub54c $a$\ub97c \ubc11\uc774\ub77c\uace0 \ud558\uba70, \ubc11\uc758 \uac12\uc5d0 \ub530\ub77c \uadf8\ub798\ud504\uc758 \ubaa8\uc591\uc774 \uacb0\uc815\ub429\ub2c8\ub2e4. $a > 1$\uc77c \ub54c\ub294 $x$\uac00 \ucee4\uc9c8\uc218\ub85d $y$\uac12\ub3c4 \uae09\uaca9\ud788 \ucee4\uc9c0\ub294 \uc99d\uac00\ud568\uc218\uac00 \ub418\uace0, $0 < a < 1$\uc77c \ub54c\ub294 $x$\uac00 \ucee4\uc9c8\uc218\ub85d $y$\uac12\uc774 0\uc5d0 \ud55c\uc5c6\uc774 \uac00\uae4c\uc6cc\uc9c0\ub294 \uac10\uc18c\ud568\uc218\uac00 \ub429\ub2c8\ub2e4.","\uc9c0\uc218\ud568\uc218 $y = a^x$\uc758 \uadf8\ub798\ud504\ub294 \uba87 \uac00\uc9c0 \uc911\uc694\ud55c \uc131\uc9c8\uc744 \uac00\uc9d1\ub2c8\ub2e4. \uccab\uc9f8, \ubaa8\ub4e0 \uc9c0\uc218\ud568\uc218\uc758 \uadf8\ub798\ud504\ub294 $x$\uac00 \ubb34\uc5c7\uc774\ub4e0 $a^0 = 1$\uc774 \ub418\ubbc0\ub85c \ud56d\uc0c1 \uc810 $(0, 1)$\uc744 \uc9c0\ub0a9\ub2c8\ub2e4. \ub458\uc9f8, $a^x$\ub294 \ud56d\uc0c1 \uc591\uc218\uc774\ubbc0\ub85c \uadf8\ub798\ud504\ub294 $x$\ucd95\ubcf4\ub2e4 \ud56d\uc0c1 \uc704\ucabd\uc5d0 \uadf8\ub824\uc9c0\uba70, $x$\ucd95($y=0$)\uc744 \uc810\uadfc\uc120\uc73c\ub85c \uac00\uc9d1\ub2c8\ub2e4. \uc14b\uc9f8, $x$\uac12\uc774 \uc99d\uac00\ud560 \ub54c $y$\uac12\ub3c4 \uc99d\uac00\ud558\uac70\ub098 \uac10\uc18c\ud558\ub294 \uc77c\ub300\uc77c \ub300\uc751 \ud568\uc218\uc774\ubbc0\ub85c \uc5ed\ud568\uc218\uac00 \uc874\uc7ac\ud569\ub2c8\ub2e4.","\uc9c0\uc218\ud568\uc218\uc758 \uadf8\ub798\ud504\ub97c \ud3c9\ud589\uc774\ub3d9\ud558\uac70\ub098 \ub300\uce6d\uc774\ub3d9\ud558\uba74 \ub354 \ub2e4\uc591\ud55c \ud615\ud0dc\ub97c \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 $y = a^x + q$\ub294 \uc6d0\ub798 \uadf8\ub798\ud504\ub97c $y$\ucd95 \ubc29\ud5a5\uc73c\ub85c $q$\ub9cc\ud07c \ud3c9\ud589\uc774\ub3d9\ud55c \uac83\uc774\uba70, \uc774\ub85c \uc778\ud574 \uc810\uadfc\uc120\ub3c4 $y = q$\ub85c \ubcc0\ud558\uac8c \ub429\ub2c8\ub2e4. \ub610\ud55c $y = a^{-x} = (1/a)^x$\ub294 $y$\ucd95\uc5d0 \ub300\ud558\uc5ec \ub300\uce6d\uc778 \uadf8\ub798\ud504\uac00 \ub418\uc5b4, \ubc11\uc758 \uc5ed\uc218 \uad00\uacc4\uac00 \uadf8\ub798\ud504\uc758 \ub300\uce6d\uc131\uc744 \uacb0\uc815\ud55c\ub2e4\ub294 \uc810\uc744 \uc774\ud574\ud558\ub294 \uac83\uc774 \uc911\uc694\ud569\ub2c8\ub2e4.","\uc608\uc81c: \ud568\uc218 $f(x) = 2^x - 1$\uc758 \uadf8\ub798\ud504\ub97c \uadf8\ub9ac\uace0 \uc810\uadfc\uc120\uc744 \uad6c\ud558\uc2dc\uc624. \uba3c\uc800 \uae30\ubcf8\ud615\uc778 $y = 2^x$\uc758 \uadf8\ub798\ud504\ub97c \uc0dd\uac01\ud569\ub2c8\ub2e4. \uc774 \uadf8\ub798\ud504\ub294 $(0, 1)$\uc744 \uc9c0\ub098\uace0 $x$\ucd95\uc744 \uc810\uadfc\uc120\uc73c\ub85c \uac00\uc9d1\ub2c8\ub2e4. \uc8fc\uc5b4\uc9c4 \ud568\uc218\ub294 \uc774\ub97c $y$\ucd95 \ubc29\ud5a5\uc73c\ub85c $-1$\ub9cc\ud07c \ud3c9\ud589\uc774\ub3d9\ud55c \uac83\uc774\ubbc0\ub85c, \ubaa8\ub4e0 \uc810\uc758 $y$\uc88c\ud45c\uc5d0\uc11c 1\uc744 \ube8d\ub2c8\ub2e4. \ub530\ub77c\uc11c $(0, 1)$\uc740 $(0, 0)$\uc73c\ub85c \uc774\ub3d9\ud569\ub2c8\ub2e4.","\ub2e8\uacc4\ubcc4 \ud480\uc774: 1\ub2e8\uacc4, \uae30\ubcf8 \uadf8\ub798\ud504 $y = 2^x$\ub97c \uadf8\ub9bd\ub2c8\ub2e4. 2\ub2e8\uacc4, \ud568\uc218\uc2dd $y = 2^x - 1$\uc744 \ud655\uc778\ud558\uc5ec \uadf8\ub798\ud504\ub97c \uc544\ub798\ub85c 1\ub9cc\ud07c \ub0b4\ub9bd\ub2c8\ub2e4. 3\ub2e8\uacc4, \uc6d0\ub798 \uc810\uadfc\uc120\uc774 $y = 0$\uc774\uc5c8\uc73c\ubbc0\ub85c, \ud3c9\ud589\uc774\ub3d9\uc5d0 \uc758\ud574 \uc0c8\ub85c\uc6b4 \uc810\uadfc\uc120\uc740 $y = -1$\uc774 \ub429\ub2c8\ub2e4. \uacb0\uacfc\uc801\uc73c\ub85c \uc774 \uadf8\ub798\ud504\ub294 \uc810 $(0, 0)$\uc744 \uc9c0\ub098\uba70 $y = -1$\uc744 \uc810\uadfc\uc120\uc73c\ub85c \ud558\ub294 \uc99d\uac00\ud558\ub294 \uace1\uc120\uc774 \ub429\ub2c8\ub2e4."],ai0),ah3,B.r)],ai2),ah3,B.r)],ai3),s3,s3,s3,s3,"concept_\uc9c0\uc218\ud568\uc218\uc758\uadf8\ub798\ud504",0,"",1,s3,B.n,"\ub300\uc218 > \uc9c0\uc218\ud568\uc218 > \uc9c0\uc218\ud568\uc218\uc758\uadf8\ub798\ud504",r1,ah3,s3)
r2=A.a(["\ubbf8\uc801\ubd84\u2160","\ud568\uc218\uc758\uadf9\ub300\uc640\uadf9\uc18c","\uadf9\ub313\uac12"],ai0)
r2=A.ay(s2,A.a([A.aA(A.a(["\ubbf8\uc801\ubd84\u2160 > \ud568\uc218\uc758\uadf9\ub300\uc640\uadf9\uc18c > \uadf9\ub313\uac12 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\ud568\uc218\uc758 \uadf9\ub313\uac12\uc774\ub780, \uc5b4\ub5a4 \uc5f4\ub9b0 \uad6c\uac04\uc5d0\uc11c \ud568\uc218 $f(x)$\uc758 \uac12\uc774 \uadf8 \uad6c\uac04\uc5d0 \uc18d\ud558\ub294 \ubaa8\ub4e0 $x$\uc5d0 \ub300\ud558\uc5ec $f(x) \\le f(a)$\ub97c \ub9cc\uc871\ud560 \ub54c, $f(a)$\ub97c \uadf8 \ud568\uc218\uac00 $x=a$\uc5d0\uc11c \uac00\uc9c0\ub294 \uadf9\ub313\uac12\uc774\ub77c\uace0 \uc815\uc758\ud569\ub2c8\ub2e4. \uc27d\uac8c \ub9d0\ud574, \uadf8\ub798\ud504\uac00 \uc8fc\ubcc0\ubcf4\ub2e4 \ubcfc\ub85d\ud558\uac8c \uc19f\uc544\uc624\ub978 '\uc0b0\ubd09\uc6b0\ub9ac'\uc640 \uac19\uc740 \uc9c0\uc810\uc758 \ub192\uc774\ub97c \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc774\ub54c \ud568\uc218\uac00 $x=a$\ub97c \ud3ec\ud568\ud558\ub294 \uc5b4\ub5a4 \uc791\uc740 \ubc94\uc704 \ub0b4\uc5d0\uc11c \uac00\uc7a5 \ud070 \uac12\uc744 \uac00\uc9c4\ub2e4\uba74, \uadf8 \uc9c0\uc810\uc744 \uadf9\ub300\uc810\uc774\ub77c\uace0 \ubd80\ub985\ub2c8\ub2e4.","\ud568\uc218 $f(x)$\uac00 \ubbf8\ubd84 \uac00\ub2a5\ud560 \ub54c, $x=a$\uc5d0\uc11c \uadf9\ub313\uac12\uc744 \uac00\uc9c0\uae30 \uc704\ud55c \ud544\uc694\uc870\uac74\uc740 $f'(a)=0$\uc785\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ubbf8\ubd84\uacc4\uc218\uac00 0\uc774\ub77c\uace0 \ud574\uc11c \ubc18\ub4dc\uc2dc \uadf9\ub313\uac12\uc774 \ub418\ub294 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4. \uc815\ud655\ud55c \ud310\ubcc4\uc744 \uc704\ud574\uc11c\ub294 $x=a$\ub97c \uae30\uc900\uc73c\ub85c \uc88c\uc6b0\uc5d0\uc11c\uc758 \ub3c4\ud568\uc218 \ubd80\ud638 \ubcc0\ud654\ub97c \uc0b4\ud3b4\uc57c \ud569\ub2c8\ub2e4. \uc989, $x=a$\uc758 \uc67c\ucabd\uc5d0\uc11c $f'(x) > 0$\uc774\uace0, \uc624\ub978\ucabd\uc5d0\uc11c $f'(x) < 0$\uc73c\ub85c \ubd80\ud638\uac00 \ubc14\ub010\ub2e4\uba74, \ud568\uc218 $f(x)$\ub294 $x=a$\uc5d0\uc11c \uc99d\uac00\ud558\ub2e4\uac00 \uac10\uc18c\ud558\uac8c \ub418\ubbc0\ub85c $f(a)$\ub294 \uadf9\ub313\uac12\uc774 \ub429\ub2c8\ub2e4.","\uc815\ub9ac\ud558\uc790\uba74, \uadf9\ub313\uac12\uc744 \ucc3e\uae30 \uc704\ud574\uc11c\ub294 \uba3c\uc800 \ub3c4\ud568\uc218 $f'(x)$\ub97c \uad6c\ud558\uc5ec $f'(x)=0$\uc774 \ub418\ub294 $x$\uc758 \uac12\uc744 \ucc3e\uc2b5\ub2c8\ub2e4. \uc774\ud6c4, \uadf8 \uc9c0\uc810\uc744 \uae30\uc900\uc73c\ub85c \ub3c4\ud568\uc218\uc758 \ubd80\ud638\uac00 \uc591(+)\uc5d0\uc11c \uc74c(-)\uc73c\ub85c \ubcc0\ud558\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uac83\uc774 \ud575\uc2ec\uc785\ub2c8\ub2e4. \uc774\ub7ec\ud55c \uc131\uc9c8\uc744 \uc774\uc6a9\ud558\uba74 \ubcf5\uc7a1\ud55c \ub2e4\ud56d\ud568\uc218\uc758 \uadf8\ub798\ud504 \uac1c\ud615\uc744 \uc815\ud655\ud558\uac8c \ud30c\uc545\ud558\uace0, \ud568\uc218\uc758 \ucd5c\ub313\uac12\uacfc \ucd5c\uc19f\uac12\uc744 \uad6c\ud558\ub294 \ubb38\uc81c\uae4c\uc9c0 \ud655\uc7a5\ud558\uc5ec \ud574\uacb0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc608\uc81c: \ud568\uc218 $f(x) = -x^3 + 3x^2 + 9x$\uc758 \uadf9\ub313\uac12\uc744 \uad6c\ud574\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \ud568\uc218\ub97c \ubbf8\ubd84\ud558\uc5ec \ub3c4\ud568\uc218\ub97c \uad6c\ud558\uba74 $f'(x) = -3x^2 + 6x + 9$\uac00 \ub429\ub2c8\ub2e4. \uadf9\ub300 \ub610\ub294 \uadf9\uc18c\uac00 \ub418\ub294 \uc9c0\uc810\uc744 \ucc3e\uae30 \uc704\ud574 $f'(x) = 0$\uc744 \ud480\uba74 $-3(x^2 - 2x - 3) = -3(x-3)(x+1) = 0$\uc774 \ub418\uc5b4, $x=-1$ \ub610\ub294 $x=3$\uc5d0\uc11c \ub3c4\ud568\uc218\uac00 0\uc774 \ub428\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c $x=-1$\uacfc $x=3$\uc744 \uae30\uc900\uc73c\ub85c \ub3c4\ud568\uc218\uc758 \ubd80\ud638\ub97c \uc870\uc0ac\ud569\ub2c8\ub2e4. $x < -1$\uc77c \ub54c $f'(x) < 0$, $-1 < x < 3$\uc77c \ub54c $f'(x) > 0$, $x > 3$\uc77c \ub54c $f'(x) < 0$\uc774 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c $x=-1$\uc5d0\uc11c\ub294 \uac10\uc18c\ud558\ub2e4\uac00 \uc99d\uac00\ud558\ubbc0\ub85c \uadf9\uc19f\uac12\uc744 \uac16\uace0, $x=3$\uc5d0\uc11c\ub294 \uc99d\uac00\ud558\ub2e4\uac00 \uac10\uc18c\ud558\ubbc0\ub85c \uadf9\ub313\uac12\uc744 \uac00\uc9d1\ub2c8\ub2e4. \ucd5c\uc885\uc801\uc73c\ub85c $x=3$\uc744 \uc6d0\ub798 \ud568\uc218\uc5d0 \ub300\uc785\ud558\uba74 $f(3) = -(3)^3 + 3(3)^2 + 9(3) = -27 + 27 + 27 = 27$\uc774 \ub418\uc5b4, \uad6c\ud558\ub294 \uadf9\ub313\uac12\uc740 $27$\uc785\ub2c8\ub2e4."],ai0),"\uadf9\ub313\uac12",B.r)],ai2),"\uadf9\ub313\uac12",B.r)],ai3),s3,s3,s3,s3,"concept_\uadf9\ub313\uac12",0,"",1,s3,B.n,"\ubbf8\uc801\ubd84\u2160 > \ud568\uc218\uc758\uadf9\ub300\uc640\uadf9\uc18c > \uadf9\ub313\uac12",r2,"\uadf9\ub313\uac12",s3)
r3=A.a(["\uacf5\ud1b5\uc218\ud5591","\uc774\ucc28\ubd80\ub4f1\uc2dd","\uc774\ucc28\ubd80\ub4f1\uc2dd\uc758\ud480\uc774"],ai0)
r3=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5591 > \uc774\ucc28\ubd80\ub4f1\uc2dd > \uc774\ucc28\ubd80\ub4f1\uc2dd\uc758\ud480\uc774 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uc774\ucc28\ubd80\ub4f1\uc2dd\uc774\ub780 \ubd80\ub4f1\uc2dd\uc758 \ubaa8\ub4e0 \ud56d\uc744 \uc88c\ubcc0\uc73c\ub85c \uc774\ud56d\ud558\uc5ec \uc815\ub9ac\ud588\uc744 \ub54c, \uc88c\ubcc0\uc774 $x$\uc5d0 \ub300\ud55c \uc774\ucc28\uc2dd\uc778 \ubd80\ub4f1\uc2dd\uc744 \ub9d0\ud569\ub2c8\ub2e4. \uc77c\ubc18\uc801\uc73c\ub85c $ax^2 + bx + c > 0$ (\ub610\ub294 $<, \\le, \\ge$)\uc758 \uaf34\ub85c \ub098\ud0c0\ub0b4\uba70, \uc5ec\uae30\uc11c $a, b, c$\ub294 \uc0c1\uc218\uc774\uace0 $a \\neq 0$\uc785\ub2c8\ub2e4. \uc774\ucc28\ubd80\ub4f1\uc2dd\uc744 \ud47c\ub2e4\ub294 \uac83\uc740 \ubd80\ub4f1\uc2dd\uc744 \ub9cc\uc871\ud558\ub294 $x$\uc758 \uac12\uc758 \ubc94\uc704\ub97c \uad6c\ud558\ub294 \uac83\uc744 \uc758\ubbf8\ud558\uba70, \uc774\ub294 \uc774\ucc28\ud568\uc218 $y = ax^2 + bx + c$\uc758 \uadf8\ub798\ud504\uac00 $x$\ucd95\ubcf4\ub2e4 \uc704\ucabd\uc5d0 \uc788\ub294\uc9c0, \uc544\ub798\ucabd\uc5d0 \uc788\ub294\uc9c0, \ud639\uc740 \ub9cc\ub098\ub294\uc9c0\ub97c \ud655\uc778\ud558\ub294 \uacfc\uc815\uacfc \uac19\uc2b5\ub2c8\ub2e4.","\uc774\ucc28\ubd80\ub4f1\uc2dd\uc744 \ud480\uae30 \uc704\ud574\uc11c\ub294 \uba3c\uc800 \uc774\ucc28\ubc29\uc815\uc2dd $ax^2 + bx + c = 0$\uc758 \ud574\ub97c \uad6c\ud574\uc57c \ud569\ub2c8\ub2e4. \uc774\ucc28\ubc29\uc815\uc2dd\uc758 \ub450 \uc2e4\uadfc\uc744 $\\alpha, \\beta$ (\ub2e8, $\\alpha < \\beta$)\ub77c\uace0 \ud560 \ub54c, $a > 0$\uc778 \uacbd\uc6b0 \ubd80\ub4f1\uc2dd\uc758 \ud574\ub294 \ub2e4\uc74c\uacfc \uac19\uc774 \uacb0\uc815\ub429\ub2c8\ub2e4. \uccab\uc9f8, $ax^2 + bx + c > 0$\uc758 \ud574\ub294 $x < \\alpha$ \ub610\ub294 $x > \\beta$\uc785\ub2c8\ub2e4. \ub458\uc9f8, $ax^2 + bx + c < 0$\uc758 \ud574\ub294 \ub450 \uadfc \uc0ac\uc774\uc778 $\\alpha < x < \\beta$\uac00 \ub429\ub2c8\ub2e4. \ub9cc\uc57d \ud310\ubcc4\uc2dd $D = b^2 - 4ac$\uac00 $0$\uc774\uac70\ub098 $0$\ubcf4\ub2e4 \uc791\ub2e4\uba74, \uadf8\ub798\ud504\uc758 \uc704\uce58 \uad00\uacc4\ub97c \uace0\ub824\ud558\uc5ec \ud574\uac00 \ubaa8\ub4e0 \uc2e4\uc218\uc774\uac70\ub098 \ud574\uac00 \uc874\uc7ac\ud558\uc9c0 \uc54a\ub294 \uacbd\uc6b0\ub97c \ub530\uc838\uc57c \ud569\ub2c8\ub2e4.","\uc608\ub97c \ub4e4\uc5b4 \uc774\ucc28\ubd80\ub4f1\uc2dd $x^2 - 5x + 6 < 0$\uc744 \ud480\uc5b4\ubd05\uc2dc\ub2e4. \uba3c\uc800 \uc88c\ubcc0\uc744 \uc778\uc218\ubd84\ud574\ud558\uba74 $(x - 2)(x - 3) < 0$\uc774 \ub429\ub2c8\ub2e4. \uc774\ub294 \uc774\ucc28\ud568\uc218 $y = x^2 - 5x + 6$\uc758 \uadf8\ub798\ud504\uac00 $x$\ucd95\uacfc \ub9cc\ub098\ub294 \ub450 \uc810\uc758 $x$\uc88c\ud45c\uac00 $2$\uc640 $3$\uc784\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. $x^2$\uc758 \uacc4\uc218\uac00 \uc591\uc218\uc774\ubbc0\ub85c \uc544\ub798\ub85c \ubcfc\ub85d\ud55c \ud3ec\ubb3c\uc120\uc774 \uadf8\ub824\uc9c0\uba70, \ud568\uc22b\uac12\uc774 $0$\ubcf4\ub2e4 \uc791\uc740 \uad6c\uac04\uc740 \ub450 \uad50\uc810 \uc0ac\uc774\uac00 \ub429\ub2c8\ub2e4.","\ub530\ub77c\uc11c \ubd80\ub4f1\uc2dd $x^2 - 5x + 6 < 0$\uc758 \ud574\ub294 $2 < x < 3$\uc785\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uc774\ucc28\ubd80\ub4f1\uc2dd\uc744 \ud480 \ub54c\ub294 \ud56d\uc0c1 \uc774\ucc28\ud56d\uc758 \uacc4\uc218\ub97c \uc591\uc218\ub85c \ub9de\ucd98 \ub4a4, \uc778\uc218\ubd84\ud574\ub97c \ud1b5\ud574 $x$\ucd95\uacfc\uc758 \uad50\uc810\uc744 \ucc3e\uace0, \uadf8\ub798\ud504\uc758 \uac1c\ud615\uc744 \uadf8\ub824 \ubd80\ub4f1\ud638\uc758 \ubc29\ud5a5\uc5d0 \ub9de\ub294 \ubc94\uc704\ub97c \uc120\ud0dd\ud558\ub294 \uac83\uc774 \uac00\uc7a5 \uc815\ud655\ud558\uace0 \ud6a8\uc728\uc801\uc778 \ubc29\ubc95\uc785\ub2c8\ub2e4.","\ub610 \ub2e4\ub978 \uc608\ub85c $x^2 - 4x + 4 \\le 0$\uc744 \ud480\uc5b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uc88c\ubcc0\uc744 \uc778\uc218\ubd84\ud574\ud558\uba74 $(x - 2)^2 \\le 0$\uc774 \ub429\ub2c8\ub2e4. \uc774\ucc28\ud568\uc218 $y = (x - 2)^2$\uc758 \uadf8\ub798\ud504\ub294 \uaf2d\uc9d3\uc810\uc774 $(2, 0)$\uc778 \uc544\ub798\ub85c \ubcfc\ub85d\ud55c \ud3ec\ubb3c\uc120\uc785\ub2c8\ub2e4. \uc774 \uadf8\ub798\ud504\ub294 $x=2$\uc77c \ub54c $0$\uc774 \ub418\uace0, \ub098\uba38\uc9c0 \ubaa8\ub4e0 $x$\uc5d0 \ub300\ud574\uc11c\ub294 \ud56d\uc0c1 $0$\ubcf4\ub2e4 \ud07d\ub2c8\ub2e4. \ubb38\uc81c\uc5d0\uc11c\ub294 $0$\ubcf4\ub2e4 \uc791\uac70\ub098 \uac19\uc740 \ubc94\uc704\ub97c \ucc3e\uc73c\ub77c\uace0 \ud588\uc73c\ubbc0\ub85c, \uc870\uac74\uc744 \ub9cc\uc871\ud558\ub294 \uac12\uc740 $x = 2$\ubfd0\uc785\ub2c8\ub2e4."],ai0),ah4,B.r)],ai2),ah4,B.r)],ai3),s3,s3,s3,s3,"concept_\uc774\ucc28\ubd80\ub4f1\uc2dd\uc758\ud480\uc774",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5591 > \uc774\ucc28\ubd80\ub4f1\uc2dd > \uc774\ucc28\ubd80\ub4f1\uc2dd\uc758\ud480\uc774",r3,ah4,s3)
r4=A.a(["\ub300\uc218","\uc218\uc5f4","\uc5ec\ub7ec\uac00\uc9c0\uc218\uc5f4\uc758\ud569","\uc790\uc5f0\uc218\uc758\uac70\ub4ed\uc81c\uacf1\uc758\ud569"],ai0)
r4=A.ay(s2,A.a([A.aA(A.a(["\ub300\uc218 > \uc218\uc5f4 > \uc5ec\ub7ec\uac00\uc9c0\uc218\uc5f4\uc758\ud569 > \uc790\uc5f0\uc218\uc758\uac70\ub4ed\uc81c\uacf1\uc758\ud569 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uc790\uc5f0\uc218\uc758 \uac70\ub4ed\uc81c\uacf1\uc758 \ud569\uc774\ub780 1\ubd80\ud130 n\uae4c\uc9c0\uc758 \uc790\uc5f0\uc218\ub97c \uac01\uac01 \uac70\ub4ed\uc81c\uacf1\ud558\uc5ec \ubaa8\ub450 \ub354\ud55c \uac12\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc218\uc5f4\uc758 \ud569\uc744 \ub098\ud0c0\ub0b4\ub294 \uae30\ud638\uc778 \uc2dc\uadf8\ub9c8($\\sum$)\ub97c \uc0ac\uc6a9\ud558\uc5ec \ud45c\ud604\ud558\uba70, \uac00\uc7a5 \ub300\ud45c\uc801\uc778 \uc138 \uac00\uc9c0 \uacf5\uc2dd\uc740 \uc790\uc5f0\uc218 \uadf8 \uc790\uccb4\uc758 \ud569, \uc81c\uacf1\uc758 \ud569, \uc138\uc81c\uacf1\uc758 \ud569\uc785\ub2c8\ub2e4. \uc774 \uacf5\uc2dd\ub4e4\uc740 \uc218\uc5f4\uc758 \uc77c\ubc18\ud56d\uc774 $k, k^2, k^3$\uc778 \uacbd\uc6b0\uc758 \ud569\uc744 \uad6c\ud558\ub294 \uacfc\uc815\uc5d0\uc11c \ub9e4\uc6b0 \uc720\uc6a9\ud558\uac8c \uc0ac\uc6a9\ub429\ub2c8\ub2e4.","\uccab \ubc88\uc9f8\ub85c 1\ubd80\ud130 $n$\uae4c\uc9c0\uc758 \uc790\uc5f0\uc218\uc758 \ud569\uc740 $$ \\sum_{k=1}^{n} k = \\frac{n(n+1)}{2} $$ \uc785\ub2c8\ub2e4. \ub450 \ubc88\uc9f8\ub85c \uc790\uc5f0\uc218\uc758 \uc81c\uacf1\uc758 \ud569\uc740 $$ \\sum_{k=1}^{n} k^2 = \\frac{n(n+1)(2n+1)}{6} $$ \uc774\uba70, \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uc790\uc5f0\uc218\uc758 \uc138\uc81c\uacf1\uc758 \ud569\uc740 $$ \\sum_{k=1}^{n} k^3 = \\left\\{ \\frac{n(n+1)}{2} \\right\\}^2 $$ \ub85c \uacc4\uc0b0\ub429\ub2c8\ub2e4. \uc774 \uacf5\uc2dd\ub4e4\uc740 \uc218\ud559\uc801 \uadc0\ub0a9\ubc95\uc744 \ud1b5\ud574 \uc99d\uba85\ud560 \uc218 \uc788\uc73c\uba70, \ubcf5\uc7a1\ud55c \uc218\uc5f4\uc758 \ud569\uc744 \uad6c\ud560 \ub54c \uae30\ubcf8\uc774 \ub418\ub294 \ub3c4\uad6c\uc785\ub2c8\ub2e4.","\uc774\uc81c \uc608\uc81c\ub97c \ud1b5\ud574 \uc9c1\uc811 \uc801\uc6a9\ud574 \ubd05\uc2dc\ub2e4. \uccab \ubc88\uc9f8 \ubb38\uc81c\ub294 '1\ubd80\ud130 10\uae4c\uc9c0\uc758 \uc81c\uacf1\uc758 \ud569\uc744 \uad6c\ud558\uc2dc\uc624'\uc785\ub2c8\ub2e4. \uc989, $1^2 + 2^2 + \\dots + 10^2$\uc758 \uac12\uc744 \uad6c\ud558\ub294 \uac83\uc785\ub2c8\ub2e4. \uc5ec\uae30\uc11c $n=10$\uc774\ubbc0\ub85c, \uc55e\uc11c \ubc30\uc6b4 \uc81c\uacf1\uc758 \ud569 \uacf5\uc2dd\uc744 \uadf8\ub300\ub85c \ub300\uc785\ud558\uba74 \ub429\ub2c8\ub2e4.","\ud480\uc774 \uacfc\uc815\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uacf5\uc2dd $$ \\sum_{k=1}^{n} k^2 = \\frac{n(n+1)(2n+1)}{6} $$ \uc5d0 $n=10$\uc744 \ub300\uc785\ud558\uba74, $$ \\frac{10(10+1)(2 \\times 10 + 1)}{6} = \\frac{10 \\times 11 \\times 21}{6} $$ \uc774 \ub429\ub2c8\ub2e4. \uc774\ub97c \uacc4\uc0b0\ud558\uba74 $$ \\frac{2310}{6} = 385 $$ \uac00 \ub418\uc5b4, 1\ubd80\ud130 10\uae4c\uc9c0\uc758 \uc81c\uacf1\uc758 \ud569\uc740 385\uc784\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ub450 \ubc88\uc9f8 \uc608\uc81c\ub85c '1\ubd80\ud130 5\uae4c\uc9c0\uc758 \uc138\uc81c\uacf1\uc758 \ud569\uc744 \uad6c\ud558\uc2dc\uc624'\ub97c \ud480\uc5b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uc774\ub294 $1^3 + 2^3 + 3^3 + 4^3 + 5^3$\uc744 \uacc4\uc0b0\ud558\ub294 \ubb38\uc81c\uc785\ub2c8\ub2e4. \uc138\uc81c\uacf1\uc758 \ud569 \uacf5\uc2dd\uc778 $$ \\sum_{k=1}^{n} k^3 = \\left\\{ \\frac{n(n+1)}{2} \\right\\}^2 $$ \uc5d0 $n=5$\ub97c \ub300\uc785\ud569\ub2c8\ub2e4.","\ub2e8\uacc4\ubcc4 \ud480\uc774\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uad04\ud638 \uc548\uc758 \uac12\uc744 \uacc4\uc0b0\ud558\uba74 $$ \\frac{5(5+1)}{2} = \\frac{5 \\times 6}{2} = 15 $$ \uc785\ub2c8\ub2e4. \uc774\uc81c \uc774 \uac12\uc744 \uc81c\uacf1\ud558\uba74 $$ 15^2 = 225 $$ \uac00 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c 1\ubd80\ud130 5\uae4c\uc9c0\uc758 \uc138\uc81c\uacf1\uc758 \ud569\uc740 225\uc785\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uacf5\uc2dd\uc744 \ud65c\uc6a9\ud558\uba74 \uc77c\uc77c\uc774 \ub354\ud558\uc9c0 \uc54a\uc544\ub3c4 \ube60\ub974\uace0 \uc815\ud655\ud558\uac8c \ud569\uc744 \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),ah5,B.r)],ai2),ah5,B.r)],ai3),s3,s3,s3,s3,"concept_\uc790\uc5f0\uc218\uc758\uac70\ub4ed\uc81c\uacf1\uc758\ud569",0,"",1,s3,B.n,"\ub300\uc218 > \uc218\uc5f4 > \uc5ec\ub7ec\uac00\uc9c0\uc218\uc5f4\uc758\ud569 > \uc790\uc5f0\uc218\uc758\uac70\ub4ed\uc81c\uacf1\uc758\ud569",r4,ah5,s3)
r5=A.a(["\uacf5\ud1b5\uc218\ud5592","\uba85\uc81c","\ucda9\ubd84\uc870\uac74\uacfc\ud544\uc694\uc870\uac74","\ud544\uc694\uc870\uac74"],ai0)
r5=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uba85\uc81c > \ucda9\ubd84\uc870\uac74\uacfc\ud544\uc694\uc870\uac74 > \ud544\uc694\uc870\uac74 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\ub450 \uc870\uac74 $p, q$\uc5d0 \ub300\ud558\uc5ec \uba85\uc81c '$p$\uc774\uba74 $q$\uc774\ub2e4($p \\implies q$)'\uac00 \ucc38\uc77c \ub54c, \uc6b0\ub9ac\ub294 $p$\ub97c $q$\uc774\uae30 \uc704\ud55c '\ucda9\ubd84\uc870\uac74'\uc774\ub77c\uace0 \ubd80\ub985\ub2c8\ub2e4. \ubc18\ub300\ub85c $q$\uc758 \uc785\uc7a5\uc5d0\uc11c\ub294 $p$\uac00 \ucc38\uc774 \ub418\uae30 \uc704\ud574 \ubc18\ub4dc\uc2dc \ub9cc\uc871\ud574\uc57c \ud558\ub294 \uc870\uac74\uc774 \ub418\ubbc0\ub85c, $q$\ub97c $p$\uc774\uae30 \uc704\ud55c '\ud544\uc694\uc870\uac74'\uc774\ub77c\uace0 \uc815\uc758\ud569\ub2c8\ub2e4. \uc989, $p \\implies q$\uac00 \ucc38\uc774\ub77c\ub294 \uac83\uc740 $p$\uac00 \uc77c\uc5b4\ub098\ub294 \uc0c1\ud669\uc774 $q$\uac00 \uc77c\uc5b4\ub098\ub294 \uc0c1\ud669\uc5d0 \ud3ec\ud568\ub41c\ub2e4\ub294 \ub73b\uc774\uba70, \uc774\ub54c $q$\ub294 $p$\ub97c \ubc1b\uc544\ub4e4\uc774\uae30 \uc704\ud55c \ub113\uc740 \uc6b8\ud0c0\ub9ac \uc5ed\ud560\uc744 \ud55c\ub2e4\uace0 \uc774\ud574\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ud544\uc694\uc870\uac74\uc744 \ud310\ubcc4\ud558\ub294 \ud575\uc2ec\uc740 \uc9c4\ub9ac\uc9d1\ud569 \uc0ac\uc774\uc758 \ud3ec\ud568 \uad00\uacc4\ub97c \ud655\uc778\ud558\ub294 \uac83\uc785\ub2c8\ub2e4. \ub450 \uc870\uac74 $p, q$\uc758 \uc9c4\ub9ac\uc9d1\ud569\uc744 \uac01\uac01 $P, Q$\ub77c\uace0 \ud560 \ub54c, $P \\subseteq Q$\uc774\uba74 \uba85\uc81c $p \\implies q$\ub294 \ucc38\uc774 \ub429\ub2c8\ub2e4. \uc774\ub54c $q$\ub294 $p$\uc774\uae30 \uc704\ud55c \ud544\uc694\uc870\uac74\uc785\ub2c8\ub2e4. \ub9cc\uc57d $P = Q$\uc778 \uacbd\uc6b0\uc5d0\ub294 $p$\ub294 $q$\uc774\uae30 \uc704\ud55c \ud544\uc694\ucda9\ubd84\uc870\uac74\uc774 \ub418\uba70, \uc774\ub294 \ud544\uc694\uc870\uac74\uc758 \uc815\uc758\ub97c \ub9cc\uc871\ud558\ub294 \ud2b9\uc218\ud55c \uacbd\uc6b0\ub77c\uace0 \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc608\ub97c \ub4e4\uc5b4, '$x$\ub294 4\uc758 \ubc30\uc218\uc774\ub2e4'\ub77c\ub294 \uc870\uac74 $p$\uc640 '$x$\ub294 2\uc758 \ubc30\uc218\uc774\ub2e4'\ub77c\ub294 \uc870\uac74 $q$\ub97c \uc0dd\uac01\ud574 \ubd05\uc2dc\ub2e4. 4\uc758 \ubc30\uc218\ub294 \ubaa8\ub450 2\uc758 \ubc30\uc218\uc774\ubbc0\ub85c $p \\implies q$\ub294 \ucc38\uc785\ub2c8\ub2e4. \uc774\ub54c $p$\uc758 \uc9c4\ub9ac\uc9d1\ud569 $P = \\{4, 8, 12, \\dots\\}$\ub294 $q$\uc758 \uc9c4\ub9ac\uc9d1\ud569 $Q = \\{2, 4, 6, 8, \\dots\\}$\uc5d0 \ud3ec\ud568\ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c $q$\ub294 $p$\uc774\uae30 \uc704\ud55c \ud544\uc694\uc870\uac74\uc774 \ub429\ub2c8\ub2e4. \uc989, $x$\uac00 4\uc758 \ubc30\uc218\uac00 \ub418\ub824\uba74 \uc77c\ub2e8 2\uc758 \ubc30\uc218\ub77c\ub294 \uc870\uac74\uc774 \ubc18\ub4dc\uc2dc \ud544\uc694\ud558\uae30 \ub54c\ubb38\uc5d0 \uc774\ub7ec\ud55c \uc774\ub984\uc774 \ubd99\uc740 \uac83\uc785\ub2c8\ub2e4.","\ub2e4\uc74c \uc608\uc81c\ub97c \ud1b5\ud574 \ud544\uc694\uc870\uac74\uc744 \ud655\uc778\ud574 \ubd05\uc2dc\ub2e4. \ub450 \uc870\uac74 $p: x > 3$, $q: x > 1$\uc5d0 \ub300\ud558\uc5ec $q$\uac00 $p$\uc774\uae30 \uc704\ud55c \ud544\uc694\uc870\uac74\uc778\uc9c0 \ud310\ubcc4\ud574 \ubcf4\uc138\uc694. \uba3c\uc800 \uac01 \uc870\uac74\uc758 \uc9c4\ub9ac\uc9d1\ud569\uc744 \uc218\uc9c1\uc120 \uc704\uc5d0 \ub098\ud0c0\ub0b4\uba74 $P = \\{x \\mid x > 3\\}$\uc774\uace0 $Q = \\{x \\mid x > 1\\}$\uc785\ub2c8\ub2e4. \uc218\uc9c1\uc120\uc5d0\uc11c $P$\uc758 \ubc94\uc704\uac00 $Q$\uc758 \ubc94\uc704 \uc548\uc5d0 \uc644\uc804\ud788 \ud3ec\ud568\ub418\ub294\uc9c0 \ud655\uc778\ud558\uba74, $3$\ubcf4\ub2e4 \ud070 \ubaa8\ub4e0 \uc218\ub294 $1$\ubcf4\ub2e4 \ud06c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ub530\ub77c\uc11c \uc9c4\ub9ac\uc9d1\ud569 \uc0ac\uc774\uc758 \uad00\uacc4\ub294 $P \\subset Q$\uac00 \uc131\ub9bd\ud569\ub2c8\ub2e4. \uc774\ub294 \uba85\uc81c '$p \\implies q$'\uac00 \ucc38\uc784\uc744 \uc758\ubbf8\ud558\uba70, \uc815\uc758\uc5d0 \ub530\ub77c $q$\ub294 $p$\uc774\uae30 \uc704\ud55c \ud544\uc694\uc870\uac74\uc774 \ub429\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uc5b4\ub5a4 \uc870\uac74\uc774 \ub2e4\ub978 \uc870\uac74\uc758 \ubc94\uc704\ub97c \ud3ec\ud568\ud558\uace0 \uc788\uc744 \ub54c, \uadf8 \ud3ec\ud568\ud558\ub294 \ucabd\uc758 \uc870\uac74\uc774 \ubc14\ub85c '\ud544\uc694\uc870\uac74'\uc774 \ub41c\ub2e4\ub294 \uc810\uc744 \uae30\uc5b5\ud558\uba74 \ubb38\uc81c\ub97c \uc27d\uac8c \ud574\uacb0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),ah6,B.r)],ai2),ah6,B.r)],ai3),s3,s3,s3,s3,"concept_\ud544\uc694\uc870\uac74",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5592 > \uba85\uc81c > \ucda9\ubd84\uc870\uac74\uacfc\ud544\uc694\uc870\uac74 > \ud544\uc694\uc870\uac74",r5,ah6,s3)
r6=A.a(["\uacf5\ud1b5\uc218\ud5591","\ub2e4\ud56d\uc2dd","\uc778\uc218\uc815\ub9ac","\uc778\uc218\uc815\ub9ac\uc99d\uba85"],ai0)
r6=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5591 > \ub2e4\ud56d\uc2dd > \uc778\uc218\uc815\ub9ac > \uc778\uc218\uc815\ub9ac\uc99d\uba85 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(['[   "\uc778\uc218\uc815\ub9ac\ub780 \ub2e4\ud56d\uc2dd $P(x)$\uc5d0 \ub300\ud558\uc5ec $P(a)=0$\uc774\uba74, \ub2e4\ud56d\uc2dd $P(x)$\ub294 \uc77c\ucc28\uc2dd $(x-a)$\ub97c \uc778\uc218\ub85c \uac00\uc9c4\ub2e4\ub294 \uc815\ub9ac\uc785\ub2c8\ub2e4. \uc774\ub294 \ub098\uba38\uc9c0\uc815\ub9ac\uc758 \ud2b9\uc218\ud55c \uacbd\uc6b0\ub85c, \ub2e4\ud56d\uc2dd\uc744 $(x-a)$\ub85c \ub098\ub204\uc5c8\uc744 \ub54c \ub098\uba38\uc9c0\uac00 0\uc774 \ub418\ub294 \uc0c1\ud669\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc989, \uc5b4\ub5a4 \ub2e4\ud56d\uc2dd\uc758 \uac12\uc744 0\uc73c\ub85c \ub9cc\ub4dc\ub294 $x$\uc758 \uac12\uc744 \ucc3e\uc73c\uba74, \uadf8 \ub2e4\ud56d\uc2dd\uc744 \ub098\ub204\uc5b4\ub5a8\uc5b4\uc9c0\uac8c \ud558\ub294 \uc77c\ucc28\uc2dd \uc778\uc218\ub97c \ubc14\ub85c \ucc3e\uc544\ub0bc \uc218 \uc788\ub2e4\ub294 \ub9e4\uc6b0 \uac15\ub825\ud55c \ub3c4\uad6c\uc785\ub2c8\ub2e4.",   "\uc778\uc218\uc815\ub9ac\ub97c \uc99d\uba85\ud558\uae30 \uc704\ud574\uc11c\ub294 \ub2e4\ud56d\uc2dd\uc758 \ub098\ub217\uc148\uc5d0 \ub300\ud55c \ud56d\ub4f1\uc2dd\uc744 \uc774\uc6a9\ud569\ub2c8\ub2e4. \ub2e4\ud56d\uc2dd $P(x)$\ub97c $(x-a)$\ub85c \ub098\ub204\uc5c8\uc744 \ub54c\uc758 \ubaab\uc744 $Q(x)$, \ub098\uba38\uc9c0\ub97c $R$\uc774\ub77c\uace0 \ud558\uba74, \ub098\ub217\uc148\uc758 \uc6d0\ub9ac\uc5d0 \uc758\ud574 $$P(x) = (x-a)Q(x) + R$$\uc774\ub77c\ub294 \uc2dd\uc744 \uc138\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub54c \ub098\ub204\ub294 \uc2dd\uc774 \uc77c\ucc28\uc2dd\uc774\ubbc0\ub85c \ub098\uba38\uc9c0\ub294 \uc0c1\uc218 $R$\uc774 \ub429\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uc591\ubcc0\uc5d0 $x=a$\ub97c \ub300\uc785\ud558\uba74 $$P(a) = (a-a)Q(a) + R = 0 \\cdot Q(a) + R = R$$\uc774 \ub418\uc5b4, \uacb0\uad6d $R=P(a)$\ub77c\ub294 \ub098\uba38\uc9c0\uc815\ub9ac\uac00 \uc131\ub9bd\ud568\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.",   "\uc774\uc81c \uc778\uc218\uc815\ub9ac\ub97c \uc99d\uba85\ud574 \ubd05\uc2dc\ub2e4. \ub9cc\uc57d $P(a)=0$\uc774\ub77c\uba74, \uc704\uc5d0\uc11c \uad6c\ud55c \uc2dd $R=P(a)$\uc5d0 \uc758\ud574 \ub098\uba38\uc9c0 $R$\uc740 0\uc774 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \ucc98\uc74c\uc758 \ud56d\ub4f1\uc2dd\uc740 $$P(x) = (x-a)Q(x)$$\uac00 \ub429\ub2c8\ub2e4. \uc774 \uc2dd\uc740 $P(x)$\uac00 $(x-a)$\uc640 $Q(x)$\uc758 \uacf1\uc73c\ub85c \ub098\ud0c0\ub0b4\uc5b4\uc9d0\uc744 \uc758\ubbf8\ud558\ubbc0\ub85c, $(x-a)$\ub294 $P(x)$\uc758 \uc778\uc218\uac00 \ub429\ub2c8\ub2e4. \uc5ed\uc73c\ub85c $P(x)$\uac00 $(x-a)$\ub97c \uc778\uc218\ub85c \uac00\uc9c4\ub2e4\uba74 $P(x)=(x-a)Q(x)$\uc774\ubbc0\ub85c $x=a$\ub97c \ub300\uc785\ud588\uc744 \ub54c $P(a)=0$\uc774 \ub428\uc740 \uc790\uba85\ud569\ub2c8\ub2e4.",   "\uc608\uc81c: \ub2e4\ud56d\uc2dd $P(x) = x^3 - 2x^2 - x + 2$\uac00 $(x-1)$\uc744 \uc778\uc218\ub85c \uac00\uc9c0\ub294\uc9c0 \uc778\uc218\uc815\ub9ac\ub97c \uc774\uc6a9\ud558\uc5ec \ud655\uc778\ud574 \ubd05\uc2dc\ub2e4. \uba3c\uc800 \uc778\uc218\uc815\ub9ac\uc5d0 \ub530\ub77c $x=1$\uc744 \ub2e4\ud56d\uc2dd\uc5d0 \ub300\uc785\ud558\uc5ec $P(1)$\uc758 \uac12\uc744 \uad6c\ud569\ub2c8\ub2e4. $$P(1) = 1^3 - 2(1)^2 - 1 + 2 = 1 - 2 - 1 + 2 = 0$$\uc785\ub2c8\ub2e4. $P(1)=0$\uc774\ubbc0\ub85c, \uc778\uc218\uc815\ub9ac\uc5d0 \uc758\ud574 $P(x)$\ub294 $(x-1)$\uc744 \uc778\uc218\ub85c \uac00\uc9d0\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4.",   "\uc704\uc5d0\uc11c \ud655\uc778\ud55c \uc778\uc218\ub97c \ubc14\ud0d5\uc73c\ub85c \ub2e4\ud56d\uc2dd\uc744 \uc644\uc804\ud788 \uc778\uc218\ubd84\ud574\ud574 \ubd05\uc2dc\ub2e4. $P(x) = x^3 - 2x^2 - x + 2$\ub97c $(x-1)$\ub85c \ub098\ub204\uba74 \ubaab\uc740 \uc870\ub9bd\uc81c\ubc95\uc744 \ud1b5\ud574 \uad6c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uacc4\uc218 1, -2, -1, 2\ub97c 1\ub85c \ub098\ub204\uba74 \ubaab\uc758 \uacc4\uc218\ub294 1, -1, -2\uac00 \ub418\uc5b4 \ubaab\uc740 $x^2 - x - 2$\uac00 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c $$P(x) = (x-1)(x^2 - x - 2)$$\uac00 \ub418\uba70, \uc774\ucc28\uc2dd $x^2 - x - 2$\ub97c \ub2e4\uc2dc \uc778\uc218\ubd84\ud574\ud558\uba74 $$(x-1)(x-2)(x+1)$$\uc774\ub77c\ub294 \ucd5c\uc885 \uacb0\uacfc\ub97c \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4." ]'],ai0),ah7,B.r)],ai2),ah7,B.r)],ai3),s3,s3,s3,s3,"concept_\uc778\uc218\uc815\ub9ac\uc99d\uba85",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5591 > \ub2e4\ud56d\uc2dd > \uc778\uc218\uc815\ub9ac > \uc778\uc218\uc815\ub9ac\uc99d\uba85",r6,ah7,s3)
r7=A.a(["\uacf5\ud1b5\uc218\ud5592","\uc88c\ud45c\ud3c9\uba74","\uc9c1\uc120\uc758\ubc29\uc815\uc2dd","\uc808\ud3b8"],ai0)
r7=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \uc9c1\uc120\uc758\ubc29\uc815\uc2dd > \uc808\ud3b8 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uc88c\ud45c\ud3c9\uba74 \uc704\uc5d0\uc11c \uc9c1\uc120\uc774 x\ucd95\uc774\ub098 y\ucd95\uacfc \ub9cc\ub098\ub294 \uc810\uc744 '\uc808\ud3b8'\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4. \uad6c\uccb4\uc801\uc73c\ub85c, \uc9c1\uc120\uc774 x\ucd95\uacfc \ub9cc\ub098\ub294 \uc810\uc758 x\uc88c\ud45c\ub97c 'x\uc808\ud3b8'\uc774\ub77c \ud558\uace0, y\ucd95\uacfc \ub9cc\ub098\ub294 \uc810\uc758 y\uc88c\ud45c\ub97c 'y\uc808\ud3b8'\uc774\ub77c\uace0 \ubd80\ub985\ub2c8\ub2e4. x\ucd95 \uc704\uc758 \ubaa8\ub4e0 \uc810\uc740 y\uc88c\ud45c\uac00 0\uc774\ubbc0\ub85c, x\uc808\ud3b8\uc744 \uad6c\ud558\ub824\uba74 \uc9c1\uc120\uc758 \ubc29\uc815\uc2dd\uc5d0 $y=0$\uc744 \ub300\uc785\ud558\uc5ec x\uc758 \uac12\uc744 \ucc3e\uc73c\uba74 \ub429\ub2c8\ub2e4. \ubc18\ub300\ub85c y\ucd95 \uc704\uc758 \ubaa8\ub4e0 \uc810\uc740 x\uc88c\ud45c\uac00 0\uc774\ubbc0\ub85c, y\uc808\ud3b8\uc744 \uad6c\ud558\ub824\uba74 $x=0$\uc744 \ub300\uc785\ud558\uc5ec y\uc758 \uac12\uc744 \ucc3e\uc2b5\ub2c8\ub2e4.","\uc9c1\uc120\uc758 \ubc29\uc815\uc2dd\uc744 $ax + by + c = 0$ (\ub2e8, $a, b \\neq 0$)\uc758 \ud615\ud0dc\ub85c \ub098\ud0c0\ub0bc \ub54c, x\uc808\ud3b8\uc740 $y=0$\uc744 \ub300\uc785\ud55c $ax + c = 0$\uc5d0\uc11c $x = -\\frac{c}{a}$\uac00 \ub429\ub2c8\ub2e4. \ub9c8\ucc2c\uac00\uc9c0\ub85c y\uc808\ud3b8\uc740 $x=0$\uc744 \ub300\uc785\ud55c $by + c = 0$\uc5d0\uc11c $y = -\\frac{c}{b}$\uac00 \ub429\ub2c8\ub2e4. \ub9cc\uc57d \uc9c1\uc120\uc774 x\uc808\ud3b8\uc744 $p$, y\uc808\ud3b8\uc744 $q$\ub77c\uace0 \ud560 \ub54c, \uc774 \uc9c1\uc120\uc758 \ubc29\uc815\uc2dd\uc740 \ub2e4\uc74c\uacfc \uac19\uc740 \uc544\ub984\ub2e4\uc6b4 \uacf5\uc2dd\uc73c\ub85c \ud45c\ud604\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. $$\\frac{x}{p} + \\frac{y}{q} = 1 \\quad (p \\neq 0, q \\neq 0)$$","\uc808\ud3b8\uc740 \uc9c1\uc120\uc758 \uadf8\ub798\ud504\ub97c \uadf8\ub9b4 \ub54c \ub9e4\uc6b0 \uc720\uc6a9\ud569\ub2c8\ub2e4. \ub450 \uc810\ub9cc \uc54c\uba74 \uc9c1\uc120\uc744 \uadf8\ub9b4 \uc218 \uc788\ub294\ub370, x\uc808\ud3b8\uacfc y\uc808\ud3b8\uc740 \uc88c\ud45c\ucd95 \uc704\uc5d0\uc11c \uc27d\uac8c \ucc3e\uc744 \uc218 \uc788\ub294 \ub450 \uc810\uc774\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc9c1\uc120\uc758 \ubc29\uc815\uc2dd\uc744 \uc54c\uba74 \uc808\ud3b8\uc744 \uad6c\ud558\uc5ec \uc88c\ud45c\ud3c9\uba74\uc5d0 \uc810\uc744 \ucc0d\uace0, \uadf8 \ub450 \uc810\uc744 \uace7\uac8c \uc5f0\uacb0\ud558\uae30\ub9cc \ud558\uba74 \uadf8\ub798\ud504\ub97c \ube60\ub974\uac8c \uc644\uc131\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\uc81c \uc774 \uac1c\ub150\uc744 \ud65c\uc6a9\ud558\uc5ec \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud480\uc5b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4.","\uc608\uc81c: \uc9c1\uc120 $2x - 3y + 6 = 0$\uc758 x\uc808\ud3b8\uacfc y\uc808\ud3b8\uc744 \uac01\uac01 \uad6c\ud558\uace0, \uc774\ub97c \uc774\uc6a9\ud558\uc5ec \uadf8\ub798\ud504\ub97c \uadf8\ub824\ubd05\uc2dc\ub2e4. \uba3c\uc800 x\uc808\ud3b8\uc744 \uad6c\ud558\uae30 \uc704\ud574 $y=0$\uc744 \ub300\uc785\ud558\uba74 $2x - 3(0) + 6 = 0$\uc774 \ub429\ub2c8\ub2e4. \uc774\ub97c \uc815\ub9ac\ud558\uba74 $2x = -6$\uc774 \ub418\uc5b4 $x = -3$\uc744 \uc5bb\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c x\uc808\ud3b8\uc740 $-3$\uc774\uba70, \uadf8\ub798\ud504\ub294 \uc810 $(-3, 0)$\uc744 \uc9c0\ub0a9\ub2c8\ub2e4.","\ub2e4\uc74c\uc73c\ub85c y\uc808\ud3b8\uc744 \uad6c\ud558\uae30 \uc704\ud574 $x=0$\uc744 \ub300\uc785\ud558\uba74 $2(0) - 3y + 6 = 0$\uc774 \ub429\ub2c8\ub2e4. \uc774\ub97c \uc815\ub9ac\ud558\uba74 $-3y = -6$\uc774 \ub418\uc5b4 $y = 2$\ub97c \uc5bb\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c y\uc808\ud3b8\uc740 $2$\uc774\uba70, \uadf8\ub798\ud504\ub294 \uc810 $(0, 2)$\ub97c \uc9c0\ub0a9\ub2c8\ub2e4. \uacb0\ub860\uc801\uc73c\ub85c \uc774 \uc9c1\uc120\uc740 \uc88c\ud45c\ud3c9\uba74\uc5d0\uc11c $(-3, 0)$\uacfc $(0, 2)$\ub77c\ub294 \ub450 \uc810\uc744 \uc9c0\ub098\ub294 \uc9c1\uc120\uc774 \ub429\ub2c8\ub2e4. \uc774 \ub450 \uc810\uc744 \uc790\ub97c \ub300\uace0 \uc5f0\uacb0\ud558\uba74 \uc6b0\ub9ac\uac00 \uc6d0\ud558\ub294 \uc9c1\uc120\uc758 \uadf8\ub798\ud504\uac00 \uc644\uc131\ub429\ub2c8\ub2e4."],ai0),"\uc808\ud3b8",B.r)],ai2),"\uc808\ud3b8",B.r)],ai3),s3,s3,s3,s3,"concept_\uc808\ud3b8",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \uc9c1\uc120\uc758\ubc29\uc815\uc2dd > \uc808\ud3b8",r7,"\uc808\ud3b8",s3)
r8=A.a(["\uacf5\ud1b5\uc218\ud5592","\uc88c\ud45c\ud3c9\uba74","\uc9c1\uc120\uc758\ubc29\uc815\uc2dd","\uc810\uae30\uc6b8\uae30\ud615"],ai0)
r8=A.ay(s2,A.a([A.aA(A.a(["\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \uc9c1\uc120\uc758\ubc29\uc815\uc2dd > \uc810\uae30\uc6b8\uae30\ud615 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\uc9c1\uc120\uc758 \ubc29\uc815\uc2dd\uc744 \uad6c\ud558\ub294 \uac00\uc7a5 \uae30\ubcf8\uc801\uc774\uba74\uc11c\ub3c4 \uac15\ub825\ud55c \ubc29\ubc95\uc778 '\uc810\uae30\uc6b8\uae30\ud615'\uc5d0 \ub300\ud574 \uc54c\uc544\ubd05\uc2dc\ub2e4. \uc88c\ud45c\ud3c9\uba74 \uc704\uc5d0\uc11c \ud55c \uc810 $(x_1, y_1)$\uc744 \uc9c0\ub098\uace0 \uae30\uc6b8\uae30\uac00 $m$\uc778 \uc9c1\uc120\uc740 \uc720\uc77c\ud558\uac8c \uacb0\uc815\ub429\ub2c8\ub2e4. \uc774 \uc9c1\uc120 \uc704\uc5d0 \uc788\ub294 \uc784\uc758\uc758 \uc810\uc744 $(x, y)$\ub77c\uace0 \ud560 \ub54c, \ub450 \uc810 $(x_1, y_1)$\uacfc $(x, y)$\ub97c \uc787\ub294 \uc120\ubd84\uc758 \uae30\uc6b8\uae30\ub294 \ud56d\uc0c1 $m$\uc73c\ub85c \uc77c\uc815\ud558\ub2e4\ub294 \uc131\uc9c8\uc744 \uc774\uc6a9\ud569\ub2c8\ub2e4.","\uae30\uc6b8\uae30\uc758 \uc815\uc758\uc5d0 \ub530\ub77c $\\frac{y - y_1}{x - x_1} = m$\uc774\ub77c\ub294 \uc2dd\uc744 \uc138\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \uc2dd\uc758 \uc591\ubcc0\uc5d0 $(x - x_1)$\uc744 \uacf1\ud558\uc5ec \uc815\ub9ac\ud558\uba74, \uc810\uae30\uc6b8\uae30\ud615\uc758 \ud575\uc2ec \uacf5\uc2dd\uc778 $$y - y_1 = m(x - x_1)$$\uc744 \uc5bb\uac8c \ub429\ub2c8\ub2e4. \uc774 \uacf5\uc2dd\uc740 \uc9c1\uc120 \uc704\uc758 \ud55c \uc810\uacfc \uae30\uc6b8\uae30\ub9cc \uc54c\uba74 \uc9c1\uc120\uc758 \ubc29\uc815\uc2dd\uc744 \uc989\uc2dc \uc644\uc131\ud560 \uc218 \uc788\uac8c \ud574\uc8fc\ub294 \ub9e4\uc6b0 \uc720\uc6a9\ud55c \ub3c4\uad6c\uc785\ub2c8\ub2e4.","\uc774 \uacf5\uc2dd\uc758 \uc131\uc9c8\uc744 \uc0b4\ud3b4\ubcf4\uba74, $m$\uc740 \uc9c1\uc120\uc758 \uac00\ud30c\ub978 \uc815\ub3c4\ub97c \ub098\ud0c0\ub0b4\ub294 \uae30\uc6b8\uae30\uc774\uace0, $(x_1, y_1)$\uc740 \uc9c1\uc120\uc774 \ubc18\ub4dc\uc2dc \ud1b5\uacfc\ud558\ub294 \uace0\uc815\ub41c \uc810\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \ub9cc\uc57d \uae30\uc6b8\uae30\uac00 \uc8fc\uc5b4\uc9c0\uc9c0 \uc54a\uace0 \uc11c\ub85c \ub2e4\ub978 \ub450 \uc810\uc774 \uc8fc\uc5b4\uc84c\ub354\ub77c\ub3c4, \ub450 \uc810\uc744 \uc774\uc6a9\ud574 \uae30\uc6b8\uae30\ub97c \uba3c\uc800 \uad6c\ud55c \ub4a4 \uc774 \uacf5\uc2dd\uc5d0 \ub300\uc785\ud558\uba74 \uc5b4\ub5a4 \uc9c1\uc120\uc758 \ubc29\uc815\uc2dd\uc774\ub77c\ub3c4 \uc27d\uac8c \ucc3e\uc544\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uc608\uc81c\ub97c \ud1b5\ud574 \uc9c1\uc811 \uc801\uc6a9\ud574 \ubd05\uc2dc\ub2e4. '\uc810 $(2, -3)$\uc744 \uc9c0\ub098\uace0 \uae30\uc6b8\uae30\uac00 $4$\uc778 \uc9c1\uc120\uc758 \ubc29\uc815\uc2dd\uc744 \uad6c\ud558\uc2dc\uc624.'\ub77c\ub294 \ubb38\uc81c\ub97c \ud480\uc5b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uba3c\uc800 \uc810\uae30\uc6b8\uae30\ud615 \uacf5\uc2dd $$y - y_1 = m(x - x_1)$$\uc5d0 \uc8fc\uc5b4\uc9c4 \uac12 $x_1 = 2$, $y_1 = -3$, $m = 4$\ub97c \uac01\uac01 \ub300\uc785\ud569\ub2c8\ub2e4.","\uacf5\uc2dd\uc5d0 \ub300\uc785\ud558\uba74 $$y - (-3) = 4(x - 2)$$\uac00 \ub429\ub2c8\ub2e4. \uc774\ub97c \uc815\ub9ac\ud558\uba74 $$y + 3 = 4x - 8$$\uc774 \ub418\uba70, \ucd5c\uc885\uc801\uc73c\ub85c \uc0c1\uc218\ud56d\uc744 \uc6b0\ubcc0\uc73c\ub85c \uc774\ud56d\ud558\uc5ec \uc815\ub9ac\ud558\uba74 $$y = 4x - 11$$\uc774\ub77c\ub294 \uc9c1\uc120\uc758 \ubc29\uc815\uc2dd\uc744 \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uc810\uae30\uc6b8\uae30\ud615 \uacf5\uc2dd\uc744 \ud65c\uc6a9\ud558\uba74 \ubcf5\uc7a1\ud55c \uacfc\uc815 \uc5c6\uc774 \uc9c1\uc120\uc758 \uc2dd\uc744 \uac04\uacb0\ud558\uac8c \uc644\uc131\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),ah8,B.r)],ai2),ah8,B.r)],ai3),s3,s3,s3,s3,"concept_\uc810\uae30\uc6b8\uae30\ud615",0,"",1,s3,B.n,"\uacf5\ud1b5\uc218\ud5592 > \uc88c\ud45c\ud3c9\uba74 > \uc9c1\uc120\uc758\ubc29\uc815\uc2dd > \uc810\uae30\uc6b8\uae30\ud615",r8,ah8,s3)
r9=A.a(["\ubbf8\uc801\ubd84\u2160","\ud568\uc218\uc758\uadf9\ub300\uc640\uadf9\uc18c","\uadf9\uc19f\uac12"],ai0)
r9=A.ay(s2,A.a([A.aA(A.a(["\ubbf8\uc801\ubd84\u2160 > \ud568\uc218\uc758\uadf9\ub300\uc640\uadf9\uc18c > \uadf9\uc19f\uac12 \uac1c\ub150 \ud559\uc2b5"],ai0),B.E,A.a([A.aB(s3,B.n,A.a(["\ud568\uc218\uc758 \uadf9\uc19f\uac12\uc774\ub780, \ud568\uc218 $f(x)$\uc758 \uadf8\ub798\ud504\uc5d0\uc11c \ud2b9\uc815 \uad6c\uac04\uc744 \uad00\ucc30\ud588\uc744 \ub54c \uc8fc\ubcc0\uc758 \ub2e4\ub978 \uc810\ub4e4\ubcf4\ub2e4 \ud568\uc22b\uac12\uc774 \uc791\uac70\ub098 \uac19\uc740 \uc9c0\uc810\uc758 \uac12\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc218\ud559\uc801\uc73c\ub85c \ub354 \uc5c4\ubc00\ud558\uac8c \uc815\uc758\ud558\uba74, \uc5b4\ub5a4 \uc5f4\ub9b0 \uad6c\uac04\uc5d0 \uc18d\ud558\ub294 \ubaa8\ub4e0 $x$\uc5d0 \ub300\ud558\uc5ec $f(x) \\ge f(a)$\ub97c \ub9cc\uc871\ud558\ub294 \uc810 $a$\uac00 \uc874\uc7ac\ud560 \ub54c, \ud568\uc22b\uac12 $f(a)$\ub97c \ud568\uc218 $f(x)$\uc758 \uadf9\uc19f\uac12\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4. \uc989, \uadf9\uc19f\uac12\uc740 \ubc18\ub4dc\uc2dc \ucd5c\uc19f\uac12\uc77c \ud544\uc694\ub294 \uc5c6\uc73c\uba70, \uad6d\uc18c\uc801\uc73c\ub85c \uc8fc\ubcc0\ubcf4\ub2e4 \uc544\ub798\ub85c \ubcfc\ub85d\ud558\uac8c \ub0b4\ub824\uac04 '\uace8\uc9dc\uae30'\uc758 \ub192\uc774\ub77c\uace0 \uc774\ud574\ud558\uba74 \uc27d\uc2b5\ub2c8\ub2e4.","\ud568\uc218\uac00 \ubbf8\ubd84 \uac00\ub2a5\ud560 \ub54c, \uadf9\uc19f\uac12\uc744 \ucc3e\ub294 \ubc29\ubc95\uc740 \ub3c4\ud568\uc218 $f'(x)$\ub97c \ud65c\uc6a9\ud558\ub294 \uac83\uc785\ub2c8\ub2e4. \ub9cc\uc57d $x=a$\uc5d0\uc11c \ud568\uc218 $f(x)$\uac00 \uadf9\uc19f\uac12\uc744 \uac00\uc9c4\ub2e4\uba74, \uadf8 \uc9c0\uc810\uc5d0\uc11c\uc758 \uc811\uc120\uc758 \uae30\uc6b8\uae30\ub294 $0$\uc774 \ub418\uc5b4\uc57c \ud558\ubbc0\ub85c $f'(a)=0$\uc744 \ub9cc\uc871\ud569\ub2c8\ub2e4. \uc774\ub54c $x=a$\ub97c \uae30\uc900\uc73c\ub85c \uc67c\ucabd\uc5d0\uc11c\ub294 \ub3c4\ud568\uc218\uc758 \ubd80\ud638\uac00 \uc74c\uc218($f'(x) < 0$)\uc600\ub2e4\uac00 \uc624\ub978\ucabd\uc5d0\uc11c \uc591\uc218($f'(x) > 0$)\ub85c \ubc14\ub00c\ub294 \ud604\uc0c1\uc774 \ub098\ud0c0\ub0a9\ub2c8\ub2e4. \uc774\ub97c \ud1b5\ud574 \uc6b0\ub9ac\ub294 \ub3c4\ud568\uc218\uc758 \ubd80\ud638 \ubcc0\ud654\ub97c \uad00\ucc30\ud558\uc5ec \uadf9\uc19f\uac12\uc744 \uc815\ud655\ud788 \ud310\ubcc4\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc815\ub9ac\ud558\uc790\uba74, \uadf9\uc19f\uac12\uc744 \uad6c\ud558\ub294 \uacfc\uc815\uc740 \ud06c\uac8c \ub450 \ub2e8\uacc4\ub85c \ub098\ub269\ub2c8\ub2e4. \uccab\uc9f8, \ubc29\uc815\uc2dd $f'(x)=0$\uc744 \ud480\uc5b4 \ubbf8\ubd84\uacc4\uc218\uac00 $0$\uc774 \ub418\ub294 $x$\uc758 \uac12\ub4e4\uc744 \ucc3e\uc2b5\ub2c8\ub2e4. \ub458\uc9f8, \uadf8 \uc9c0\uc810\uc758 \uc88c\uc6b0\uc5d0\uc11c \ub3c4\ud568\uc218\uc758 \ubd80\ud638\uac00 '\uc74c\uc5d0\uc11c \uc591'\uc73c\ub85c \ubcc0\ud558\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4. \ub9cc\uc57d \ubd80\ud638\uac00 \ubc14\ub010\ub2e4\uba74 \uadf8 \uc9c0\uc810\uc758 \ud568\uc22b\uac12 $f(a)$\uac00 \ubc14\ub85c \uadf9\uc19f\uac12\uc774 \ub429\ub2c8\ub2e4. \uc774 \uc6d0\ub9ac\ub294 \ubcf5\uc7a1\ud55c \ub2e4\ud56d\ud568\uc218\uc758 \uadf8\ub798\ud504 \uac1c\ud615\uc744 \ud30c\uc545\ud558\ub294 \ub370 \ub9e4\uc6b0 \uc911\uc694\ud55c \ub3c4\uad6c\uac00 \ub429\ub2c8\ub2e4.","\uc608\uc81c \ubb38\uc81c: \ud568\uc218 $f(x) = x^3 - 3x + 2$\uc758 \uadf9\uc19f\uac12\uc744 \uad6c\ud558\uc2dc\uc624. \uba3c\uc800 \uc8fc\uc5b4\uc9c4 \ud568\uc218\ub97c \ubbf8\ubd84\ud558\uba74 $f'(x) = 3x^2 - 3$\uc774 \ub429\ub2c8\ub2e4. \uadf9\uac12\uc774 \ub420 \ud6c4\ubcf4\ub97c \ucc3e\uae30 \uc704\ud574 $f'(x) = 0$\uc744 \uacc4\uc0b0\ud558\uba74 $3(x^2 - 1) = 0$\uc774 \ub418\uc5b4 $x = 1$ \ub610\ub294 $x = -1$\uc774\ub77c\ub294 \ub450 \uac1c\uc758 \uc784\uacc4\uc810\uc744 \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uac01 \uc9c0\uc810\uc5d0\uc11c\uc758 \ubd80\ud638 \ubcc0\ud654\ub97c \uc0b4\ud3b4\ubd05\uc2dc\ub2e4. $x < -1$\uc77c \ub54c $f'(x) > 0$, $-1 < x < 1$\uc77c \ub54c $f'(x) < 0$, $x > 1$\uc77c \ub54c $f'(x) > 0$\uc774 \ub429\ub2c8\ub2e4. $x=1$\uc778 \uc9c0\uc810\uc744 \ubcf4\uba74 \ub3c4\ud568\uc218\uc758 \ubd80\ud638\uac00 \uc74c\uc218\uc5d0\uc11c \uc591\uc218\ub85c \ubc14\ub00c\uace0 \uc788\uc73c\ubbc0\ub85c, $x=1$\uc5d0\uc11c \uadf9\uc19f\uac12\uc744 \uac00\uc9d0\uc744 \uc54c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub530\ub77c\uc11c \uad6c\ud558\ub294 \uadf9\uc19f\uac12\uc740 $f(1)$\uc744 \uacc4\uc0b0\ud558\uc5ec \uc5bb\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.","\ucd5c\uc885 \uacc4\uc0b0\uc744 \uc218\ud589\ud558\uba74 $f(1) = 1^3 - 3(1) + 2 = 1 - 3 + 2 = 0$\uc774 \ub429\ub2c8\ub2e4. \ub530\ub77c\uc11c \ud568\uc218 $f(x) = x^3 - 3x + 2$\uc758 \uadf9\uc19f\uac12\uc740 $0$\uc785\ub2c8\ub2e4. \uc774\ucc98\ub7fc \ub3c4\ud568\uc218\uc758 \ubd80\ud638 \ubcc0\ud654\ub97c \uaf3c\uaf3c\ud788 \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc744 \ub4e4\uc774\uba74, \uc5b4\ub5a4 \ud568\uc218\uac00 \uc8fc\uc5b4\uc9c0\ub354\ub77c\ub3c4 \uc815\ud655\ud558\uac8c \uadf9\uc19f\uac12\uc744 \ucc3e\uc544\ub0bc \uc218 \uc788\uc2b5\ub2c8\ub2e4."],ai0),"\uadf9\uc19f\uac12",B.r)],ai2),"\uadf9\uc19f\uac12",B.r)],ai3),s3,s3,s3,s3,"concept_\uadf9\uc19f\uac12",0,"",1,s3,B.n,"\ubbf8\uc801\ubd84\u2160 > \ud568\uc218\uc758\uadf9\ub300\uc640\uadf9\uc18c > \uadf9\uc19f\uac12",r9,"\uadf9\uc19f\uac12",s3)
